window.__CH("c11",["<div class=\"hw\">F, f</div><div class=\"pos\"><i>indecl n</i></div><div class=\"def\">ラテン語アルファベットの第6字.</div>\r\n","<div class=\"hw\">F., f.</div><div class=\"def\">《略》=<a href=\"entry://fīlius\">filius</a>;<a href=\"entry://fīlia\">filia</a>;<a href=\"entry://factus\">factus</a>;fecit(⇒ <a href=\"entry://faciō\">facio</a>).</div>\r\n","<div class=\"hw\">faba</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">豆.</div>\r\n","<div class=\"hw\">Fabaris</div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\">ファバリス《Tiberis 川の支流;Sabini 族の土地を流れる;現 Farfa》.</div>\r\n","<div class=\"hw\">faber<SUP>1</SUP></div><div class=\"pos\">-brī, <i>m</i></div><div class=\"def\"><num>①</num> 職人</div><div class=\"ex\"><i>～ tignarius</i> (<author>C<small>IC</small></author>)<span class=\"ext\">大工</span></div><div class=\"ex\"><i>～ ferrarius</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">鍛冶屋.</span></div><div class=\"def\"><num>②</num> 工兵.</div><hr><div class=\"hw\">faber<SUP>2</SUP></div><div class=\"pos\">-bra -brum, <i>adj</i></div><div class=\"def\">巧みな, 熟練した;巧妙に作られた.</div>\r\n","<div class=\"hw\">Faberius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ファベリウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">Faberiānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Faberius の.</div>\r\n","<div class=\"hw\">Fabius<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ファビウス《ローマ人の氏族名;特に (1) <i>Q. ～ Pictor</i>, 第2次 Poeni 戦争時代の歴史家.(2) <i>Q. ～ Maximus Cunctator</i>, 第2次 Poeni 戦争時の独裁官(前203年没)》.</div><hr><div class=\"hw\">Fabius<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Fabiānus\">Fabianus</a>.</div>\r\n","<div class=\"hw\">Fabiānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Fabius の.</div>\r\n","<div class=\"hw\">fabrica</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[faber]</div><div class=\"def\"><num>①</num> 技術, わざ;建築術.</div><div class=\"def\"><num>②</num> 作業場, 仕事場.</div><div class=\"def\"><num>③</num> 作ること, 作り方.</div><div class=\"def\"><num>④</num> 策略.</div>\r\n","<div class=\"hw\">fabricensis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[fabrica]</div><div class=\"def\">武具製造者.</div>\r\n","<div class=\"hw\">Fabricius<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ファブリキウス《ローマ人の氏族名;特に <i>C. ～ Luscinus</i>, 前282年と278年の執政官;Epirus の王 Pyrrhus との戦いで有名;清廉潔白の模範とされる》.</div><hr><div class=\"hw\">Fabricius<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Fabriciānus\">Fabricianus</a>.</div>\r\n","<div class=\"hw\">fabricius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[fabrica]</div><div class=\"def\">煙で乾かした.</div>\r\n","<div class=\"hw\">Fabriciānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Fabricius の.</div>\r\n","<div class=\"hw\">fabricor</div><div class=\"pos\">-ārī -ātus sum, <i>tr dep</i></div><div class=\"ori\">[fabrica]</div><div class=\"def\"><num>①</num> 製作する, 形づくる.</div><div class=\"def\"><num>②</num> 建造する.</div><div class=\"def\"><num>③</num> 工夫[考案]する.</div>\r\n","<div class=\"hw\">fabricula</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f dim</i></div><div class=\"ori\">[fabrica]</div><div class=\"def\">小さな仕事場.</div>\r\n","<div class=\"hw\">fabricātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[fabricor]</div><div class=\"def\"><num>①</num> 製作, 製造.</div><div class=\"def\"><num>②</num> (弁論の)構成.</div>\r\n","<div class=\"hw\">fabricātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[fabricor]</div><div class=\"def\">製作者.</div>\r\n","<div class=\"hw\">fabricātrix</div><div class=\"pos\">-īcis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[fabricator]</div><div class=\"def\">製作者《女性》.</div>\r\n","<div class=\"hw\">fabricātōrius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://fabricātor\">fabricātor</a>]</div><div class=\"def\">創造的な</div><div class=\"ex\"><i>potentia fabricatoria</i> (<author>A<small>UG</small></author>)<span class=\"ext\">産出的な力.</span></div>\r\n","<div class=\"hw\">fabricō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"def\">=<a href=\"entry://fabricor\">fabricor</a>.</div>\r\n","<div class=\"hw\">fabrificātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[faber/facio]</div><div class=\"def\">製作, 製造.</div>\r\n","<div class=\"hw\">fabriō</div><div class=\"pos\">-īre -īvī, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[faber]</div><div class=\"def\">製作する.</div>\r\n","<div class=\"hw\">Fabrāteria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ファブラーテリア《Latium にあった Volsci 族の町》.</div>\r\n","<div class=\"hw\">Fabrāternī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">Fabrateria の住民.</div>\r\n","<div class=\"hw\">fabrē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[faber]</div><div class=\"def\">巧みに.</div>\r\n","<div class=\"hw\">fabrēfacere</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://fabrēfaciō\">fabrefacio</a>.</div>\r\n","<div class=\"hw\">fabrēfaciō</div><div class=\"pos\">-cere -fēcī -factum, <i>tr</i></div><div class=\"ori\">[faber/facio]</div><div class=\"def\">巧みに作る.</div>\r\n","<div class=\"hw\">fabrēfactus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://fabrēfaciō\">fabrefacio</a>.</div>\r\n","<div class=\"hw\">fabrēfēcī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://fabrēfaciō\">fabrefacio</a>.</div>\r\n","<div class=\"hw\">fabrīlia</div><div class=\"pos\">-ium, <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://fabrīlis\">fabrīlis</a>]</div><div class=\"def\">大工道具.</div>\r\n","<div class=\"hw\">fabrīlis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[faber]</div><div class=\"def\">職人の;熟練した.</div>\r\n","<div class=\"hw\">fabulus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[faba]</div><div class=\"def\">小さな豆.</div>\r\n","<div class=\"hw\">fabāceus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://faba\">faba</a>]</div><div class=\"def\">豆の.</div>\r\n","<div class=\"hw\">fabāginus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://fabālis\">fabalis</a>.</div>\r\n","<div class=\"hw\">fabālia</div><div class=\"pos\">-ium, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://fabālis\">fabālis</a>]</div><div class=\"def\">豆の茎.</div>\r\n","<div class=\"hw\">fabālis</div><div class=\"pos\">-is -e, adj</div><div class=\"ori\">[faba]</div><div class=\"def\">豆の.</div>\r\n","<div class=\"hw\">fabāria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[fabarius]</div><div class=\"def\">《碑》豆商人《女性》.</div>\r\n","<div class=\"hw\">fabārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[faba]</div><div class=\"def\">豆の.</div><hr><div class=\"hw\">fabārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">《碑》豆商人.</div>\r\n","<div class=\"hw\">fabātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[faba]</div><div class=\"def\">豆から作った;豆の入った.</div>\r\n","<div class=\"hw\">fabātārium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↓<a href=\"entry://fabātus\">fabātus</a>]</div><div class=\"def\">豆のスープを入れる器.</div>\r\n","<div class=\"hw\">fac</div><div class=\"pos\">2 <i>sg impr pr</i></div><div class=\"def\">⇒<a href=\"entry://faciō\">facio</a>.</div>\r\n","<div class=\"hw\">facere</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://faciō\">facio</a>.</div>\r\n","<div class=\"hw\">facessī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">=<a href=\"entry://facessīvī\">facessivi</a>.</div>\r\n","<div class=\"hw\">facessītus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://facessō\">facesso</a>.</div>\r\n","<div class=\"hw\">facessīvī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://facessō\">facesso</a>.</div>\r\n","<div class=\"hw\">facessō</div><div class=\"pos\">-ere -sīvī [-sī] -sītum, <i>tr</i>, <i>intr intens</i></div><div class=\"ori\">[facio]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>tr</i>)</div><div class=\"def\"><num>①</num> 果たす, 実行する.</div><div class=\"def\"><num>②</num> ひき起こす 〈alci alqd〉</div><div class=\"ex\"><i>negotium alci facessere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ある人に面倒をかける</span></div><div class=\"ex\"><i>alci periculum facessere</i> (<author>T<small>AC</small></author>)<span class=\"ext\">ある人を危険に陥れる.</span></div><div class=\"def\"><num>③</num> </div><div class=\"ex\"><i>rem facessere</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">(訴訟を)起こす.</span></div><div class=\"def\"><num0>Ⅱ</num0> (<i>intr</i>)遠ざかる, 立ち去る 〈(ex)re〉.</div>\r\n","<div class=\"hw\">facile</div><div class=\"pos\"><i>adv</i>(<i>neut</i>)</div><div class=\"ori\">[↓<a href=\"entry://facilis\">facilis</a>]</div><div class=\"def\"><num>①</num> 容易に, たやすく.</div><div class=\"def\"><num>②</num> 当然, 疑いなく</div><div class=\"ex\"><i>non [haud] ～</i> (<author>C<small>IC</small></author>)<span class=\"ext\">かろうじて, ほとんど...なく.</span></div><div class=\"def\"><num>③</num> 喜んで, 快く.</div><div class=\"def\"><num>④</num> 快適に.</div><div class=\"def\"><num>⑤</num> 軽率に, 不注意に.</div>\r\n","<div class=\"hw\">facilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[facio]</div><div class=\"def\"><num>①</num> (実行・入手が)容易な, 簡単な 〈+<i>dat</i>;ad alqd;+<i>sup</i>;+<i>inf</i>〉</div><div class=\"ex\"><i>res factu ～</i> (<author>T<small>ER</small></author>)<span class=\"ext\">造作なくできること.</span></div><div class=\"def\"><num>②</num> 軽快な.</div><div class=\"def\"><num>③</num> 巧みな.</div><div class=\"def\"><num>④</num> 従順な;好意的な, 親切な.</div><div class=\"def\"><num>⑤</num> 喜んで...する, ...する用意のある 〈ad alqd;alci rei〉.</div>\r\n","<div class=\"hw\">faciliter</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">=<a href=\"entry://facile\">facile</a>.</div>\r\n","<div class=\"hw\">facilitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://facilis\">facilis</a>]</div><div class=\"def\"><num>①</num> 容易さ.</div><div class=\"def\"><num>②</num> 流暢.</div><div class=\"def\"><num>③</num> 傾向 〈alcis rei〉.</div><div class=\"def\"><num>④</num> 愛想のよいこと, 親切.</div>\r\n","<div class=\"hw\">facinerōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://facinorōsus\">facinorosus</a>.</div>\r\n","<div class=\"hw\">facinorōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://facinus\">facinus</a>]</div><div class=\"def\">邪悪な, 犯罪の.</div>\r\n","<div class=\"hw\">facinorōsē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://facinorōsus\">facinorōsus</a>]</div><div class=\"def\">邪悪に, 罪を犯して.</div>\r\n","<div class=\"hw\">facinus</div><div class=\"pos\">-noris, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://faciō\">faciō</a>]</div><div class=\"def\"><num>①</num> (人目をひく)行為</div><div class=\"ex\"><i>～ pulcherrimum</i> (<author>C<small>IC</small></author>)<span class=\"ext\">最もすばらしい行為.</span></div><div class=\"def\"><num>②</num> 悪行, 犯罪.</div><div class=\"def\"><num>③</num> 犯罪の道具.</div><div class=\"def\"><num>④</num> 犯罪者.</div>\r\n","<div class=\"hw\">facitergium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[facies/tergeo]</div><div class=\"def\">顔をふく布[タオル].</div>\r\n","<div class=\"hw\">faciēs</div><div class=\"pos\">-ēī, <i>f</i></div><div class=\"ori\">[facio]</div><div class=\"def\"><num>①</num> 外観, 外形.</div><div class=\"def\"><num>②</num> 様相;特徴.</div><div class=\"def\"><num>③</num> 顔, 容貌;美貌</div><div class=\"ex\"><i>virgo facie egregiā</i> (<author>T<small>ER</small></author>)<span class=\"ext\">とびきりの美女.</span></div><div class=\"def\"><num>④</num> うわべ, 見せかけ.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>〘解〙面</div><div class=\"ex\">～ <i>articularis</i><span class=\"ext\">関節面.</span></div>\r\n","<div class=\"hw\">faciō</div><div class=\"pos\">-cere fēcī factum(<i>pass</i> fīō fierī factus sum), <i>tr</i>, <i>intr</i></div><div class=\"def\"><num0>Ⅰ</num0> (<i>tr</i>)</div><div class=\"def\"><num>①</num> する, 行なう.</div><div class=\"def\"><num>②</num> 作る, 形づくる 〈alqm [alqd];alci alqd〉.</div><div class=\"def\"><num>③</num> 建設する, 設置する</div><div class=\"ex\"><i>pontem facere</i> (<author>C<small>AES</small></author>)<span class=\"ext\">橋をかける</span></div><div class=\"ex\"><i>castra facere</i> (<author>C<small>AES</small></author>)<span class=\"ext\">陣を張る.</span></div><div class=\"def\"><num>④</num> 作成する, 書き上げる.</div><div class=\"def\"><num>⑤</num> (貨幣を)刻印する, 鋳造する.</div><div class=\"def\"><num>⑥</num> もうける, 手に入れる.</div><div class=\"def\"><num>⑦</num> (原料を)細工する, 加工する.</div><div class=\"def\"><num>⑧</num> 集める, 調達する.</div><div class=\"def\"><num>⑨</num> 実行する, 果たす 〈alqd;alci alqd〉.</div><div class=\"def\"><num>⑩</num> (儀式・祭典を)挙行する.</div><div class=\"def\"><num>⑪</num> (罪を)犯す.</div><div class=\"def\"><num>⑫</num> (ことば・音を)発する.</div><div class=\"def\"><num>⑬</num> 戦闘する.</div><div class=\"def\"><num>⑭</num> (業務を)営む.</div><div class=\"def\"><num>⑮</num> (苦痛・害を)受ける, こうむる.</div><div class=\"def\"><num>⑯</num> ひき起こす 〈alqd;alci alqd〉.</div><div class=\"def\"><num>⑰</num> (同盟を)結ぶ.</div><div class=\"def\"><num>⑱</num> 与える, 提供する 〈alci alqd〉</div><div class=\"ex\"><i>negotium alci facere</i> (<author>Q<small>UINT</small></author>)<span class=\"ext\">ある人に面倒をかける</span></div><div class=\"ex\"><i>alci potestatem facere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ある人に機会[許可]を与える.</span></div><div class=\"def\"><num>⑲</num> 処理する, 扱う 〈+<i>abl</i> [<i>dat</i>]〉</div><div class=\"ex\"><i>quid hoc homine facias?</i> (<author>C<small>IC</small></author>)<span class=\"ext\">あなたはこの人をどうするのか.</span></div><div class=\"def\"><num>⑳</num> 指定する, 任命する 〈+2個の <i>acc</i>〉.</div><div class=\"def\"><num>㉑</num> (話・文章などの中で)描写する;見せかける 〈+<i>acc c.part</i>;+<i>acc c. inf</i>〉</div><div class=\"ex\"><i>Xenophon facit ... Socratem disputantem</i> (<author>C<small>IC</small></author>)<span class=\"ext\">Xenophon は Socrates に...と主張させている.</span></div><div class=\"def\"><num>㉒</num> (ある人の)所有物とする 〈alqd+<i>gen</i>〉</div><div class=\"ex\"><i>facere alqd dicionis alcis</i> (<author>L<small>IV</small></author>)<span class=\"ext\">あるものをある人の支配下に置く.</span></div><div class=\"def\"><num>㉓</num> (...と)みなす, (...と)評価する 〈+評価の <i>gen</i>〉</div><div class=\"ex\"><i>alqd magni facere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">あるものを重んずる</span></div><div class=\"ex\"><i>alqd nihili facere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">あるものを取るに足らぬと考える.</span></div><div class=\"def\"><num>㉔</num> ...になるようにする, ...させる 〈ut, ne;+<i>subj</i>〉</div><div class=\"ex\"><i>facito, ut sciam</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私に知らせてください.</span></div><div class=\"def\"><num>㉕</num> 想定する 〈+<i>acc c.inf</i>〉.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>intr</i>)</div><div class=\"def\"><num>①</num> 行動する, 行なう.</div><div class=\"def\"><num>②</num> ふるまう.</div><div class=\"def\"><num>③</num> </div><div class=\"ex\"><i>cum [ab] alqo facere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ある人の側に立つ, ある人に味方する.</span></div><div class=\"def\"><num>④</num> (犠牲として)供える, ささげる.</div><div class=\"def\"><num>⑤</num> 役立つ, 適している 〈alci rei;ad alqd〉;ためになる 〈alci〉.</div>\r\n","<div class=\"hw\">facteon</div><div class=\"pos\"><i>indecl</i></div><div class=\"ori\">[facio]</div><div class=\"def\">作るべきである, しなければならぬ(=faciendum(facio の <i>gerundiv</i>))《Cicero によるギリシア語をまねた造語》.</div>\r\n","<div class=\"hw\">factitātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[factito]</div><div class=\"def\">作ること, 創造.</div>\r\n","<div class=\"hw\">factitātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↓<a href=\"entry://factitō\">factitō</a>]</div><div class=\"def\">作る人, 製作者.</div>\r\n","<div class=\"hw\">factitō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr freq</i></div><div class=\"ori\">[facio]</div><div class=\"def\"><num>①</num> 常に行なう.</div><div class=\"def\"><num>②</num> 職業とする.</div><div class=\"def\"><num>③</num> (公然と)指名する</div><div class=\"ex\"><i>alqm heredem factitare</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ある人を相続人であると宣言する.</span></div>\r\n","<div class=\"hw\">factiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[facio]</div><div class=\"def\"><num>①</num> 行動, 作成</div><div class=\"ex\"><i>～ testamenti</i> (<author>C<small>IC</small></author>)<span class=\"ext\">〘法〙遺言状作成(の権限).</span></div><div class=\"def\"><num>②</num> 党派;一団.</div>\r\n","<div class=\"hw\">factiōsus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[factio]</div><div class=\"def\"><num>①</num> 忙しい.</div><div class=\"def\"><num>②</num> 勢力のある.</div><div class=\"def\"><num>③</num> 党派心の強い.</div><hr><div class=\"hw\">factiōsus<SUP>2</SUP></div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">党派争いに巻き込まれた人.</div>\r\n","<div class=\"hw\">factiōsē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://factiōsus\">factiōsus<SUP>1</SUP></a>]</div><div class=\"def\">力強く, 強力に.</div>\r\n","<div class=\"hw\">factor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[facio]</div><div class=\"def\"><num>①</num> 製作者, 創造者.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 実行者</div><div class=\"ex\">～ <i>sceleris</i> (<author>U<small>LP</small></author>)<span class=\"ext\">犯罪者.</span></div><div class=\"def\"><num>③</num> (球戯の)競技者.</div><div class=\"def\"><num>④</num> 搾油人.</div>\r\n","<div class=\"hw\">factum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[factus<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 行為, 行動.</div><div class=\"def\"><num>②</num> 偉業;悪行.</div><div class=\"def\"><num>③</num> 事実.</div><div class=\"def\"><num>④</num> できごと.</div><div class=\"def\"><num>⑤</num> 結果.</div>\r\n","<div class=\"hw\">factus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[facio]</div><div class=\"def\"><num>①</num> なされた, 行なわれた;作られた.</div><div class=\"def\"><num>②</num> 起こった, 事実の.</div><div class=\"def\"><num>③</num> 達成[成就]された.</div><div class=\"def\"><num>④</num> 加工[細工]された.</div><div class=\"def\"><num>⑤</num> (文体が)磨かれた, 完成された.</div><hr><div class=\"hw\">factus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 建築(様式).</div><div class=\"def\"><num>②</num> (オリーブの)圧搾;1回の圧搾量.</div>\r\n","<div class=\"hw\">factīcius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[facio]</div><div class=\"def\"><num>①</num> 人口の, 人為的な.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP></div><div class=\"ex\"><i>facticium nomen</i> (<author>P<small>RISC</small></author>)<span class=\"ext\">〘文〙擬声[音]語.</span></div>\r\n","<div class=\"hw\">factūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[facio]</div><div class=\"def\"><num>①</num> 製造, 製作.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 製品, 作品.</div>\r\n","<div class=\"hw\">facul</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">《古形》=<a href=\"entry://facile\">facile</a>.</div>\r\n","<div class=\"hw\">facula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[fax]</div><div class=\"def\">(小さな)たいまつ.</div>\r\n","<div class=\"hw\">faculter</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">=<a href=\"entry://facile\">facile</a>.</div>\r\n","<div class=\"hw\">facultās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[facilis]</div><div class=\"def\"><num>①</num> 可能性, 便, 機会 〈alcis rei;ad alqd;ut〉</div><div class=\"ex\"><i>si ～ tui praesentis esset</i> (<author>C<small>IC</small></author>)<span class=\"ext\">もしあなたに一目お会いできれば.</span></div><div class=\"def\"><num>②</num> 能力, 技能.</div><div class=\"def\"><num>③</num> たくわえ, 備え 〈alcis rei〉.</div><div class=\"def\"><num>④</num> 手段.</div><div class=\"def\"><num>⑤</num> (<i>pl</i>)資力, 財力.</div>\r\n","<div class=\"hw\">facultātula</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f dim</i></div><div class=\"ori\">[↑<a href=\"entry://facultās\">facultās</a>]</div><div class=\"def\">わずかな資力.</div>\r\n","<div class=\"hw\">facētiae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"ori\">[↓<a href=\"entry://facētus\">facētus</a>]</div><div class=\"def\"><num>①</num> 巧妙.</div><div class=\"def\"><num>②</num> 機知.</div>\r\n","<div class=\"hw\">facētus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>cf. </i> fax]</div><div class=\"def\"><num>①</num> 巧みな, みごとな.</div><div class=\"def\"><num>②</num> 機知に富む.</div>\r\n","<div class=\"hw\">facētē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[facetus]</div><div class=\"def\"><num>①</num> 巧みに, みごとに.</div><div class=\"def\"><num>②</num> 機知に富んで.</div>\r\n","<div class=\"hw\">Fadius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ファディウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">faeceus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[faex]</div><div class=\"def\">不純な, けがれた.</div>\r\n","<div class=\"hw\">faecula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[faex]</div><div class=\"def\">(ぶどう酒の干した)かす, 酒石.</div>\r\n","<div class=\"hw\">faeculentus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[faex]</div><div class=\"def\"><num>①</num> 沈澱物[おり]の多い;濁った.</div><div class=\"def\"><num>②</num> 不潔な.</div>\r\n","<div class=\"hw\">faecārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[faex]</div><div class=\"def\">(ぶどう酒の)かすの.</div>\r\n","<div class=\"hw\">faecātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[faex]</div><div class=\"def\">(ぶどう酒の)かすで作った.</div>\r\n","<div class=\"hw\">faelis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">=<a href=\"entry://fēlis\">felis</a>.</div>\r\n","<div class=\"hw\">faenebris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[faenus]</div><div class=\"def\">利子の.</div>\r\n","<div class=\"hw\">faeneror</div><div class=\"pos\">-ārī -ātus sum, <i>intr</i>, <i>tr dep</i></div><div class=\"ori\">[faenus]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>intr</i>)利子をつけて金を貸す, 高利貸しをする.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>tr</i>)投資[融資]する.</div>\r\n","<div class=\"hw\">faenerātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[faeneror]</div><div class=\"def\">高利貸し《行為》.</div>\r\n","<div class=\"hw\">faenerātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[faeneror]</div><div class=\"def\">高利貸し.</div>\r\n","<div class=\"hw\">faenerātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://faenerō\">faenero</a>, <a href=\"entry://faeneror\">faeneror</a>.</div>\r\n","<div class=\"hw\">faenerātō</div><div class=\"pos\"><i>adv</i>(<i>abl</i>)</div><div class=\"ori\">[faeneratus]</div><div class=\"def\">利子をつけて.</div>\r\n","<div class=\"hw\">faenerātōrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://faenerātor\">faenerātor</a>]</div><div class=\"def\">高利貸しの.</div>\r\n","<div class=\"hw\">faenerō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>, <i>tr</i></div><div class=\"def\">=<a href=\"entry://faeneror\">faeneror</a>.</div>\r\n","<div class=\"hw\">faeneus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[faenum]</div><div class=\"def\">干し草の.</div>\r\n","<div class=\"hw\">faeniculum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[faenum]</div><div class=\"def\">〘植〙ウイキョウ.</div>\r\n","<div class=\"hw\">faeniculārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://faeniculum\">faeniculum</a>]</div><div class=\"def\">ウイキョウの.</div>\r\n","<div class=\"hw\">faenum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">干し草.</div>\r\n","<div class=\"hw\">faenus</div><div class=\"pos\">-noris, <i>n</i></div><div class=\"ori\">[<i>cf. </i> felix<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 利子.</div><div class=\"def\"><num>②</num> (利子付きの)負債, 借金.</div><div class=\"def\"><num>③</num> 利益.</div><div class=\"def\"><num>④</num> 資金.</div><div class=\"def\"><num>⑤</num> 高利貸し.</div>\r\n","<div class=\"hw\">faenusculum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[↑<a href=\"entry://faenus\">faenus</a>]</div><div class=\"def\">わずかな利子.</div>\r\n","<div class=\"hw\">faenārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[faenum]</div><div class=\"def\">干し草の.</div>\r\n","<div class=\"hw\">faenīlia</div><div class=\"pos\">-ium, <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://faenum\">faenum</a>]</div><div class=\"def\">干し草納屋.</div>\r\n","<div class=\"hw\">Faesulae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"def\">ファエスラエ《Etruria の町;現 Fiesole》.</div>\r\n","<div class=\"hw\">Faesulānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Faesulae の.</div>\r\n","<div class=\"hw\">faex</div><div class=\"pos\">-cis, <i>f</i></div><div class=\"def\"><num>①</num> (ぶどう酒などの)沈澱物, おり, かす, 酒石.</div><div class=\"def\"><num>②</num> (人間の)かす, くず.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP></div><div class=\"ex\"><i>～ medicinalis</i><span class=\"ext\">〘薬〙乾燥酵母.</span></div>\r\n","<div class=\"hw\">faida</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[<i>G</i>]</div><div class=\"def\">反目, 不和.</div>\r\n","<div class=\"hw\">fala</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">高い足場《木製の攻城用やぐらなど》.</div>\r\n","<div class=\"hw\">falcicula</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f dim</i></div><div class=\"ori\">[falx]</div><div class=\"def\">(小さな)鎌.</div>\r\n","<div class=\"hw\">Falcidius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ファルキディウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">Falcidiānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Falcidius の.</div>\r\n","<div class=\"hw\">falcifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[falx/fero]</div><div class=\"def\">鎌を持っている.</div>\r\n","<div class=\"hw\">falciformis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[falx/forma]</div><div class=\"def\">〘解〙鎌状の.</div>\r\n","<div class=\"hw\">falcula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[falx]</div><div class=\"def\"><num>①</num> (小さな)鎌.</div><div class=\"def\"><num>②</num> (鳥獣の)かぎづめ.</div>\r\n","<div class=\"hw\">falcārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[falx]</div><div class=\"def\">鎌製造者.</div>\r\n","<div class=\"hw\">falcātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[falx]</div><div class=\"def\"><num>①</num> 鎌のついた.</div><div class=\"def\"><num>②</num> 鎌形の.</div>\r\n","<div class=\"hw\">falcō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[falx]</div><div class=\"def\">〘鳥〙タカ(鷹).</div>\r\n","<div class=\"hw\">falcōnārius</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↑<a href=\"entry://falcō\">falcō</a>]</div><div class=\"def\">鷹匠, 鷹使い.</div>\r\n","<div class=\"hw\">Faleriī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ファレリイー《Etruria の町;Falisci 族の首都;現 Civita Castellana》.</div>\r\n","<div class=\"hw\">Falernum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> (<i>sc. </i> vinum)Falernus 地方産のぶどう酒.</div><div class=\"def\"><num>②</num> (<i>sc. </i> praedium)Falernus 地方にあった Pompeius の地所.</div>\r\n","<div class=\"hw\">Falernus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Campania 北部の Falernus 地方の</div><div class=\"ex\"><i>～ ager</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">Falernus の野《ぶどう酒で有名》.</span></div>\r\n","<div class=\"hw\">falisca</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[Faliscus]</div><div class=\"def\">かいば桶.</div>\r\n","<div class=\"hw\">Faliscus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Falerii の.</div>\r\n","<div class=\"hw\">Faliscī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">ファリスキー《Etruria にいた一部族》.</div>\r\n","<div class=\"hw\">falla</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://fallācia\">fallacia</a>.</div>\r\n","<div class=\"hw\">fallax</div><div class=\"pos\">-ācis, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://fallō\">fallō</a>]</div><div class=\"def\"><num>①</num> 人を欺く, 裏切る.</div><div class=\"def\"><num>②</num> にせの.</div>\r\n","<div class=\"hw\">fallācia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[fallax]</div><div class=\"def\">ごまかし, ぺてん.</div>\r\n","<div class=\"hw\">fallāciloquus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fallax/loquor]</div><div class=\"def\">うそをつく.</div>\r\n","<div class=\"hw\">fallāciter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://fallax\">fallax</a>]</div><div class=\"def\">偽って.</div>\r\n","<div class=\"hw\">fallācitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[fallax]</div><div class=\"def\">あてにならないこと.</div>\r\n","<div class=\"hw\">fallāciōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fallacia]</div><div class=\"def\">偽りの.</div>\r\n","<div class=\"hw\">fallō</div><div class=\"pos\">-ere fefellī falsum, <i>tr</i></div><div class=\"def\"><num>①</num> 迷わせる, 誤らせる</div><div class=\"ex\"><i>glacies fallit pedes</i> (<author>L<small>IV</small></author>)<span class=\"ext\">氷が足をすべらせる</span></div><div class=\"ex\">(impers)<i>nisi me fallit</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私の思い違いでなければ.</span></div><div class=\"def\"><num>②</num> 欺く, だます 〈alqm〉.</div><div class=\"def\"><num>③</num> (期待を)裏切る, 失望させる</div><div class=\"ex\"><i>fidem fallere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">信義を裏切る.</span></div><div class=\"def\"><num>④</num> (...に)気づかれぬようにする, (...から)隠れる 〈alqm [alqd];+<i>part</i>〉</div><div class=\"ex\"><i>ne alio itinere hostis falleret ad urbem incedens</i> (<author>L<small>IV</small></author>)<span class=\"ext\">敵が別の道を通ってこっそり町に侵入してこないように</span></div><div class=\"ex\">(impers)〈+<i>acc c. inf</i>;+間接疑問〉 <i>neque me fallit quantum negotii sustineam</i> (<author>S<small>ALL</small></author>)<span class=\"ext\">私がどれほど大きな仕事を担っているか知らないわけではない(=よくわきまえている).</span></div><div class=\"def\"><num>⑤</num> (暇・苦しみなどを)紛らす</div><div class=\"ex\"><i>curam somno fallere</i> (<author>H<small>OR</small></author>)<span class=\"ext\">眠りによって心配を紛らす.</span></div>\r\n","<div class=\"hw\">falsidicentia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://falsidicus\">falsidicus</a>]</div><div class=\"def\">うそ, 虚言.</div>\r\n","<div class=\"hw\">falsidicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[falsus/dico<SUP>2</SUP>]</div><div class=\"def\">うそをつく;うその.</div>\r\n","<div class=\"hw\">falsificus</div><div class=\"pos\">-a -um</div><div class=\"ori\">[falsus/facio]</div><div class=\"def\">人を欺く.</div>\r\n","<div class=\"hw\">falsificātus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://falsificus\">falsificus</a>]</div><div class=\"def\">にせの, 偽造された.</div>\r\n","<div class=\"hw\">falsijūrius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[falsus/juro]</div><div class=\"def\">偽誓する.</div>\r\n","<div class=\"hw\">falsiloquium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↓<a href=\"entry://falsiloquus\">falsiloquus</a>]</div><div class=\"def\">うそ, 虚言.</div>\r\n","<div class=\"hw\">falsiloquus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[falsus/loquor]</div><div class=\"def\">うそをつく.</div>\r\n","<div class=\"hw\">falsimōnia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[falsus]</div><div class=\"def\">詐欺, ぺてん.</div>\r\n","<div class=\"hw\">falsiparens</div><div class=\"pos\">-entis, <i>adj</i></div><div class=\"ori\">[falsus/parens<SUP>2</SUP>]</div><div class=\"def\">見せかけ[表面上]の父を持った</div><div class=\"ex\"><i>～ Amphitryoniades</i> (<author>C<small>ATUL</small></author>)<span class=\"ext\">=<a href=\"entry://Herculēs\">Hercules</a>.</span></div>\r\n","<div class=\"hw\">falsitās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[falsus]</div><div class=\"def\">虚偽, 偽り.</div>\r\n","<div class=\"hw\">falsum<SUP>1</SUP></div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[falsus]</div><div class=\"def\"><num>①</num> 虚偽, 偽り, 詐欺.</div><div class=\"def\"><num>②</num> 間違い, 誤り.</div><div class=\"def\"><num>③</num> 〘法〙(文書の)偽造.</div><hr><div class=\"hw\">falsum<SUP>2</SUP></div><div class=\"pos\"><i>adv</i></div><div class=\"def\">偽って.</div>\r\n","<div class=\"hw\">falsus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[fallo]</div><div class=\"def\"><num>①</num> 誤った, 間違った</div><div class=\"ex\"><i>opinio falsa</i> (<author>C<small>IC</small></author>)<span class=\"ext\">間違った見解.</span></div><div class=\"def\"><num>②</num> にせの, 偽造された.</div><div class=\"def\"><num>③</num> 人を欺く.</div><div class=\"def\"><num>④</num> 偽りの, 虚偽の</div><div class=\"ex\"><i>falsi rumores</i> (<author>C<small>AES</small></author>)<span class=\"ext\">根も葉もないうわさ.</span></div>\r\n","<div class=\"hw\">falsārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[falsus]</div><div class=\"def\">文書の偽造者.</div>\r\n","<div class=\"hw\">falsātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://falsātus\">falsātus</a>]</div><div class=\"def\">偽造.</div>\r\n","<div class=\"hw\">falsātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://falsō\">falso<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">falsē</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">=<a href=\"entry://falsō\">falso<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">falsō<SUP>1</SUP></div><div class=\"pos\"><i>adv</i>(<i>abl</i>)</div><div class=\"ori\">[falsus]</div><div class=\"def\"><num>①</num> 誤って.</div><div class=\"def\"><num>②</num> 偽って.</div><hr><div class=\"hw\">falsō<SUP>2</SUP></div><div class=\"pos\">-āre -āvī -ātum, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[falsus]</div><div class=\"def\">偽る.</div>\r\n","<div class=\"hw\">falx</div><div class=\"pos\">falcis, <i>f</i></div><div class=\"def\"><num>①</num> 鎌.</div><div class=\"def\"><num>②</num> 破城鉤.</div>\r\n","<div class=\"hw\">falārica</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://fala\">fala</a>]</div><div class=\"def\">(投石機から発射される火のついた)飛び道具.</div>\r\n","<div class=\"hw\">familia</div><div class=\"pos\">-ae(古形 -ās), <i>f</i></div><div class=\"ori\">[famulus]</div><div class=\"def\"><num>①</num> 家族</div><div class=\"ex\"><i>pater familias</i> (<author>C<small>IC</small></author>)<span class=\"ext\">家父長.</span></div><div class=\"def\"><num>②</num> 奴隷, 召使.</div><div class=\"def\"><num>③</num> 財産.</div><div class=\"def\"><num>④</num> 一家《氏族(gens)の下位区分》.</div><div class=\"def\"><num>⑤</num> 一派.</div>\r\n","<div class=\"hw\">familiāris<SUP>1</SUP></div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://familia\">familia</a>]</div><div class=\"def\"><num>①</num> 家族の</div><div class=\"ex\"><i>res ～</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私有財産.</span></div><div class=\"def\"><num>②</num> 個人的な.</div><div class=\"def\"><num>③</num> よく知られた, 見慣れた.</div><div class=\"def\"><num>④</num> 親しい, 親密な.</div><div class=\"def\"><num>⑤</num> (内臓占いで)犠牲をささげた人に関する.</div><div class=\"def\"><num>⑥</num> 熟知した, 精通した 〈alci rei〉.</div><hr><div class=\"hw\">familiāris<SUP>2</SUP></div><div class=\"pos\">-is, <i>m</i>, <i>f</i></div><div class=\"def\"><num>①</num> 家人;奴隷.</div><div class=\"def\"><num>②</num> 親しい人, 友人.</div>\r\n","<div class=\"hw\">familiāriter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[familiaris]</div><div class=\"def\"><num>①</num> 親しく, 親密に.</div><div class=\"def\"><num>②</num> 熟知して.</div>\r\n","<div class=\"hw\">familiāritās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://familiāris\">familiāris<SUP>2</SUP></a>]</div><div class=\"def\"><num>①</num> 親交, 親密.</div><div class=\"def\"><num>②</num> 親しい人, 友人.</div>\r\n","<div class=\"hw\">famis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">=<a href=\"entry://famēs\">fames</a>.</div>\r\n","<div class=\"hw\">famul</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://famulus\">famulus<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">famula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[famulus<SUP>1</SUP>]</div><div class=\"def\">下女, 女奴隷.</div>\r\n","<div class=\"hw\">famulanter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[famulor]</div><div class=\"def\">奴隷のように.</div>\r\n","<div class=\"hw\">famulitium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[famulus]</div><div class=\"def\"><num>①</num> <SUP>◇</SUP>(主人に)仕えること.</div><div class=\"def\"><num>②</num> 大勢の召使.</div>\r\n","<div class=\"hw\">famulor</div><div class=\"pos\">-ārī -ātus sum, <i>intr dep</i></div><div class=\"ori\">[↓<a href=\"entry://famulus\">famulus<SUP>1</SUP></a>]</div><div class=\"def\">召使として働く, 仕える.</div>\r\n","<div class=\"hw\">famulus<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">召使, 奴隷.</div><hr><div class=\"hw\">famulus<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">奴隷の;仕える.</div>\r\n","<div class=\"hw\">famulāris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[famulus]</div><div class=\"def\">奴隷の.</div>\r\n","<div class=\"hw\">famulātrix</div><div class=\"pos\">-īcis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[famulor]</div><div class=\"def\">下女, 女奴隷.</div>\r\n","<div class=\"hw\">famulātus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[famulor]</div><div class=\"def\">隷属, 隷従.</div>\r\n","<div class=\"hw\">famulātōrius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[famulor]</div><div class=\"def\">奴隷的な, 卑屈な.</div>\r\n","<div class=\"hw\">famulātōriē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://famulātōrius\">famulātōrius</a>]</div><div class=\"def\">奴隷的に, 卑屈に.</div>\r\n","<div class=\"hw\">famulō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[famulus]</div><div class=\"def\">召使として使う.</div>\r\n","<div class=\"hw\">famēlicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://famēs\">famēs</a>]</div><div class=\"def\">空腹な, 飢えた.</div>\r\n","<div class=\"hw\">famēlicō</div><div class=\"pos\">-āre -āvī, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://famēlicus\">famēlicus</a>]</div><div class=\"def\">飢えさせる.</div>\r\n","<div class=\"hw\">famēs</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\"><num>①</num> 飢え, 空腹.</div><div class=\"def\"><num>②</num> 飢饉.</div><div class=\"def\"><num>③</num> (文体の)貧弱.</div><div class=\"def\"><num>④</num> 欲望 〈alcis rei〉.</div>\r\n","<div class=\"hw\">fandus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>gerundiv</i>)</div><div class=\"ori\">[for]</div><div class=\"def\"><num>①</num> 口にすることができる.</div><div class=\"def\"><num>②</num> 正しい, 正当な.</div>\r\n","<div class=\"hw\">Fannius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ファンニウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">Fanniānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Fannius の.</div>\r\n","<div class=\"hw\">fans</div><div class=\"pos\">fantis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[for]</div><div class=\"def\">物を言う, 口をきく.</div>\r\n","<div class=\"hw\">far</div><div class=\"pos\">farris, <i>n</i></div><div class=\"def\"><num>①</num> スペルト小麦.</div><div class=\"def\"><num>②</num> (<i>pl</i>)穀物.</div><div class=\"def\"><num>③</num> ひき割り小麦.</div><div class=\"def\"><num>④</num> 小麦粉.</div>\r\n","<div class=\"hw\">farciō</div><div class=\"pos\">-īre farsī fartum, <i>tr</i></div><div class=\"def\">詰め込む.</div>\r\n","<div class=\"hw\">farcīmen</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"ori\">[farcio]</div><div class=\"def\">ソーセージ.</div>\r\n","<div class=\"hw\">farcīminum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↓<a href=\"entry://farciō\">farciō</a>]</div><div class=\"def\">馬や牛の病気《おそらく便秘》.</div>\r\n","<div class=\"hw\">farfarum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">〘植〙フキタンポポ.</div>\r\n","<div class=\"hw\">Farfarus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://Fabaris\">Fabaris</a>.</div>\r\n","<div class=\"hw\">fariō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>m</i></div><div class=\"def\">〘魚〙マス(鱒).</div>\r\n","<div class=\"hw\">farneus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://farnus\">farnus</a>]</div><div class=\"def\">トネリコの木の.</div>\r\n","<div class=\"hw\">farnus</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"def\">〘植〙トネリコ.</div>\r\n","<div class=\"hw\">farreum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://farreus\">farreus</a>]</div><div class=\"def\">(<i>sc</i>. libum)スペルト小麦菓子.</div>\r\n","<div class=\"hw\">farreus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[far]</div><div class=\"def\">スペルト小麦の.</div>\r\n","<div class=\"hw\">farreārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://farrārius\">farrarius</a>.</div>\r\n","<div class=\"hw\">farreātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"def\">=<a href=\"entry://confarreātiō\">confarreatio</a>.</div>\r\n","<div class=\"hw\">farriculum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n dim</i></div><div class=\"ori\">[farreum]</div><div class=\"def\">(小さな)スペルト小麦菓子.</div>\r\n","<div class=\"hw\">farrāceus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[far]</div><div class=\"def\">スペルト小麦の.</div>\r\n","<div class=\"hw\">farrāgō</div><div class=\"pos\">-ginis, <i>f</i></div><div class=\"ori\">[far]</div><div class=\"def\"><num>①</num> (家畜の飼料にする)混合飼料.</div><div class=\"def\"><num>②</num> 寄せ集め, ごたまぜ;くだらぬ事.</div>\r\n","<div class=\"hw\">farrārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[far]</div><div class=\"def\">穀物の.</div>\r\n","<div class=\"hw\">farrātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[far]</div><div class=\"def\">スペルト小麦の粥<SUB>かゆ</SUB>でいっぱいの.</div>\r\n","<div class=\"hw jl\"><SUP>*</SUP>fars</div><div class=\"pos\">fartis, <i>f</i></div><div class=\"ori\">[farcio]</div><div class=\"def\">(用例は <i>acc</i> fartim, <i>abl</i> farte のみ)詰め物;挽肉.</div>\r\n","<div class=\"hw\">farsī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://farciō\">farcio</a>.</div>\r\n","<div class=\"hw\">fartim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[fars]</div><div class=\"def\">詰め込んで, ぎっしりと.</div>\r\n","<div class=\"hw\">fartor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[farcio]</div><div class=\"def\">鳥の肥育者;鳥肉屋.</div>\r\n","<div class=\"hw\">fartus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://farciō\">farcio</a>.</div>\r\n","<div class=\"hw\">fartūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[farcio]</div><div class=\"def\"><num>①</num> (鳥の)肥育.</div><div class=\"def\"><num>②</num> (壁に割り石などを)詰め込むこと.</div>\r\n","<div class=\"hw\">farēdō</div><div class=\"pos\">-dinis, <SUP>◇</SUP><i>f</i></div><div class=\"def\">膿瘍の一種.</div>\r\n","<div class=\"hw\">farīna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[far]</div><div class=\"def\">穀粉, ひき割り粉.</div>\r\n","<div class=\"hw\">farīnula</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f dim</i></div><div class=\"ori\">[farina]</div><div class=\"def\">少量のひき割り粉.</div>\r\n","<div class=\"hw\">farīnulentus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[farina]</div><div class=\"def\">粉を混ぜた, 粉の多い.</div>\r\n","<div class=\"hw\">farīnāceus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://farīna\">farīna</a>]</div><div class=\"def\">穀粉から作られた.</div>\r\n","<div class=\"hw\">farīnārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[farina]</div><div class=\"def\">穀粉の.</div>\r\n","<div class=\"hw\">fascea, fasceola</div><div class=\"def\">⇒<a href=\"entry://fascia\">fascia</a>, <a href=\"entry://fasciola\">fasciola</a>.</div>\r\n","<div class=\"hw\">fascia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 帯状のもの;ひも, 帯, バンド</div><div class=\"ex\"><i>～ nigra</i> (<author>J<small>UV</small></author>)<span class=\"ext\">一筋の雲</span></div><div class=\"ex\"><i>non es nostrae fasciae</i> (<author>P<small>ETR</small></author>)<span class=\"ext\">きみはわれわれの仲間ではない.</span></div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘解〙筋膜.</div>\r\n","<div class=\"hw\">fasciculus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[fascis]</div><div class=\"def\">(小さな)束.</div>\r\n","<div class=\"hw\">fascinum</div><div class=\"pos\">-ī, <i>n</i>, <B>-us</B> -ī, <i>m</i></div><div class=\"def\"><num>①</num> 呪文, 魔法.</div><div class=\"def\"><num>②</num> 陰茎.</div>\r\n","<div class=\"hw\">fascinātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://fascinō\">fascinō</a>]</div><div class=\"def\">魔法をかけること.</div>\r\n","<div class=\"hw\">fascinō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[fascinum]</div><div class=\"def\">魔法をかける.</div>\r\n","<div class=\"hw\">fascinōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">好色な.</div>\r\n","<div class=\"hw\">fasciola</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[fascia]</div><div class=\"def\"><num>①</num> (小さな)ひも, 帯, バンド.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘解〙小束.</div>\r\n","<div class=\"hw\">fascis</div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\"><num>①</num> 束.</div><div class=\"def\"><num>②</num> 荷物.</div><div class=\"def\"><num>③</num> (通例 <i>pl</i>)束桿<SUB>そっかん</SUB>《執政官など高官の権威標章;束ねた棒の中央に斧を入れて縛ったもので, 高官に随行する警吏 lictores が奉持した》;執政官の職.</div>\r\n","<div class=\"hw\">fasciō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[fascia]</div><div class=\"def\">包帯を巻く.</div>\r\n","<div class=\"hw\">fascīna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[fascis]</div><div class=\"def\">(小枝の)束.</div>\r\n","<div class=\"hw\">fassus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://fateor\">fateor</a>.</div>\r\n","<div class=\"hw\">fastus<SUP>1</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">尊大;軽蔑.</div><hr><div class=\"hw\">fastus<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>cf. </i> fas]</div><div class=\"def\">開廷日の</div><div class=\"ex\"><i>dies fasti</i> (<author>C<small>IC</small></author>)<span class=\"ext\">開廷日(=<a href=\"entry://fastī\">fasti</a>).</span></div>\r\n","<div class=\"hw\">fastī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[fastus<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 開廷日.</div><div class=\"def\"><num>②</num> (開廷日・祭事などを記載した)暦.</div><div class=\"def\"><num>③</num> (年代順の)執政官一覧表.</div>\r\n","<div class=\"hw\">fastīdium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[fastus<SUP>1</SUP>/taedium]</div><div class=\"def\"><num>①</num> 嫌悪, 反感;(食べ物の)好き嫌い, 食欲不振 〈+<i>gen</i>〉.</div><div class=\"def\"><num>②</num> 好みのやかましいこと, 気むずかしさ.</div><div class=\"def\"><num>③</num> 尊大;軽蔑.</div>\r\n","<div class=\"hw\">fastīdiō</div><div class=\"pos\">-īre -īvī [-iī] -ītum, <i>intr</i>, <i>tr</i></div><div class=\"ori\">[fastidium]</div><div class=\"def\"><num>①</num> 嫌う, いやがる 〈<i>abs</i>;alqd〉.</div><div class=\"def\"><num>②</num> 尊大にふるまう 〈<i>abs</i>〉.</div><div class=\"def\"><num>③</num> 退ける, 軽蔑する 〈+<i>gen</i>;+<i>acc</i>;+<i>inf</i>;+<i>acc c.inf</i>〉</div><div class=\"ex\"><i>ne fastidieris nos in sacerdotum numerum accipere</i> (<author>L<small>IV</small></author>)<span class=\"ext\">われわれを神官の仲間に入れるのをすげなく拒否してはならない.</span></div>\r\n","<div class=\"hw\">fastīdiōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fastidium]</div><div class=\"def\"><num>①</num> 嫌悪を覚えさせる, 不快な.</div><div class=\"def\"><num>②</num> 好みのやかましい, ...に満足しない 〈+<i>gen</i>〉</div><div class=\"ex\"><i>～ litterarum Latinarum</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ラテン文学を軽んじる.</span></div><div class=\"def\"><num>③</num> 尊大な.</div>\r\n","<div class=\"hw\">fastīdiōsē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://fastīdiōsus\">fastīdiōsus</a>]</div><div class=\"def\"><num>①</num> 嫌悪を表わして, 軽蔑的に.</div><div class=\"def\"><num>②</num> 気むずかしく.</div>\r\n","<div class=\"hw\">fastīdītus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://fastīdiō\">fastidio</a>.</div>\r\n","<div class=\"hw\">fastīgium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://fastīgō\">fastīgō</a>]</div><div class=\"def\"><num>①</num> 先端;先細り.</div><div class=\"def\"><num>②</num> 傾斜, 斜面.</div><div class=\"def\"><num>③</num> 高さ;深さ.</div><div class=\"def\"><num>④</num> 最高部, 頂点.</div><div class=\"def\"><num>⑤</num> 〘建〙切妻, 破風.</div><div class=\"def\"><num>⑥</num> 高位.</div><div class=\"def\"><num>⑦</num> 要点, 眼目.</div><div class=\"def\"><num>⑧</num> <SUP>◇</SUP>〘解〙脳室頂.</div>\r\n","<div class=\"hw\">fastīgātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[fastigo]</div><div class=\"def\">とがらせること.</div>\r\n","<div class=\"hw\">fastīgātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[fastigo]</div><div class=\"def\"><num>①</num> とがった.</div><div class=\"def\"><num>②</num> 傾いた, 斜めの.</div>\r\n","<div class=\"hw\">fastīgātē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[fastigatus]</div><div class=\"def\">傾いて, 斜めに.</div>\r\n","<div class=\"hw\">fastīgō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"def\"><num>①</num> (先を)とがらせる.</div><div class=\"def\"><num>②</num> 傾斜させる.</div>\r\n","<div class=\"hw\">fastōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://fastus\">fastus<SUP>1</SUP></a>]</div><div class=\"def\">尊大な, 軽蔑的な.</div>\r\n","<div class=\"hw\">fasēlus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://phasēlus\">phaselus</a>.</div>\r\n","<div class=\"hw\">fateor</div><div class=\"pos\">-ērī fassus sum, <i>tr dep</i></div><div class=\"ori\">[<i>cf. </i> fari]</div><div class=\"def\"><num>①</num> (真実であると)認める;告白する.</div><div class=\"def\"><num>②</num> 示す, 現わす</div><div class=\"ex\"><i>fateri iram vultu</i> (<author>O<small>V</small></author>)<span class=\"ext\">顔に怒りを現わす.</span></div>\r\n","<div class=\"hw\">fatiscor</div><div class=\"pos\">-scī, <i>intr dep</i></div><div class=\"def\">=<a href=\"entry://fatiscō\">fatisco</a>.</div>\r\n","<div class=\"hw\">fatiscō</div><div class=\"pos\">-ere, <i>intr</i></div><div class=\"def\"><num>①</num> [<i>cf. </i> fatigo] 裂ける, 割れる.</div><div class=\"def\"><num>②</num> 衰える, 弱る</div><div class=\"ex\"><i>fatiscit seditio</i> (<author>T<small>AC</small></author>)<span class=\"ext\">暴動がおさまる.</span></div>\r\n","<div class=\"hw\">fatuitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[fatuus]</div><div class=\"def\">愚かさ.</div>\r\n","<div class=\"hw\">fatuor<SUP>1</SUP></div><div class=\"pos\">-ārī, <i>intr dep</i></div><div class=\"ori\">[fatuus]</div><div class=\"def\">愚かなことを言う.</div>\r\n","<div class=\"hw\">fatuus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> 愚かな.</div><div class=\"def\"><num>②</num> (食物が)味のない, まずい.</div>\r\n","<div class=\"hw\">fatuē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[fatuus]</div><div class=\"def\">愚かに.</div>\r\n","<div class=\"hw\">fatīgābilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[fatigo]</div><div class=\"def\">疲労させる.</div>\r\n","<div class=\"hw\">fatīgātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://fatīgō\">fatīgō</a>]</div><div class=\"def\">疲労, 消耗.</div>\r\n","<div class=\"hw\">fatīgō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"def\"><num>①</num> 疲れさせる;うんざりさせる 〈alqm〉.</div><div class=\"def\"><num>②</num> (しつこく)悩ます, 苦しめる</div><div class=\"ex\"><i>fatigare alqm precibus</i> (<author>L<small>IV</small></author>)<span class=\"ext\">ある人にしつこくせがむ.</span></div><div class=\"def\"><num>③</num> (精神力・体力を)使い尽くす, 枯渇させる.</div><div class=\"def\"><num>④</num> 屈服させる, 打ち負かす.</div>\r\n","<div class=\"hw\">faucēs</div><div class=\"pos\">-ium, <i>f pl</i></div><div class=\"def\"><num>①</num> のど, 咽喉.</div><div class=\"def\"><num>②</num> 狭い出入口.</div><div class=\"def\"><num>③</num> 隘路, 狭い道.</div><div class=\"def\"><num>④</num> 噴火口.</div><div class=\"def\"><num>⑤</num> 海峡;地峡.</div><div class=\"def\"><num>⑥</num> 割れ目, 深淵.</div>\r\n","<div class=\"hw\">fauna</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘生物〙(一地域または一時代の)動物相.</div>\r\n","<div class=\"hw\">Fauna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘神話〙ファウナ《Faunus の姉妹または妻とされる予言の女神;Bona Dea と同一視される》.</div>\r\n","<div class=\"hw\">Faunigena</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://Faunus\">Faunus</a>/gigno]</div><div class=\"def\">Faunus の息子または子孫.</div>\r\n","<div class=\"hw\">Faunus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">〘神話〙</div><div class=\"def\"><num>①</num> ファウヌス《Latium の王で Latinus の父;死後, 牧人と家畜の守護神となる;のち Pan と同一視された》.</div><div class=\"def\"><num>②</num> (<i>pl</i> Fauni)ファウニー《上半身は人間, 下半身は山羊で, 角とひづめをもった山野の精;ギリシア神話の Satyrus たちと同一視された》.</div>\r\n","<div class=\"hw\">Fausta</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ファウスタ《Sulla の娘で Milo の妻》.</div>\r\n","<div class=\"hw\">Faustitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[faustus]</div><div class=\"def\">〘神話〙ファウスティタース《「幸運」 の意;豊饒<SUB>ほうじょう</SUB>の女神》.</div>\r\n","<div class=\"hw\">Faustulus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">〘伝説〙ファウストゥルス《Romulus と Remus を拾って養育した羊飼い》.</div>\r\n","<div class=\"hw\">faustus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[faveo]</div><div class=\"def\">幸運な;さい先のよい.</div>\r\n","<div class=\"hw\">Faustus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ファウストゥス《ローマ人の個人名;特に <i>～ Cornelius Sulla</i>, 独裁官 Sulla の息子》.</div>\r\n","<div class=\"hw\">faustē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[faustus]</div><div class=\"def\">さい先よく, 都合よく.</div>\r\n","<div class=\"hw\">fautor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[faveo]</div><div class=\"def\"><num>①</num> 保護者, 支持者, 後援者.</div><div class=\"def\"><num>②</num> (劇場に雇われて)拍手喝采する者.</div>\r\n","<div class=\"hw\">fautrix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://fautor\">fautor</a>]</div><div class=\"def\">保護者, 支持者《女性》.</div>\r\n","<div class=\"hw\">fautus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://faveō\">faveo</a>.</div>\r\n","<div class=\"hw jl\"><SUP>*</SUP>faux</div><div class=\"pos\">faucis, <i>f</i></div><div class=\"def\">(通例 <i>pl</i> faucēs で;<i>sg</i> の用例は <i>abl</i> fauce のみ)⇒ <a href=\"entry://faucēs\">fauces</a>.</div>\r\n","<div class=\"hw\">favea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[faveo]</div><div class=\"def\">気に入りの女奴隷.</div>\r\n","<div class=\"hw\">faventia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[faveo]</div><div class=\"def\">縁起のよいふるまい(=宗教儀式で沈黙を守ること).</div>\r\n","<div class=\"hw\">Faventia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">ファウェンティア《Gallia Cisalpina の町》.</div>\r\n","<div class=\"hw\">Faventīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Faventia の.</div>\r\n","<div class=\"hw\">faveō</div><div class=\"pos\">-ēre fāvī fautum, <i>intr</i></div><div class=\"def\"><num>①</num> 好意を示す, 後援[支持]する 〈+<i>dat</i>〉.</div><div class=\"def\"><num>②</num> 好都合である.</div><div class=\"def\"><num>③</num> 拍手喝采する.</div><div class=\"def\"><num>④</num> </div><div class=\"ex\"><i>linguis [ore] favere</i> (<author>C<small>IC</small> [V<small>ERG</small>]</author>)<span class=\"ext\">縁起の悪いことばを口にしない(=沈黙する).</span></div>\r\n","<div class=\"hw\">favilla</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>cf. </i> fax, foveo]</div><div class=\"def\"><num>①</num> (まだ熱い)灰, 燃えさし, 余燼<SUB>よじん</SUB>.</div><div class=\"def\"><num>②</num> 火花.</div>\r\n","<div class=\"hw\">favillāceus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://favilla\">favilla</a>]</div><div class=\"def\">灰の(ような).</div>\r\n","<div class=\"hw\">favitor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"def\">《古形》=<a href=\"entry://fautor\">fautor</a>.</div>\r\n","<div class=\"hw\">favor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[faveo]</div><div class=\"def\"><num>①</num> 好意, 支持;偏愛.</div><div class=\"def\"><num>②</num> 賛同, 喝采.</div>\r\n","<div class=\"hw\">favus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">ミツバチの巣, ハチの巣.</div>\r\n","<div class=\"hw\">favīsae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"def\">(神殿近くにあった)地下貯蔵室.</div>\r\n","<div class=\"hw\">Favōnius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>cf. </i> foveo]</div><div class=\"def\">(春に吹く)西風(=<a href=\"entry://zephyrus\">Zephyrus</a>).</div>\r\n","<div class=\"hw\">favōrābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://favor\">favor</a>]</div><div class=\"def\">好意をもたれている, うけがよい.</div>\r\n","<div class=\"hw\">favōrābiliter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://favōrābilis\">favōrābilis</a>]</div><div class=\"def\">好評を博して.</div>\r\n","<div class=\"hw\">fax</div><div class=\"pos\">facis, <i>f</i></div><div class=\"def\"><num>①</num> たいまつ.</div><div class=\"def\"><num>②</num> 婚礼のたいまつ;婚礼.</div><div class=\"def\"><num>③</num> 葬式のたいまつ.</div><div class=\"def\"><num>④</num> 光, 炎</div><div class=\"ex\"><i>aeterna ～</i> (<author>S<small>EN</small></author>)<span class=\"ext\">太陽.</span></div><div class=\"def\"><num>⑤</num> 火つけたいまつ, 燃え木.</div><div class=\"def\"><num>⑥</num> 主謀者 〈alci rei〉.</div><div class=\"def\"><num>⑦</num> 流星.</div>\r\n","<div class=\"hw\">faxim</div><div class=\"pos\"><i>subj pf</i></div><div class=\"def\">《古形》=fecerim(⇒ <a href=\"entry://faciō\">facio</a>).</div>\r\n","<div class=\"hw\">faxitur</div><div class=\"pos\">3 <i>sg pass ind fut pf</i></div><div class=\"def\">《古形》=factum erit(⇒ <a href=\"entry://faciō\">facio</a>).</div>\r\n","<div class=\"hw\">faxō</div><div class=\"pos\"><i>fut pf</i></div><div class=\"def\">《古形》=fecero(⇒ <a href=\"entry://faciō\">facio</a>).</div>\r\n","<div class=\"hw\">febribilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[febris]</div><div class=\"def\">熱を出しやすい.</div>\r\n","<div class=\"hw\">febrifugia</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[febris/fugo]</div><div class=\"def\"><num>①</num> 〘植〙シマセンブリ属の植物(=<a href=\"entry://centaurēum\">centaureum</a>).</div><div class=\"def\"><num>②</num> 〘薬〙解熱剤.</div>\r\n","<div class=\"hw\">febris</div><div class=\"pos\">-is, <i>f</i></div><div class=\"ori\">[<i>cf. </i> ferveo]</div><div class=\"def\">熱, 発熱.</div>\r\n","<div class=\"hw\">febriō</div><div class=\"pos\">-īre, <i>intr</i></div><div class=\"ori\">[↓<a href=\"entry://febris\">febris</a>]</div><div class=\"def\">熱がある.</div>\r\n","<div class=\"hw\">Februa</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"ori\">[februm]</div><div class=\"def\">清めと贖罪の儀式《2月15日に行なわれた;<i>cf. </i> Februarius》.</div>\r\n","<div class=\"hw\">februm</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">清め《Sabini 族の用語》.</div>\r\n","<div class=\"hw\">Februālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://Februa\">Februa</a>]</div><div class=\"def\">=<a href=\"entry://februātus\">februatus</a>.</div>\r\n","<div class=\"hw\">Februārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[Februa]</div><div class=\"def\">2月の.</div><hr><div class=\"hw\">Februārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">(<i>sc. </i> mensis)2月《前450年まで一年の最後の月;以後, 第2月》.</div>\r\n","<div class=\"hw\">februātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[februo]</div><div class=\"def\">清めの儀式.</div>\r\n","<div class=\"hw\">februātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[februo]</div><div class=\"def\">清めの.</div>\r\n","<div class=\"hw\">februō</div><div class=\"pos\">-āre -ātum, <i>tr</i></div><div class=\"ori\">[Februa]</div><div class=\"def\">清める, (罪を)贖<SUB>あがな</SUB>う.</div>\r\n","<div class=\"hw\">febrīcitō</div><div class=\"pos\">-āre -āvī, <i>intr</i></div><div class=\"ori\">[febris]</div><div class=\"def\">熱がある.</div>\r\n","<div class=\"hw\">febrīcula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[febris]</div><div class=\"def\">微熱.</div>\r\n","<div class=\"hw\">febrīculōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[febris]</div><div class=\"def\">熱のある, 熱病の.</div>\r\n","<div class=\"hw\">febrīcōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[febris]</div><div class=\"def\">熱のある.</div>\r\n","<div class=\"hw\">fefellī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://fallō\">fallo</a>.</div>\r\n","<div class=\"hw\">fel</div><div class=\"pos\">fellis, <i>n</i></div><div class=\"def\"><num>①</num> 胆汁;胆嚢<SUB>たんのう</SUB></div><div class=\"ex\"><i>atrum ～</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">黒い胆汁《怒りの原因とされた》.</span></div><div class=\"def\"><num>②</num> 毒.</div><div class=\"def\"><num>③</num> とげとげしさ, 悪意.</div>\r\n","<div class=\"hw\">felicātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://filicātus\">filicatus</a>.</div>\r\n","<div class=\"hw\">felix<SUP>2</SUP></div><div class=\"pos\">-icis, <i>f</i></div><div class=\"def\">=<a href=\"entry://filix\">filix</a>.</div>\r\n","<div class=\"hw\">felleus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fel]</div><div class=\"def\">胆汁の(ような).</div>\r\n","<div class=\"hw\">fellicula</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f dim</i></div><div class=\"ori\">[fel]</div><div class=\"def\">胆汁.</div>\r\n","<div class=\"hw\">fellicō, -tō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr freq</i></div><div class=\"ori\">[fello]</div><div class=\"def\">吸う.</div>\r\n","<div class=\"hw\">fellātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[fello]</div><div class=\"def\">フェラチオ, 吸茎.</div>\r\n","<div class=\"hw\">fellātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[fello]</div><div class=\"def\">フェラチオをする者.</div>\r\n","<div class=\"hw\">fellātrix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://fellātor\">fellātor</a>]</div><div class=\"def\">《碑》フェラチオをする女.</div>\r\n","<div class=\"hw\">fellō, fēlō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>, <i>intr</i></div><div class=\"def\"><num>①</num> (乳を)吸う.</div><div class=\"def\"><num>②</num> 吸茎する.</div>\r\n","<div class=\"hw\">Felsina</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">フェルシナ《Bononia の古名》.</div>\r\n","<div class=\"hw\">femen</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"def\">=<a href=\"entry://femur\">femur</a>.</div>\r\n","<div class=\"hw\">feminālia</div><div class=\"pos\">-ium, <i>n pl</i></div><div class=\"ori\">[femen]</div><div class=\"def\">ももひき.</div>\r\n","<div class=\"hw\">femoropopliteus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙大腿膝窩の.</div>\r\n","<div class=\"hw\">femorālia</div><div class=\"pos\">-ium, <SUP>◇</SUP><i>n pl</i></div><div class=\"ori\">[femur]</div><div class=\"def\">=<a href=\"entry://feminālia\">feminalia</a>.</div>\r\n","<div class=\"hw\">femorālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[femur]</div><div class=\"def\">腿の.</div>\r\n","<div class=\"hw\">femur</div><div class=\"pos\">-moris, <i>n</i></div><div class=\"def\">腿<SUB>もも</SUB>.</div>\r\n","<div class=\"hw\">fenestella</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[↓<a href=\"entry://fenestra\">fenestra</a>]</div><div class=\"def\">小窓, 壁の小さな開き口.</div>\r\n","<div class=\"hw\">fenestra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 窓.</div><div class=\"def\"><num>②</num> 銃眼, 狭間.</div><div class=\"def\"><num>③</num> (壁の)開き口.</div><div class=\"def\"><num>④</num> 機会, 門戸</div><div class=\"ex\"><i>huic quantam fenestram ad nequitiam patefeceris</i>! (<author>T<small>ER</small></author>)<span class=\"ext\">あなたは彼の放蕩のためになんと大きな抜け穴を開けてやることになろう.</span></div>\r\n","<div class=\"hw\">fenestrula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[fenestra]</div><div class=\"def\">小窓.</div>\r\n","<div class=\"hw\">fenestrātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[↓<a href=\"entry://fenestrō\">fenestrō</a>]</div><div class=\"def\">窓のついた.</div>\r\n","<div class=\"hw\">fenestrō</div><div class=\"pos\">-āre -āvī -ātum, <i>adj</i></div><div class=\"ori\">[fenestra]</div><div class=\"def\">窓をつける.</div>\r\n","<div class=\"hw\">fer</div><div class=\"pos\">2 <i>sg impr</i></div><div class=\"def\">⇒<a href=\"entry://ferō\">fero</a>.</div>\r\n","<div class=\"hw\">fera</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[ferus]</div><div class=\"def\">(<i>sc. </i> bestia)野獣.</div>\r\n","<div class=\"hw\">ferax</div><div class=\"pos\">-ācis, <i>adj</i></div><div class=\"ori\">[fero]</div><div class=\"def\">実り豊かな, 多産の, 肥沃な 〈+<i>gen</i> [<i>abl</i>]〉.</div>\r\n","<div class=\"hw\">ferbuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://ferveō\">ferveo</a>.</div>\r\n","<div class=\"hw\">ferctum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://fertum\">fertum</a>.</div>\r\n","<div class=\"hw\">ferculum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[fero]</div><div class=\"def\"><num>①</num> 運び台, 盆, 皿.</div><div class=\"def\"><num>②</num> (一皿の)料理.</div>\r\n","<div class=\"hw\">ferens</div><div class=\"pos\">-entis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[fero]</div><div class=\"def\"><num>①</num> (風が)望みの方角に吹く, さい先のよい.</div><div class=\"def\"><num>②</num> 耐えることができる.</div>\r\n","<div class=\"hw\">Ferentium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://Ferentīnum\">Ferentinum (2)</a> .</div>\r\n","<div class=\"hw\">ferentārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">(飛び道具をもって戦う)軽装兵.</div>\r\n","<div class=\"hw\">Ferentīna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">フェレンティーナ《Ferentinum (1) の女神》.</div>\r\n","<div class=\"hw\">Ferentīnum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">フェレンティーヌム《 (1) Latium 中部の町;現 Ferentino.(2) Etruria 南部の町;現 Ferento》.</div>\r\n","<div class=\"hw\">Ferentīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Ferentinum (1) の</div><div class=\"ex\"><i>aqua Ferentina</i> (<author>L<small>IV</small></author>)<span class=\"ext\">Latium の Alba Longa 付近の小川.</span></div>\r\n","<div class=\"hw\">Ferentīnās</div><div class=\"pos\">-ātis, <i>adj</i></div><div class=\"def\">Ferentinum (1) の.</div><div class=\"hw2\"><b>Ferentīnātēs</b></div><div class=\"pos2\">-ium, <i>m pl</i></div><div class=\"def2\">Ferentinum (1) の住民.</div>\r\n","<div class=\"hw\">Feretrius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>cf</i>. ferio]</div><div class=\"def\">(敵を打ち負かす神としての)Juppiter の添え名.</div>\r\n","<div class=\"hw\">feretrum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">運び台, 棺台.</div>\r\n","<div class=\"hw\">feritās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[ferus]</div><div class=\"def\">野蛮, 狂暴, 獰猛.</div>\r\n","<div class=\"hw\">feriō</div><div class=\"pos\">-īre, <i>tr</i></div><div class=\"def\"><num>①</num> 打つ, たたく</div><div class=\"ex\"><i>ferire pectora</i> (<author>O<small>V</small></author>)<span class=\"ext\">(悲しみの表現として手で)胸を打つ</span></div><div class=\"ex\"><i>certatim feriunt mare</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">彼らは競って(オールで)海面をたたく(=船をこぐ).</span></div><div class=\"def\"><num>②</num> 打ち殺す;(獣を)いけにえにささげる</div><div class=\"ex\"><i>alqm securi ferire</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ある人を打ち首にする.</span></div><div class=\"def\"><num>③</num> 突き当たる, ぶつかる;届く.</div><div class=\"def\"><num>④</num> (事件などが)ふりかかる, 苦しめる.</div><div class=\"def\"><num>⑤</num> (貨幣を)鋳造する.</div><div class=\"def\"><num>⑥</num> </div><div class=\"ex\"><i>medium ferire</i> (<author>C<small>IC</small></author>)<span class=\"ext\">(両極端を避けて)中道を選ぶ.</span></div><div class=\"def\"><num>⑦</num> </div><div class=\"ex\"><i>foedus ferire</i> (<author>C<small>IC</small></author>)<span class=\"ext\">協定[契約]を結ぶ.</span></div><div class=\"def\"><num>⑧</num> (人を)かつぐ, だます.</div>\r\n","<div class=\"hw\">fermentescō</div><div class=\"pos\">-ere, <i>intr inch</i></div><div class=\"ori\">[↓<a href=\"entry://fermentō\">fermentō</a>]</div><div class=\"def\">(発酵したかのように)ふくれる.</div>\r\n","<div class=\"hw\">fermentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[<i>cf. </i> fervo, ferveo]</div><div class=\"def\"><num>①</num> 発酵.</div><div class=\"def\"><num>②</num> 酵母.</div><div class=\"def\"><num>③</num> 激怒, かんしゃく.</div><div class=\"def\"><num>④</num> 麦芽酒.</div>\r\n","<div class=\"hw\">fermentātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://fermentō\">fermento</a>.</div>\r\n","<div class=\"hw\">fermentō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://fermentum\">fermentum</a>]</div><div class=\"def\">発酵させる.</div>\r\n","<div class=\"hw\">fermē</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">=<a href=\"entry://ferē\">fere</a>.</div>\r\n","<div class=\"hw\">ferox</div><div class=\"pos\">-ōcis, <i>adj</i></div><div class=\"ori\">[ferus]</div><div class=\"def\"><num>①</num> 狂暴な, 荒々しい.</div><div class=\"def\"><num>②</num> 大胆な, 勇敢な.</div><div class=\"def\"><num>③</num> 威勢のよい, 血気盛んな.</div><div class=\"def\"><num>④</num> 傲慢な, 横柄な.</div>\r\n","<div class=\"hw\">ferre</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://ferō\">fero</a>.</div>\r\n","<div class=\"hw\">ferreus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ferrum]</div><div class=\"def\"><num>①</num> 鉄の, 鉄製の.</div><div class=\"def\"><num>②</num> 堅固な, 不動の</div><div class=\"ex\"><i>Cato ferrei corporis animique</i> (<author>L<small>IV</small></author>)<span class=\"ext\">不屈の肉体と魂の(持ち主である)Cato.</span></div><div class=\"def\"><num>③</num> 無感覚の;無情な, 残酷な</div><div class=\"ex\"><i>os ferreum</i> (<author>C<small>IC</small></author>)<span class=\"ext\">鉄面皮.</span></div>\r\n","<div class=\"hw\">ferricrepinus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ferrum/crepo]</div><div class=\"def\">足かせがガチャガチャ鳴る.</div>\r\n","<div class=\"hw\">ferricyanidum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘化〙フェリシアン化物.</div>\r\n","<div class=\"hw\">ferrifodīna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[ferrum/fodina]</div><div class=\"def\">鉄鉱山.</div>\r\n","<div class=\"hw\">ferriterium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[ferrum/tero]</div><div class=\"def\">足かせですりむけている人々のいる場所《ergastulum 「奴隷収鑑所」 を指す喜劇の造語》.</div>\r\n","<div class=\"hw\">ferriterus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ferrum/tero]</div><div class=\"def\">足かせですりむけている.</div>\r\n","<div class=\"hw\">ferritrībax</div><div class=\"pos\">-ācis, <i>adj</i></div><div class=\"def\">=<a href=\"entry://ferriterus\">ferriterus</a>.</div>\r\n","<div class=\"hw\">ferrum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> 鉄.</div><div class=\"def\"><num>②</num> 鉄器具《すき・斧・はさみ・鉄筆など》.</div><div class=\"def\"><num>③</num> 剣</div><div class=\"ex\"><i>urbes ferro atque igni vastantur</i> (<author>L<small>IV</small></author>)<span class=\"ext\">町々は剣と火(=戦火)によって荒らされる.</span></div><div class=\"def\"><num>④</num> 武力.</div><div class=\"def\"><num>⑤</num> 剣闘士の試合.</div><div class=\"def\"><num>⑥</num> <SUP>◇</SUP>〘化〙</div><div class=\"ex\"><i>～ pulveratum</i><span class=\"ext\">鉄粉</span></div><div class=\"ex\"><i>～ reductum</i><span class=\"ext\">還元鉄.</span></div>\r\n","<div class=\"hw\">ferrāmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[ferrum]</div><div class=\"def\">鉄器類.</div>\r\n","<div class=\"hw\">ferrāria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://ferrārius\">ferrārius</a>]</div><div class=\"def\">鉄鉱山.</div>\r\n","<div class=\"hw\">ferrārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ferrum]</div><div class=\"def\">鉄の</div><div class=\"ex\"><i>faber ～</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">鍛冶屋.</span></div>\r\n","<div class=\"hw\">ferrātilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://ferrātus\">ferrātus</a>]</div><div class=\"def\">足に鎖をかけられた.</div>\r\n","<div class=\"hw\">ferrātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ferrum]</div><div class=\"def\">鉄でおおわれた, 鉄のついた</div><div class=\"ex\"><i>hasta ferrata</i> (<author>L<small>IV</small></author>)<span class=\"ext\">鉄の穂先の槍.</span></div>\r\n","<div class=\"hw\">ferrātī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[ferratus]</div><div class=\"def\">装甲兵.</div>\r\n","<div class=\"hw\">ferrūgineus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://ferrūgō\">ferrūgō</a>]</div><div class=\"def\">鉄さび色の, くすんだ色の.</div>\r\n","<div class=\"hw\">ferrūgō</div><div class=\"pos\">-ginis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://ferrum\">ferrum</a>]</div><div class=\"def\"><num>①</num> 鉄さび.</div><div class=\"def\"><num>②</num> 鉄さび色, くすんだ色.</div>\r\n","<div class=\"hw\">ferrūmen</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"ori\">[↑<a href=\"entry://ferrum\">ferrum</a>]</div><div class=\"def\"><num>①</num> 接着剤, 接合剤.</div><div class=\"def\"><num>②</num> 鉄さび.</div>\r\n","<div class=\"hw\">ferrūminō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↑<a href=\"entry://ferrūmen\">ferrūmen</a>]</div><div class=\"def\">接合[接着]する, はんだでつける.</div>\r\n","<div class=\"hw\">fertilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[fero]</div><div class=\"def\"><num>①</num> 多産の, 肥沃な 〈+<i>gen</i> [<i>abl</i>]〉.</div><div class=\"def\"><num>②</num> 創造力に富む.</div><div class=\"def\"><num>③</num> 豊作をもたらす, 肥沃にする</div><div class=\"ex\"><i>dea ～</i> (<author>O<small>V</small></author>)<span class=\"ext\">=<a href=\"entry://Cerēs\">Ceres</a>.</span></div>\r\n","<div class=\"hw\">fertiliter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[fertilis]</div><div class=\"def\">実り豊かに.</div>\r\n","<div class=\"hw\">fertilitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://fertilis\">fertilis</a>]</div><div class=\"def\">肥沃, 多産.</div>\r\n","<div class=\"hw\">Fertor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"def\">フェルトル《 (1) Apulia 北部の川;後名 Frento;現 Fortore.(2) Liguria の川;現 Bisagno》.</div>\r\n","<div class=\"hw\">fertum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">供物用菓子.</div>\r\n","<div class=\"hw\">ferula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 〘植〙オオウイキョウ.</div><div class=\"def\"><num>②</num> むち.</div><div class=\"def\"><num>③</num> 杖.</div>\r\n","<div class=\"hw\">ferulāceus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://ferula\">ferula</a>]</div><div class=\"def\"><num>①</num> オオウイキョウで作った.</div><div class=\"def\"><num>②</num> オオウイキョウに似た.</div>\r\n","<div class=\"hw\">ferulāgō</div><div class=\"pos\">-ginis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[ferula]</div><div class=\"def\">〘植〙オオウイキョウ属の劣等品種.</div>\r\n","<div class=\"hw\">ferus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> 野生の, 飼いならされていない.</div><div class=\"def\"><num>②</num> (土地が)耕作されていない, 未開の.</div><div class=\"def\"><num>③</num> 野蛮な, 粗野な.</div><div class=\"def\"><num>④</num> 荒々しい, 激しい</div><div class=\"ex\"><i>fera tempestas</i> (<author>O<small>V</small></author>)<span class=\"ext\">激しいあらし.</span></div><div class=\"def\"><num>⑤</num> 無慈悲な, 残酷な.</div><hr><div class=\"hw\">ferus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">《詩》野獣.</div>\r\n","<div class=\"hw\">fervefacere</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://fervefaciō\">fervefacio</a>.</div>\r\n","<div class=\"hw\">fervefaciō</div><div class=\"pos\">-cere -fēcī -factum, <i>tr</i></div><div class=\"ori\">[ferveo/facio]</div><div class=\"def\">熱くする.</div>\r\n","<div class=\"hw\">fervefactus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://fervefaciō\">fervefacio</a>.</div>\r\n","<div class=\"hw\">fervefēcī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://fervefaciō\">fervefacio</a>.</div>\r\n","<div class=\"hw\">fervens</div><div class=\"pos\">-entis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[ferveo]</div><div class=\"def\"><num>①</num> 熱い, 煮え[沸き]立っている;赤熱した.</div><div class=\"def\"><num>②</num> (水が)泡立っている.</div><div class=\"def\"><num>③</num> 熱烈な, 激した.</div>\r\n","<div class=\"hw\">ferventer</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://fervens\">fervens</a>]</div><div class=\"def\">熱心に, 激しく.</div>\r\n","<div class=\"hw\">fervescō</div><div class=\"pos\">-ere, <i>intr inch</i></div><div class=\"ori\">[↑<a href=\"entry://ferveō\">ferveō</a>]</div><div class=\"def\">熱くなる, 煮え[沸き]立つ.</div>\r\n","<div class=\"hw\">ferveō</div><div class=\"pos\">-ēre ferbuī, <i>intr</i></div><div class=\"def\"><num>①</num> 熱い, 沸騰している.</div><div class=\"def\"><num>②</num> (海や川が)泡立っている, 荒れ狂う.</div><div class=\"def\"><num>③</num> 激しく動いている, 騒然としている.</div><div class=\"def\"><num>④</num> (激情に)燃え立っている, 興奮している.</div>\r\n","<div class=\"hw\">fervidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ferveo]</div><div class=\"def\"><num>①</num> 熱い, 煮え[沸き]立っている, 燃え上がっている.</div><div class=\"def\"><num>②</num> (水が)泡立っている.</div><div class=\"def\"><num>③</num> (酒が)強い.</div><div class=\"def\"><num>④</num> (激情に)燃え立っている, 興奮した.</div><div class=\"def\"><num>⑤</num> 激しやすい, 情熱的な.</div>\r\n","<div class=\"hw\">fervor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[ferveo]</div><div class=\"def\"><num>①</num> 熱.</div><div class=\"def\"><num>②</num> (水が)泡立っていること.</div><div class=\"def\"><num>③</num> 熱情, 激情.</div>\r\n","<div class=\"hw\">fervunculus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m dim</i></div><div class=\"def\">=<a href=\"entry://fūrunculus\">furunculus 2</a>.</div>\r\n","<div class=\"hw\">fervō</div><div class=\"pos\">-ere -vī, <i>intr</i></div><div class=\"def\">=<a href=\"entry://ferveō\">ferveo</a>.</div>\r\n","<div class=\"hw\">ferāciter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[ferax]</div><div class=\"def\">実り豊かに.</div>\r\n","<div class=\"hw\">ferācitās</div><div class=\"pos\">-ātis</div><div class=\"ori\">[ferax]</div><div class=\"def\">多産.</div>\r\n","<div class=\"hw\">ferē</div><div class=\"pos\"><i>adv</i></div><div class=\"def\"><num>①</num> ほとんど, ほぼ</div><div class=\"ex\"><i>non ～</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ほとんど...ない.</span></div><div class=\"def\"><num>②</num> 全く, すっかり.</div><div class=\"def\"><num>③</num> いつもは, 通常, たいてい.</div>\r\n","<div class=\"hw\">ferīna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://ferīnus\">ferīnus</a>]</div><div class=\"def\">野獣の肉.</div>\r\n","<div class=\"hw\">ferīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ferus]</div><div class=\"def\">野獣の</div><div class=\"ex\"><i>caro ferina</i> (<author>S<small>ALL</small></author>)<span class=\"ext\">野獣の肉.</span></div>\r\n","<div class=\"hw\">ferō</div><div class=\"pos\">ferre tulī lātum, <i>tr</i>, <i>intr</i></div><div class=\"def\"><num>①</num> 運ぶ, 持っていく 〈alqm [alqd]〉.</div><div class=\"def\"><num>②</num> </div><div class=\"ex\"><i>ventrem ferre</i> (<author>L<small>IV</small></author>)<span class=\"ext\">妊娠している</span></div><div class=\"ex\"><i>prae se ferre</i> (<author>C<small>IC</small></author>)<span class=\"ext\">示す, 公表する.</span></div><div class=\"def\"><num>③</num> 耐える, 甘受する 〈alqd [alqm];+<i>acc c. inf</i>〉</div><div class=\"ex\"><i>non ferendum est</i> (<author>C<small>IC</small></author>)<span class=\"ext\">耐えがたい</span></div><div class=\"ex\"><i>alqd aegre [moleste, graviter] ferre</i> (<author>C<small>IC</small></author>)<span class=\"ext\">あることに怒る.</span></div><div class=\"def\"><num>④</num> 持ってくる 〈alci alqd;alqd ad alqm;alqd in locum〉.</div><div class=\"def\"><num>⑤</num> 提出する, 提案する</div><div class=\"ex\"><i>suffragium [sententiam] ferre</i> (<author>C<small>IC</small></author>)<span class=\"ext\">投票する</span></div><div class=\"ex\"><i>ferre de re ut</i> ... (<author>C<small>IC</small></author>)<span class=\"ext\">あることについて...するように提案する.</span></div><div class=\"def\"><num>⑥</num> 記帳する</div><div class=\"ex\"><i>acceptum [expensum] ferre</i> (<author>C<small>IC</small></author>)<span class=\"ext\">収入[支出]を記帳する.</span></div><div class=\"def\"><num>⑦</num> もたらす, ひき起こす</div><div class=\"ex\"><i>alci luctum lacrimasque ferre</i> (<author>L<small>IV</small></author>)<span class=\"ext\">ある人に悲しみと涙をもたらす.</span></div><div class=\"def\"><num>⑧</num> 報告する, 知らせる;語る;言い触らす, 広める</div><div class=\"ex\"><i>ferunt</i> 〈+<i>acc c.inf</i>〉<span class=\"ext\">人々は...と言う, ...といううわさである</span></div><div class=\"ex\"><i>fertur</i> 〈+<i>nom c.inf</i>〉<span class=\"ext\">...とうわさされている.</span></div><div class=\"def\"><num>⑨</num> (...と)称する, (...と)みなす</div><div class=\"ex\"><i>Mercurium omnium inventorem artium ferunt</i> (<author>C<small>AES</small></author>)<span class=\"ext\">Mercurius を人々はすべての技術の発明者と信じている.</span></div><div class=\"def\"><num>⑩</num> 賞賛する, ほめそやす 〈alqm [alqd]〉.</div><div class=\"def\"><num>⑪</num> 運び去る, 奪い去る</div><div class=\"ex\"><i>ferre et agere</i> (<author>L<small>IV</small></author>)<span class=\"ext\">略奪する.</span></div><div class=\"def\"><num>⑫</num> かち取る, 獲得する 〈alqd ab [ex] alqo;alqd ex re〉.</div><div class=\"def\"><num>⑬</num> (前へ)動かす</div><div class=\"ex\"><i>signa ferre</i> (<author>C<small>AES</small></author>)<span class=\"ext\">進軍する</span></div><div class=\"ex\"><i>Rhenus citatus fertur</i> (<author>C<small>AES</small></author>)<span class=\"ext\">Rhenus 川は激しい勢いで流れる.</span></div><div class=\"def\"><num>⑭</num> 駆りたてる</div><div class=\"ex\"><i>quo cujusque animus fert, eo discedunt</i> (<author>S<small>ALL</small></author>)<span class=\"ext\">各々気の向く方へ立ち去る.</span></div><div class=\"def\"><num>⑮</num> 通ずる, 至る 〈<i>abs</i>〉</div><div class=\"ex\"><i>via ad Veserim ferebat</i> (<author>L<small>IV</small></author>)<span class=\"ext\">道は Veseris 川に通じていた.</span></div><div class=\"def\"><num>⑯</num> 要求する;認める, 許す 〈alqd;ita, sic, ut〉</div><div class=\"ex\"><i>ut mea fert opinio</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私の見解によれば.</span></div><div class=\"def\"><num>⑰</num> 産出する, 生ずる</div><div class=\"ex\"><i>terra fruges fert</i> (<author>C<small>IC</small></author>)<span class=\"ext\">土地は穀物を産出する.</span></div>\r\n","<div class=\"hw\">ferōcia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[ferox]</div><div class=\"def\"><num>①</num> 強情, 狂暴.</div><div class=\"def\"><num>②</num> (ぶどう酒の味の)きつさ.</div><div class=\"def\"><num>③</num> 勇気, 闘志.</div><div class=\"def\"><num>④</num> 傲慢.</div>\r\n","<div class=\"hw\">ferōciter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[ferox]</div><div class=\"def\"><num>①</num> 狂暴に.</div><div class=\"def\"><num>②</num> 傲慢に.</div><div class=\"def\"><num>③</num> 大胆に.</div>\r\n","<div class=\"hw\">ferōcitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[ferox]</div><div class=\"def\"><num>①</num> 狂暴.</div><div class=\"def\"><num>②</num> 傲慢, 横柄.</div>\r\n","<div class=\"hw\">ferōciō</div><div class=\"pos\">-īre -īvī [-iī], <i>intr</i></div><div class=\"ori\">[ferox]</div><div class=\"def\">荒々しくふるまう, あばれまわる.</div>\r\n","<div class=\"hw\">ferōculus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[ferox]</div><div class=\"def\">(やや)狂暴な.</div>\r\n","<div class=\"hw\">Fescennia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">フェスケンニア《Etruria の町》.</div>\r\n","<div class=\"hw\">Fescennīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Fescennia の</div><div class=\"ex\"><i>～ versus</i> (<author>L<small>IV</small></author>)<span class=\"ext\">(結婚式で歌われた卑猥な)Fescennia 詩.</span></div>\r\n","<div class=\"hw\">fessus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>cf. </i> fatigo]</div><div class=\"def\"><num>①</num> 疲れはてた.</div><div class=\"def\"><num>②</num> 弱った, 衰弱した.</div>\r\n","<div class=\"hw\">festum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://festus\">festus</a>]</div><div class=\"def\">祝祭, 祝日.</div>\r\n","<div class=\"hw\">festus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>cf. </i> feriae]</div><div class=\"def\">祝祭の;祝祭にふさわしい.</div><div class=\"def\"><num>②</num> お祭り気分の;陽気な, 楽しい.</div>\r\n","<div class=\"hw\">festīnanter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[festino]</div><div class=\"def\">急いで, 迅速に.</div>\r\n","<div class=\"hw\">festīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://festīnō\">festīnō</a>]</div><div class=\"def\">急いでいる.</div>\r\n","<div class=\"hw\">festīnābundus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[festino]</div><div class=\"def\">急いでいる.</div>\r\n","<div class=\"hw\">festīnātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[festino]</div><div class=\"def\">急ぐこと, 迅速, 性急.</div>\r\n","<div class=\"hw\">festīnātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://festīnō\">festino</a>.</div>\r\n","<div class=\"hw\">festīnātō</div><div class=\"pos\"><i>adv</i>(<i>abl</i>)</div><div class=\"ori\">[↓<a href=\"entry://festīnātus\">festīnātus</a>]</div><div class=\"def\">急いで, 迅速に.</div>\r\n","<div class=\"hw\">festīnō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>, <i>tr</i></div><div class=\"def\"><num0>Ⅰ</num0> (<i>intr</i>)急ぐ.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>tr</i>)</div><div class=\"def\"><num>①</num> 急がせる, せきたてる.</div><div class=\"def\"><num>②</num> 急いでする.</div>\r\n","<div class=\"hw\">festīvitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://festīvus\">festīvus</a>]</div><div class=\"def\"><num>①</num> お祭り気分;陽気, 愉快.</div><div class=\"def\"><num>②</num> 愛らしさ, 魅力.</div><div class=\"def\"><num>③</num> 機知, しゃれ.</div>\r\n","<div class=\"hw\">festīvus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[festus]</div><div class=\"def\"><num>①</num> 祝祭の.</div><div class=\"def\"><num>②</num> みごとな, すてきな.</div><div class=\"def\"><num>③</num> 陽気な, 感じのよい.</div><div class=\"def\"><num>④</num> 気のきいた, 機知に富んだ.</div>\r\n","<div class=\"hw\">festīvē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[festivus]</div><div class=\"def\"><num>①</num> お祭り気分で;愉快に, 陽気に.</div><div class=\"def\"><num>②</num> みごとに, うまく.</div>\r\n","<div class=\"hw\">festūca<SUP>1</SUP></div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 茎, 軸.</div><div class=\"def\"><num>②</num> (奴隷解放の儀式に用いられた)杖《この杖で奴隷に触れる》.</div><hr><div class=\"hw\">festūca<SUP>2</SUP></div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">=<a href=\"entry://fistūca\">fistuca</a>.</div>\r\n","<div class=\"hw\">festūcātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"def\">=fisticatio.</div>\r\n","<div class=\"hw\">festūcō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"def\">=<a href=\"entry://fistūcō\">fistuco</a>.</div>\r\n","<div class=\"hw\">feudum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">封土.</div>\r\n","<div class=\"hw\">feudālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://feudum\">feudum</a>]</div><div class=\"def\">封土の.</div>\r\n","<div class=\"hw\">fex</div><div class=\"pos\">fēcis, <i>f</i></div><div class=\"def\">=<a href=\"entry://faex\">faex</a>.</div>\r\n","<div class=\"hw\">fiber</div><div class=\"pos\">-brī, <i>m</i></div><div class=\"def\">〘動〙ビーバー, 海狸.</div>\r\n","<div class=\"hw\">fibra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>cf. </i> fimbriae]</div><div class=\"def\"><num>①</num> 繊維.</div><div class=\"def\"><num>②</num> (<i>pl</i>)内臓.</div>\r\n","<div class=\"hw\">fibrocartilāgō</div><div class=\"pos\">-ginis, <SUP>◇</SUP><i>f</i></div><div class=\"def\">〘解〙繊維軟骨.</div>\r\n","<div class=\"hw\">Fibrēnus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">フィブレーヌス《Latium の Arpinum 付近にある川;現 Fibreno》.</div>\r\n","<div class=\"hw\">fibrīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fiber]</div><div class=\"def\">ビーバーの.</div>\r\n","<div class=\"hw\">fibrōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[fibra]</div><div class=\"def\">繊維質の, 繊維状の.</div>\r\n","<div class=\"hw\">fictile</div><div class=\"pos\">-is, <i>n</i></div><div class=\"ori\">[fictilis]</div><div class=\"def\"><num>①</num> 土器, 陶器.</div><div class=\"def\"><num>②</num> 陶製の像.</div>\r\n","<div class=\"hw\">fictilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[fictus]</div><div class=\"def\">陶製の, 土製の.</div>\r\n","<div class=\"hw\">fictiliārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://fictilis\">fictilis</a>]</div><div class=\"def\">《碑》陶工.</div>\r\n","<div class=\"hw\">fictiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[fingo]</div><div class=\"def\"><num>①</num> 形づくること, 形成.</div><div class=\"def\"><num>②</num> 見せかけ</div><div class=\"ex\"><i>personae ～</i> (<author>Q<small>UINT</small></author>)<span class=\"ext\">〘修〙擬人法.</span></div>\r\n","<div class=\"hw\">fictor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[fingo]</div><div class=\"def\"><num>①</num> 彫刻家.</div><div class=\"def\"><num>②</num> 供物用菓子製造者.</div><div class=\"def\"><num>③</num> 製作者, 考案者.</div>\r\n","<div class=\"hw\">fictrix</div><div class=\"pos\">-īcis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://fictor\">fictor</a>]</div><div class=\"def\">製作者《女性》.</div>\r\n","<div class=\"hw\">fictum</div><div class=\"pos\">-ī, <i>n</i>(<i>pp</i>)</div><div class=\"ori\">[fingo]</div><div class=\"def\">偽り, 作り事[話].</div>\r\n","<div class=\"hw\">fictus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[fingo]</div><div class=\"def\"><num>①</num> 真実でない, 偽りの.</div><div class=\"def\"><num>②</num> 見せかけの.</div><div class=\"def\"><num>③</num> 不誠実な.</div>\r\n","<div class=\"hw\">fictē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[fictus]</div><div class=\"def\">偽って.</div>\r\n","<div class=\"hw\">fictīcius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fictus]</div><div class=\"def\">人工の, 作りものの.</div>\r\n","<div class=\"hw\">fictūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[fingo]</div><div class=\"def\"><num>①</num> 形づくること, 形成.</div><div class=\"def\"><num>②</num> 構成, 組成.</div>\r\n","<div class=\"hw\">fideicommissum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[fideicommitto]</div><div class=\"def\">〘法〙信託遺贈.</div>\r\n","<div class=\"hw\">fideicommissus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://fideicommittō\">fideicommitto</a>.</div>\r\n","<div class=\"hw\">fideicommissārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://fideicommissum\">fideicommissum</a>]</div><div class=\"def\">〘法〙信託遺贈の.</div>\r\n","<div class=\"hw\">fideicommittō</div><div class=\"pos\">-ere -mīsī -missum, <i>tr</i></div><div class=\"ori\">[fides<SUP>1</SUP>/committo]</div><div class=\"def\">〘法〙信託遺贈する.</div>\r\n","<div class=\"hw\">fideicommīsī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://fideicommittō\">fideicommitto</a>.</div>\r\n","<div class=\"hw\">fidicen</div><div class=\"pos\">-cinis, <i>m</i></div><div class=\"ori\">[fides<SUP>2</SUP>/cano]</div><div class=\"def\"><num>①</num> 竪琴奏者.</div><div class=\"def\"><num>②</num> 抒情詩人.</div>\r\n","<div class=\"hw\">fidicina</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://fidicen\">fidicen</a>]</div><div class=\"def\">(女性の)竪琴奏者.</div>\r\n","<div class=\"hw\">fidicinius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fidicen]</div><div class=\"def\">竪琴演奏の.</div>\r\n","<div class=\"hw\">fidicula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[fides<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> (小さな)竪琴.</div><div class=\"def\"><num>②</num> (<i>pl</i>)拷問具の一種.</div>\r\n","<div class=\"hw\">fidis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">=<a href=\"entry://fidēs\">fides<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">Fidius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[fides<SUP>1</SUP>]</div><div class=\"def\">(「信義をつかさどる神」の意)Juppiter の添え名の一つ</div><div class=\"ex\"><i>Dius ～</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">信義の神</span></div><div class=\"ex\"><i>medius ～!</i> (<author>C<small>IC</small></author>)(= ita me Dius ～ juvet)<span class=\"ext\">神よ, 私を助けたまえ.</span></div>\r\n","<div class=\"hw\">fidējubeō</div><div class=\"pos\">-ēre -jussī -jussum, <i>intr</i></div><div class=\"ori\">[fides<SUP>1</SUP>/jubeo]</div><div class=\"def\">〘法〙保証人になる, 保証する.</div>\r\n","<div class=\"hw\">fidējussiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[fidejubeo]</div><div class=\"def\">〘法〙保証人になること.</div>\r\n","<div class=\"hw\">fidējussor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[fidejubeo]</div><div class=\"def\">〘法〙保証人, 担保人.</div>\r\n","<div class=\"hw\">fidējussus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://fidējubeō\">fidejubeo</a>.</div>\r\n","<div class=\"hw\">fidējussī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://fidējubeō\">fidejubeo</a>.</div>\r\n","<div class=\"hw\">fidēlia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">(大きな)壺, 手桶</div><div class=\"ex\"><i>de eadem fidelia duo parietes dealbare</i> (<author>C<small>IC</small></author>)<span class=\"ext\">同じ桶で二つの壁を白く塗る(=一石二鳥).</span></div>\r\n","<div class=\"hw\">fidēlis<SUP>1</SUP></div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[fides<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 誠実な, 信頼できる.</div><div class=\"def\"><num>②</num> 確固たる, 確実な</div><div class=\"ex\"><i>lorica ～</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">がんじょうな甲冑.</span></div><hr><div class=\"hw\">fidēlis<SUP>2</SUP></div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\"><num>①</num> 親友.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 信者, 信徒.</div>\r\n","<div class=\"hw\">fidēliter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[fidelis]</div><div class=\"def\"><num>①</num> 誠実に, 忠実に.</div><div class=\"def\"><num>②</num> 確実に, しっかりと.</div>\r\n","<div class=\"hw\">fidēlitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[fidelis]</div><div class=\"def\">信頼できること, 誠実.</div>\r\n","<div class=\"hw\">fidēprōmittō</div><div class=\"pos\">-ere, <i>intr</i></div><div class=\"ori\">[↓<a href=\"entry://fidēs\">fidēs<SUP>1</SUP></a>/promitto]</div><div class=\"def\">〘法〙保証人になる.</div>\r\n","<div class=\"hw\">fidēs<SUP>1</SUP></div><div class=\"pos\">-eī, <i>f</i></div><div class=\"ori\">[fido]</div><div class=\"def\"><num>①</num> 信頼, 信用.</div><div class=\"def\"><num>②</num> 信義</div><div class=\"ex\"><i>tuam fidem obsecro</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">あなたの信義にかけてお願いだ.</span></div><div class=\"def\"><num>③</num> 誠実, 正直</div><div class=\"ex\"><i>(ex)bonā fide</i> (<author>C<small>IC</small></author>)<span class=\"ext\">誠意をもって.</span></div><div class=\"def\"><num>④</num> 忠誠, 忠実.</div><div class=\"def\"><num>⑤</num> 約束, 誓約</div><div class=\"ex\"><i>meā fide</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">誓って, (私の)名誉にかけて.</span></div><div class=\"def\"><num>⑥</num> 約束の実行[実現]</div><div class=\"ex\"><i>dicta ～ sequitur</i> (<author>O<small>V</small></author>)<span class=\"ext\">ことばを実行が追いかける(=そのことばどおりになる).</span></div><div class=\"def\"><num>⑦</num> 保証.</div><div class=\"def\"><num>⑧</num> 証拠, 確証.</div><hr><div class=\"hw\">fidēs<SUP>2</SUP></div><div class=\"pos\">-ium, <i>f pl</i>, <B>fidēs</B> -is, <i>f</i></div><div class=\"def\"><num>①</num> 竪琴.</div><div class=\"def\"><num>②</num> 竪琴の弦.</div><div class=\"def\"><num>③</num> 抒情詩.</div><div class=\"def\"><num>④</num> (<i>sg</i>)〘天〙琴座(=<a href=\"entry://lyra\">Lyra</a>).</div>\r\n","<div class=\"hw\">fidī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://findō\">findo</a>.</div>\r\n","<div class=\"hw\">fierī</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://fīō\">fio</a>.</div>\r\n","<div class=\"hw\">figlīna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[figlinus]</div><div class=\"def\"><num>①</num> (<i>sc. </i> ars)製陶術.</div><div class=\"def\"><num>②</num> 製陶所.</div>\r\n","<div class=\"hw\">figlīnum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://figlīnus\">figlīnus</a>]</div><div class=\"def\">陶器.</div>\r\n","<div class=\"hw\">figlīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[figulus]</div><div class=\"def\">陶工の</div><div class=\"ex\"><i>opus figlinum</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">陶器.</span></div>\r\n","<div class=\"hw\">figmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[fingo]</div><div class=\"def\"><num>①</num> 造ること.</div><div class=\"def\"><num>②</num> 像.</div><div class=\"def\"><num>③</num> 作り事, 虚構.</div>\r\n","<div class=\"hw\">figulus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[fingo]</div><div class=\"def\">陶工.</div>\r\n","<div class=\"hw\">Figulus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">フィグルス《ローマ人の家名;特に <i>P. Nigidius ～</i>, Cicero と同時代の学者》.</div>\r\n","<div class=\"hw\">figulāris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[figulus]</div><div class=\"def\">陶工の</div><div class=\"ex\"><i>creta ～</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">陶土.</span></div>\r\n","<div class=\"hw\">figulīn-</div><div class=\"def\">⇒figlin-.</div>\r\n","<div class=\"hw\">figūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[fingo]</div><div class=\"def\"><num>①</num> 姿, 形.</div><div class=\"def\"><num>②</num> 外観, 外形;様相.</div><div class=\"def\"><num>③</num> 体位, 姿勢;態度.</div><div class=\"def\"><num>④</num> 〘哲〙原子.</div><div class=\"def\"><num>⑤</num> 像;幻影.</div><div class=\"def\"><num>⑥</num> 種類, 様式, 型.</div><div class=\"def\"><num>⑦</num> 〘文〙語形.</div><div class=\"def\"><num>⑧</num> 成句, 熟語.</div><div class=\"def\"><num>⑨</num> 〘修〙文彩;あてこすり.</div>\r\n","<div class=\"hw\">figūrāliter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[figura]</div><div class=\"def\">比喩的に.</div>\r\n","<div class=\"hw\">figūrālitās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↑<a href=\"entry://figūra\">figūra</a>]</div><div class=\"def\">比喩的表現.</div>\r\n","<div class=\"hw\">figūrātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://figūrō\">figūrō</a>]</div><div class=\"def\"><num>①</num> 形態, 形状.</div><div class=\"def\"><num>②</num> 〘文〙語形成.</div><div class=\"def\"><num>③</num> 想像, 表象;心象.</div><div class=\"def\"><num>④</num> 〘修〙比喩的表現, 文彩.</div>\r\n","<div class=\"hw\">figūrō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[figura]</div><div class=\"def\"><num>①</num> 形づくる, 形成する.</div><div class=\"def\"><num>②</num> 想像する.</div><div class=\"def\"><num>③</num> (文章を)修辞的表現で飾る.</div>\r\n","<div class=\"hw\">filicula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[filix]</div><div class=\"def\">〘植〙エゾデンダ属のシダ類.</div>\r\n","<div class=\"hw\">filicātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[filix]</div><div class=\"def\">シダの葉の文様を彫った.</div>\r\n","<div class=\"hw\">filix</div><div class=\"pos\">-icis, <i>f</i></div><div class=\"def\">〘植〙シダ.</div>\r\n","<div class=\"hw\">filtrum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[<i>G</i>]</div><div class=\"def\"><num>①</num> フェルト.</div><div class=\"def\"><num>②</num> フィルター, 瀘過布.</div>\r\n","<div class=\"hw\">Fimbria</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"def\">フィンブリア《Flavia 氏族に属する家名》.</div>\r\n","<div class=\"hw\">fimbriae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"def\"><num>①</num> ふさ飾り;へり, 縁</div><div class=\"ex\"><i>cincinnorum ～</i> (<author>C<small>IC</small></author>)<span class=\"ext\">巻き毛の先.</span></div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘解〙ふさ.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘動・植〙ふさ状へり.</div>\r\n","<div class=\"hw\">fimbriātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://fimbriae\">fimbriae</a>]</div><div class=\"def\">ふさ飾りの付いた;ぎざぎざのある.</div>\r\n","<div class=\"hw\">fimus</div><div class=\"pos\">-ī, <i>m</i>, <B>fimum</B> -ī, <i>n</i></div><div class=\"def\"><num>①</num> (動物の)糞, 排泄物.</div><div class=\"def\"><num>②</num> 泥, ぬかるみ.</div>\r\n","<div class=\"hw\">fimētum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://fimus\">fimus</a>]</div><div class=\"def\">糞の山.</div>\r\n","<div class=\"hw\">findō</div><div class=\"pos\">-ere fidī fissum, <i>tr</i></div><div class=\"def\">割る, 裂く.</div>\r\n","<div class=\"hw\">fingibilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://fingō\">fingō</a>]</div><div class=\"def\">想像上の, 架空の.</div>\r\n","<div class=\"hw\">fingō</div><div class=\"pos\">-ere finxī fictum, <i>tr</i></div><div class=\"def\"><num>①</num> 形づくる, 形成する.</div><div class=\"def\"><num>②</num> 創造する, 表現する 〈alqd ex [de] re〉</div><div class=\"ex\"><i>ars fingendi</i> (<author>C<small>IC</small></author>)<span class=\"ext\">彫刻術.</span></div><div class=\"def\"><num>③</num> 整える, 調整する</div><div class=\"ex\"><i>fingere crinem</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">髪形を整える.</span></div><div class=\"def\"><num>④</num> 作り変える, 改造する.</div><div class=\"def\"><num>⑤</num> 仕込む, 教える.</div><div class=\"def\"><num>⑥</num> 心に描く, 想像する 〈alqd;+<i>acc c.inf</i>〉.</div><div class=\"def\"><num>⑦</num> でっちあげる, 捏造する;見せかける.</div>\r\n","<div class=\"hw\">finxī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://fingō\">fingo</a>.</div>\r\n","<div class=\"hw\">firmiter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[firmus]</div><div class=\"def\">しっかりと, 強固に.</div>\r\n","<div class=\"hw\">firmitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[firmus]</div><div class=\"def\"><num>①</num> 強いこと, 強固.</div><div class=\"def\"><num>②</num> 安定, 不動.</div><div class=\"def\"><num>③</num> (志操の)堅固, 不屈.</div>\r\n","<div class=\"hw\">firmitūdō</div><div class=\"pos\">-dinis, <i>f</i></div><div class=\"def\">=<a href=\"entry://firmitās\">firmitas</a>.</div>\r\n","<div class=\"hw\">Firmum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">フィルムム《Picenum の町;現 Fermo》.</div>\r\n","<div class=\"hw\">firmus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> 強固な, 強い, しっかりした 〈ad alqd;in re;contra [adversus] alqd〉.</div><div class=\"def\"><num>②</num> 健康な.</div><div class=\"def\"><num>③</num> 確乎不動の, 断固とした.</div><div class=\"def\"><num>④</num> 信頼できる, 確実な.</div>\r\n","<div class=\"hw\">firmāmen</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"ori\">[firmo]</div><div class=\"def\">支え.</div>\r\n","<div class=\"hw\">firmāmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[firmo]</div><div class=\"def\"><num>①</num> 支え, 支柱;土台.</div><div class=\"def\"><num>②</num> 〘修〙要点.</div>\r\n","<div class=\"hw\">Firmānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Firmum の.</div><div class=\"hw2\"><b>Firmānī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Firmum の住民.</div>\r\n","<div class=\"hw\">firmātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[firmo]</div><div class=\"def\">確立者.</div>\r\n","<div class=\"hw\">firmē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[firmus]</div><div class=\"def\">確固として, しっかりと.</div>\r\n","<div class=\"hw\">firmō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[firmus]</div><div class=\"def\"><num>①</num> 強くする, 強固にする.</div><div class=\"def\"><num>②</num> 確実にする 〈alqd re〉</div><div class=\"ex\"><i>perpetuam firmare pacem amicitiamque</i> (<author>L<small>IV</small></author>)<span class=\"ext\">永続的平和と友好関係を確立する.</span></div><div class=\"def\"><num>③</num> 力づける, 励ます.</div><div class=\"def\"><num>④</num> 保証する.</div><div class=\"def\"><num>⑤</num> 立証する.</div>\r\n","<div class=\"hw\">fiscella</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[↓<a href=\"entry://fiscina\">fiscina</a>]</div><div class=\"def\">(小さな)かご.</div>\r\n","<div class=\"hw\">fiscina</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://fiscus\">fiscus</a>]</div><div class=\"def\">(小さな)かご.</div>\r\n","<div class=\"hw\">fiscus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 財布.</div><div class=\"def\"><num>②</num> 国庫.</div><div class=\"def\"><num>③</num> (帝政時代の)元首金庫.</div>\r\n","<div class=\"hw\">fiscālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[fiscus]</div><div class=\"def\">国庫の, 財政の.</div>\r\n","<div class=\"hw\">fissilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[findo]</div><div class=\"def\"><num>①</num> 割れ[裂け]やすい.</div><div class=\"def\"><num>②</num> 割れた, 裂けた.</div>\r\n","<div class=\"hw\">fissiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[findo]</div><div class=\"def\">割る[裂く]こと.</div>\r\n","<div class=\"hw\">fissum</div><div class=\"pos\">-ī, <i>n</i>(<i>pp</i>)</div><div class=\"ori\">[findo]</div><div class=\"def\">割れ目, 裂け目.</div>\r\n","<div class=\"hw\">fissus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://findō\">findo</a>.</div>\r\n","<div class=\"hw\">fissūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[findo]</div><div class=\"def\"><num>①</num> 亀裂, 割れ目, 裂け目.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘解〙裂(溝).</div>\r\n","<div class=\"hw\">fistula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 管;送水管.</div><div class=\"def\"><num>②</num> 葦笛, 牧笛;調子笛.</div><div class=\"def\"><num>③</num> (中空の)茎;葦ペン.</div><div class=\"def\"><num>④</num> 管状器官</div><div class=\"ex\"><i>～ urinae</i> (<author>C<small>ELS</small></author>)<span class=\"ext\">尿道.</span></div><div class=\"def\"><num>⑤</num> 〘病〙瘻管(孔).</div><div class=\"def\"><num>⑥</num> ひき臼の一種.</div>\r\n","<div class=\"hw\">fistulor</div><div class=\"pos\">-ārī, <SUP>◇</SUP><i>intr dep</i></div><div class=\"def\">笛を吹く.</div>\r\n","<div class=\"hw\">fistulātim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[fistulatus]</div><div class=\"def\">噴出して.</div>\r\n","<div class=\"hw\">fistulātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[fistula]</div><div class=\"def\">笛を吹く人.</div>\r\n","<div class=\"hw\">fistulātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fistula]</div><div class=\"def\">管のついた;管状の.</div>\r\n","<div class=\"hw\">fistulōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fistula]</div><div class=\"def\"><num>①</num> 穴の多い, 多孔(性)の.</div><div class=\"def\"><num>②</num> 管状の.</div><div class=\"def\"><num>③</num> 〘病〙瘻性の.</div>\r\n","<div class=\"hw\">fistūca</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">杭打ち機.</div>\r\n","<div class=\"hw\">fistūcātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://fistūcō\">fistūcō</a>]</div><div class=\"def\">打ち込むこと.</div>\r\n","<div class=\"hw\">fistūcō</div><div class=\"pos\">-āre -ātum, <i>tr</i></div><div class=\"ori\">[fistuca]</div><div class=\"def\">打ち込む.</div>\r\n","<div class=\"hw\">fixus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[figo]</div><div class=\"def\">不動の, 不変の.</div>\r\n","<div class=\"hw\">fixī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://fīgō\">figo</a>.</div>\r\n","<div class=\"hw\">flaccescō</div><div class=\"pos\">-ere flaccuī, <i>intr inch</i></div><div class=\"ori\">[↑<a href=\"entry://flacceō\">flacceō</a>]</div><div class=\"def\">しおれる;衰える.</div>\r\n","<div class=\"hw\">flacceō</div><div class=\"pos\">-ēre, <i>intr</i></div><div class=\"ori\">[flaccus]</div><div class=\"def\">だれている, 衰えている.</div>\r\n","<div class=\"hw\">flaccidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[flaccus]</div><div class=\"def\"><num>①</num> たれた, たるんだ.</div><div class=\"def\"><num>②</num> 衰えた, 弱い.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘病・解〙弛緩(性)の</div><div class=\"ex\"><i>pars flaccida</i><span class=\"ext\">弛緩部.</span></div>\r\n","<div class=\"hw\">flaccus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> たれた, たるんだ.</div><div class=\"def\"><num>②</num> たれ耳の.</div>\r\n","<div class=\"hw\">Flaccus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">フラックス《ローマ人の家名;特に <i>Q. Horatius ～</i>, 詩人(前65‐8)》.</div>\r\n","<div class=\"hw\">flaccuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://flaccescō\">flaccesco</a>.</div>\r\n","<div class=\"hw\">flagellum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[flagrum]</div><div class=\"def\"><num>①</num> むち.</div><div class=\"def\"><num>②</num> (投げ槍用の)革ひも.</div><div class=\"def\"><num>③</num> 若枝.</div><div class=\"def\"><num>④</num> 〘動〙触手.</div>\r\n","<div class=\"hw\">flagellātae</div><div class=\"pos\">-ārum, <SUP>◇</SUP><i>f pl</i></div><div class=\"def\">〘植〙鞭毛藻綱.</div>\r\n","<div class=\"hw\">flagellātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://flagellō\">flagellō</a>]</div><div class=\"def\">むち打つこと.</div>\r\n","<div class=\"hw\">flagellō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://flagellum\">flagellum</a>]</div><div class=\"def\">むち打つ;(むち打つように)強打する.</div>\r\n","<div class=\"hw\">flagrans</div><div class=\"pos\">-antis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[flagro]</div><div class=\"def\"><num>①</num> 燃えている;光り輝く.</div><div class=\"def\"><num>②</num> 激しい, 情熱的な, 熱烈な.</div><div class=\"def\"><num>③</num> 隆盛の.</div><div class=\"def\"><num>④</num> 極悪の, 目に余る.</div>\r\n","<div class=\"hw\">flagranter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://flagrans\">flagrans</a>]</div><div class=\"def\">激しく, 熱烈に.</div>\r\n","<div class=\"hw\">flagrantia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[flagrans]</div><div class=\"def\">火, 炎, 輝き.</div>\r\n","<div class=\"hw\">flagrum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">むち.</div>\r\n","<div class=\"hw\">flagrō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"def\"><num>①</num> 燃える.</div><div class=\"def\"><num>②</num> 光り輝く.</div><div class=\"def\"><num>③</num> 興奮する, (激情に)燃える 〈re〉</div><div class=\"ex\"><i>flagrare amore</i> (<author>C<small>IC</small></author>)<span class=\"ext\">恋いこがれる.</span></div><div class=\"def\"><num>④</num> 騒然とする, 沸き返る.</div><div class=\"def\"><num>⑤</num> (...を)受ける, こうむる 〈re〉</div><div class=\"ex\"><i>flagrare infamiā</i> (<author>C<small>IC</small></author>)<span class=\"ext\">恥辱にまみれる.</span></div>\r\n","<div class=\"hw\">flamma</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>cf. </i> flagro]</div><div class=\"def\"><num>①</num> 炎, 火.</div><div class=\"def\"><num>②</num> たいまつ.</div><div class=\"def\"><num>③</num> (星・月などの)輝き;稲光.</div><div class=\"def\"><num>④</num> 情火, 激情.</div><div class=\"def\"><num>⑤</num> 破滅(させるもの).</div>\r\n","<div class=\"hw\">flammeolum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[flammeum]</div><div class=\"def\">(小さな)花嫁のベール.</div>\r\n","<div class=\"hw\">flammeolus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[flammeus]</div><div class=\"def\">炎色の.</div>\r\n","<div class=\"hw\">flammeum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://flammeus\">flammeus</a>]</div><div class=\"def\">(炎色をした)花嫁のベール.</div>\r\n","<div class=\"hw\">flammeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[flamma]</div><div class=\"def\"><num>①</num> 火の, 燃えている.</div><div class=\"def\"><num>②</num> 炎色の, 赤みがかった.</div><div class=\"def\"><num>③</num> 光り輝く.</div>\r\n","<div class=\"hw\">flammeārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[flammeum]</div><div class=\"def\">布を炎色に染める人.</div>\r\n","<div class=\"hw\">flammidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://flammeus\">flammeus</a>.</div>\r\n","<div class=\"hw\">flammifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[flamma/fero]</div><div class=\"def\">《詩》炎を運ぶ, 燃えている.</div>\r\n","<div class=\"hw\">flammiger</div><div class=\"pos\">-gera -gerum, <i>adj</i></div><div class=\"ori\">[flamma/gero]</div><div class=\"def\">《詩》=<a href=\"entry://flammifer\">flammifer</a>.</div>\r\n","<div class=\"hw\">flammigō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"ori\">[flamma/ago]</div><div class=\"def\">炎を発する.</div>\r\n","<div class=\"hw\">flammivomus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[flamma/vomo]</div><div class=\"def\">炎を吐いている.</div>\r\n","<div class=\"hw\">flammula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[flamma]</div><div class=\"def\">(小さな)炎.</div>\r\n","<div class=\"hw\">flammāris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://flamma\">flamma</a>]</div><div class=\"def\">炎色の.</div>\r\n","<div class=\"hw\">flammārius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://flammeārius\">flammearius</a>.</div>\r\n","<div class=\"hw\">flammātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[flammo]</div><div class=\"def\"><num>①</num> 火のような, 燃えている.</div><div class=\"def\"><num>②</num> 紅潮した.</div><div class=\"def\"><num>③</num> (のどが)からからに渇いた.</div>\r\n","<div class=\"hw\">flammō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>, <i>tr</i></div><div class=\"ori\">[flamma]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>intr</i>)燃える, 光り輝く.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>tr</i>)燃やす, 火をつける.</div>\r\n","<div class=\"hw\">flascō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>m</i></div><div class=\"def\">(ぶどう酒の)瓶.</div>\r\n","<div class=\"hw\">flectō</div><div class=\"pos\">-ere flexī flexum, <i>tr</i>, <i>intr</i></div><div class=\"def\"><num0>Ⅰ</num0> (<i>tr</i>)</div><div class=\"def\"><num>①</num> 曲げる.</div><div class=\"def\"><num>②</num> 変える 〈alqm [alqd]〉.</div><div class=\"def\"><num>③</num> 気持を変えさせる, 心を動かす[和らげる].</div><div class=\"def\"><num>④</num> 迂回する, 回航する.</div><div class=\"def\"><num>⑤</num> 向きを変える, 転ずる 〈alqm [alqd] ad [in] alqd〉</div><div class=\"ex\"><i>de foro in Capitolium currūs flectere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">戦車(の進行方向)を広場から Capitolium へと転ずる.</span></div><div class=\"def\"><num>⑥</num> (声・音の)調子を変える, 抑揚を付ける.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>intr</i>)向かう, 行く, 進む 〈in [ad] alqd〉.</div>\r\n","<div class=\"hw\">flexanimus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[flecto/animus]</div><div class=\"def\"><num>①</num> 心を動かす, 説得力のある.</div><div class=\"def\"><num>②</num> 狂乱した.</div>\r\n","<div class=\"hw\">flexibilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[flexus<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 曲げやすい, しなやかな.</div><div class=\"def\"><num>②</num> 適合できる, 融通のきく.</div><div class=\"def\"><num>③</num> 不安定な, 変わりやすい.</div>\r\n","<div class=\"hw\">flexibilitās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↑<a href=\"entry://flexibilis\">flexibilis</a>]</div><div class=\"def\">曲げやすいこと, 柔軟性.</div>\r\n","<div class=\"hw\">flexilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[flexus<SUP>1</SUP>]</div><div class=\"def\">曲げやすい, しなやかな.</div>\r\n","<div class=\"hw\">flexiloquus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[flexus<SUP>1</SUP>/loquor]</div><div class=\"def\">両義にとれる, あいまいな.</div>\r\n","<div class=\"hw\">flexipēs</div><div class=\"pos\">-pedis, <i>adj</i></div><div class=\"ori\">[flecto/pes]</div><div class=\"def\">(枝が)巻きつく.</div>\r\n","<div class=\"hw\">flexiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[flecto]</div><div class=\"def\"><num>①</num> 曲げること.</div><div class=\"def\"><num>②</num> 回り道.</div><div class=\"def\"><num>③</num> (声の)抑揚.</div>\r\n","<div class=\"hw\">flexor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[flecto]</div><div class=\"def\">〘解〙屈筋.</div>\r\n","<div class=\"hw\">flexus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[flecto]</div><div class=\"def\"><num>①</num> 曲がった, ねじれた, 曲がりくねった.</div><div class=\"def\"><num>②</num> (声が)抑揚の付いた.</div><div class=\"def\"><num>③</num> 〘文〙曲アクセントの付いた.</div><hr><div class=\"hw\">flexus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 曲げること, 曲がること.</div><div class=\"def\"><num>②</num> 方向を変えること</div><div class=\"ex\"><i>in quo ～ est ad iter Arpinas</i> (<author>C<small>IC</small></author>)<span class=\"ext\">Arpinum への道が分岐しているところで.</span></div><div class=\"def\"><num>③</num> 湾曲部.</div><div class=\"def\"><num>④</num> 転換点, 変わりめ.</div><div class=\"def\"><num>⑤</num> (声の)抑揚.</div>\r\n","<div class=\"hw\">flexuōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[flexus<SUP>1</SUP>]</div><div class=\"def\">曲がりくねった.</div>\r\n","<div class=\"hw\">flexuōsē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://flexuōsus\">flexuōsus</a>]</div><div class=\"def\">曲がりくねって.</div>\r\n","<div class=\"hw\">flexī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://flectō\">flecto</a>.</div>\r\n","<div class=\"hw\">flexō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr freq</i></div><div class=\"ori\">[flecto]</div><div class=\"def\">曲げる.</div>\r\n","<div class=\"hw\">flexūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[flecto]</div><div class=\"def\"><num>①</num> 曲げること, 湾曲, 屈折.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘解〙曲, 湾曲</div><div class=\"ex\"><i>～ duodenojejunalis</i><span class=\"ext\">十二指腸空腸曲.</span></div>\r\n","<div class=\"hw\">fleō</div><div class=\"pos\">-ēre flēvī flētum, <i>intr</i>, <i>tr</i></div><div class=\"def\"><num0>Ⅰ</num0> (<i>intr</i>)</div><div class=\"def\"><num>①</num> 泣く, 嘆く, 悲しむ 〈de re〉.</div><div class=\"def\"><num>②</num> したたる.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>tr</i>)悲しむ, 嘆く 〈alqm [alqd];+<i>acc c.inf</i>〉.</div>\r\n","<div class=\"hw\">flictus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://flīgō\">flīgō</a>]</div><div class=\"def\">衝突.</div>\r\n","<div class=\"hw\">flocculus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m dim</i></div><div class=\"ori\">[↓<a href=\"entry://floccus\">floccus</a>]</div><div class=\"def\"><num>①</num> (小さな)羊毛の塊り.</div><div class=\"def\"><num>②</num> 〘解〙(小脳の)片葉.</div>\r\n","<div class=\"hw\">floccus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 羊毛の塊り.</div><div class=\"def\"><num>②</num> つまらないもの</div><div class=\"ex\"><i>flocci non facere</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">何とも思わない, 少しもかまわない.</span></div>\r\n","<div class=\"hw\">floccōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[floccus]</div><div class=\"def\">羊毛の多い.</div>\r\n","<div class=\"hw\">floscellus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m dim</i></div><div class=\"ori\">[↑<a href=\"entry://flōs\">flōs</a>]</div><div class=\"def\">(小さな)花.</div>\r\n","<div class=\"hw\">floscula</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f dim</i></div><div class=\"def\">=<a href=\"entry://flosculus\">flosculus</a>.</div>\r\n","<div class=\"hw\">flosculus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[flos]</div><div class=\"def\"><num>①</num> (小さな)花.</div><div class=\"def\"><num>②</num> 精華, 最良の部分.</div><div class=\"def\"><num>③</num> 装飾.</div>\r\n","<div class=\"hw\">flucticola</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[fluctus/colo<SUP>2</SUP>]</div><div class=\"def\">波の中に住む.</div>\r\n","<div class=\"hw\">flucticolor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[fluctus/color]</div><div class=\"def\">海の色の.</div>\r\n","<div class=\"hw\">flucticulus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[fluctus]</div><div class=\"def\">小波, さざなみ.</div>\r\n","<div class=\"hw\">fluctifragus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fluctus/frango]</div><div class=\"def\">波を砕く.</div>\r\n","<div class=\"hw\">fluctigenus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[fluctus/gigno]</div><div class=\"def\">波の中で生まれた.</div>\r\n","<div class=\"hw\">fluctiger</div><div class=\"pos\">-era -erum, <i>adj</i></div><div class=\"ori\">[fluctus/gero]</div><div class=\"def\">波に運ばれる.</div>\r\n","<div class=\"hw\">fluctiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[fluo]</div><div class=\"def\">流れること, 流出.</div>\r\n","<div class=\"hw\">fluctuor</div><div class=\"pos\">-ārī fluctuātus sum, <i>intr dep</i></div><div class=\"def\">=<a href=\"entry://fluctuō\">fluctuo</a>.</div>\r\n","<div class=\"hw\">fluctus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[fluo]</div><div class=\"def\">波, 大波;流れ</div><div class=\"ex\"><i>excitare fluctūs in simpulo</i> (<author>C<small>IC</small></author>)<span class=\"ext\">ひしゃくの中で大波を起こす(=空騒ぎする).</span></div>\r\n","<div class=\"hw\">fluctuābundus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[fluctuo]</div><div class=\"def\">揺れ動く.</div>\r\n","<div class=\"hw\">fluctuātim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[fluctuo]</div><div class=\"def\">打ち寄せる波のように.</div>\r\n","<div class=\"hw\">fluctuātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://fluctuō\">fluctuō</a>]</div><div class=\"def\"><num>①</num> 揺れる動き.</div><div class=\"def\"><num>②</num> 優柔不断, 気迷い.</div>\r\n","<div class=\"hw\">fluctuō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"ori\">[fluctus]</div><div class=\"def\"><num>①</num> 波打つ, うねる.</div><div class=\"def\"><num>②</num> (心が)動揺する, かき乱される.</div><div class=\"def\"><num>③</num> ためらう, 気迷う.</div>\r\n","<div class=\"hw\">fluctuōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://fluctus\">fluctus</a>]</div><div class=\"def\">大波の立つ, しけの.</div>\r\n","<div class=\"hw\">fluens</div><div class=\"pos\">-entis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[fluo]</div><div class=\"def\"><num>①</num> 流れる.</div><div class=\"def\"><num>②</num> 流暢な.</div><div class=\"def\"><num>③</num> だらしのない, 放縦な.</div><div class=\"def\"><num>④</num> (演説が)締まりのない, 散漫な.</div>\r\n","<div class=\"hw\">fluenter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://fluens\">fluens</a>]</div><div class=\"def\">流れるように.</div>\r\n","<div class=\"hw\">fluentisonus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fluentum/sono]</div><div class=\"def\">波の音が響きわたる.</div>\r\n","<div class=\"hw\">fluentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[fluo]</div><div class=\"def\">(通例 <i>pl</i>)流れ, 川.</div>\r\n","<div class=\"hw\">fluentō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://fluentum\">fluentum</a>]</div><div class=\"def\">潤す, ぬらす.</div>\r\n","<div class=\"hw\">fluidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fluo]</div><div class=\"def\"><num>①</num> 流れる.</div><div class=\"def\"><num>②</num> たるんだ, 柔らかい;力のない.</div><div class=\"def\"><num>③</num> 変わりやすい, はかない.</div>\r\n","<div class=\"hw\">fluidō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://fluidus\">fluidus</a>]</div><div class=\"def\">液体にする, 溶かす.</div>\r\n","<div class=\"hw\">fluitō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr freq</i></div><div class=\"ori\">[fluo]</div><div class=\"def\"><num>①</num> 流れる.</div><div class=\"def\"><num>②</num> 浮かぶ, 漂う.</div><div class=\"def\"><num>③</num> (髪・衣服などが)波打つ, 揺れる</div><div class=\"ex\"><i>vela fluitantia</i> (<author>O<small>V</small></author>)<span class=\"ext\">風にはためく帆.</span></div><div class=\"def\"><num>④</num> 動揺する.</div>\r\n","<div class=\"hw\">fluor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[↑<a href=\"entry://fluō\">fluō</a>]</div><div class=\"def\"><num>①</num> 流れ.</div><div class=\"def\"><num>②</num> 〘病〙(血液・体液の)異常流出;下痢.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘化〙フッ素.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>〘鉱〙ほたる石.</div>\r\n","<div class=\"hw\">fluvidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://fluidus\">fluidus</a>.</div>\r\n","<div class=\"hw\">fluviolus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m dim</i></div><div class=\"ori\">[↓<a href=\"entry://fluvius\">fluvius</a>]</div><div class=\"def\">小川.</div>\r\n","<div class=\"hw\">fluvius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">川, 流れ;川の水.</div>\r\n","<div class=\"hw\">fluviālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[fluvius]</div><div class=\"def\">川の.</div>\r\n","<div class=\"hw\">fluviāticus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://fluviālis\">fluvialis</a>.</div>\r\n","<div class=\"hw\">fluviātilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[fluvius]</div><div class=\"def\">川の.</div>\r\n","<div class=\"hw\">fluviātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fluvius]</div><div class=\"def\">(川の水に)浸された.</div>\r\n","<div class=\"hw\">fluxilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">流動性の.</div>\r\n","<div class=\"hw\">fluxus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[fluo]</div><div class=\"def\"><num>①</num> 流れる, 流動性の.</div><div class=\"def\"><num>②</num> (髪・衣服などが)たれている, 波打つ.</div><div class=\"def\"><num>③</num> 力のない, たるんだ.</div><div class=\"def\"><num>④</num> 不安定な, 動揺する</div><div class=\"ex\"><i>gloria fluxa</i> (<author>S<small>ALL</small></author>)<span class=\"ext\">束の間の栄光.</span></div><hr><div class=\"hw\">fluxus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">流れ;流出.</div>\r\n","<div class=\"hw\">fluxē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[fluxus<SUP>1</SUP>]</div><div class=\"def\">なげやりに.</div>\r\n","<div class=\"hw\">fluxī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://fluō\">fluo</a>.</div>\r\n","<div class=\"hw\">fluō</div><div class=\"pos\">-ere fluxī fluxum, <i>intr</i></div><div class=\"def\"><num>①</num> (液体が)流れる.</div><div class=\"def\"><num>②</num> 流れ出る, あふれ出る 〈re〉</div><div class=\"ex\"><i>sudore fluentia bracchia</i> (<author>O<small>V</small></author>)<span class=\"ext\">汗がしたたっている腕.</span></div><div class=\"def\"><num>③</num> (液体でないものが)流れる, 流出する</div><div class=\"ex\"><i>turba fluit castris</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">軍勢が陣営から流れ出る.</span></div><div class=\"def\"><num>④</num> 広がる</div><div class=\"ex\"><i>Pythagorae doctrina longe lateque fluit</i> (<author>C<small>IC</small></author>)<span class=\"ext\">Pythagoras の教説は広範囲に広まっている.</span></div><div class=\"def\"><num>⑤</num> 起こる, 生まれる 〈a [ex] re〉.</div><div class=\"def\"><num>⑥</num> 進む, 向かう 〈ad alqd〉</div><div class=\"ex\"><i>res fluit ad interregnum</i> (<author>C<small>IC</small></author>)<span class=\"ext\">事態は政務停止に向かっている.</span></div><div class=\"def\"><num>⑦</num> (ことばが)すらすら出る, 流暢である.</div><div class=\"def\"><num>⑧</num> (時間が)経過する, 過ぎ去る.</div><div class=\"def\"><num>⑨</num> 消え去る, 衰える.</div><div class=\"def\"><num>⑩</num> たれさがる.</div><div class=\"def\"><num>⑪</num> 落ちる.</div>\r\n","<div class=\"hw\">flābellifera</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[flabellum/fero]</div><div class=\"def\">(女主人を)扇であおぐ女奴隷.</div>\r\n","<div class=\"hw\">flābellulum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[↓<a href=\"entry://flābellum\">flābellum</a>]</div><div class=\"def\">(小さな)扇.</div>\r\n","<div class=\"hw\">flābellum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[flabrum]</div><div class=\"def\">(小さな)扇.</div>\r\n","<div class=\"hw\">flābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[flo]</div><div class=\"def\"><num>①</num> 気体の, 空気のような.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 霊的な.</div>\r\n","<div class=\"hw jl\"><SUP>*</SUP>flābrum</div><div class=\"pos\">-ī, <i>n</i>(用例は <i>pl</i> flābra のみ)</div><div class=\"ori\">[flo]</div><div class=\"def\">一陣の風, 突風.</div>\r\n","<div class=\"hw\">flāgitium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://flāgitō\">flāgitō</a>]</div><div class=\"def\"><num>①</num> 恥ずべき行為, 不品行.</div><div class=\"def\"><num>②</num> 恥辱, 不面目.</div><div class=\"def\"><num>③</num> 悪党.</div>\r\n","<div class=\"hw\">flāgitiōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://flāgitium\">flāgitium</a>]</div><div class=\"def\">恥ずべき, 不面目な.</div>\r\n","<div class=\"hw\">flāgitiōsē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://flāgitiōsus\">flāgitiōsus</a>]</div><div class=\"def\">不面目に, 破廉恥に.</div>\r\n","<div class=\"hw\">flāgitātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[flagito]</div><div class=\"def\">しつこい要求.</div>\r\n","<div class=\"hw\">flāgitātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[flagito]</div><div class=\"def\">しつこい要求者.</div>\r\n","<div class=\"hw\">flāgitō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[<i>cf. </i> flagrum]</div><div class=\"def\"><num>①</num> しつこく要求する 〈alqd ab alqo;alqm alqd;ut, ne〉.</div><div class=\"def\"><num>②</num> 知ることを求める.</div><div class=\"def\"><num>③</num> 召喚する 〈alqm〉.</div>\r\n","<div class=\"hw\">flāmen<SUP>1</SUP></div><div class=\"pos\">-minis, <i>n</i></div><div class=\"ori\">[flo]</div><div class=\"def\"><num>①</num> (風が)吹くこと.</div><div class=\"def\"><num>②</num> 風.</div><div class=\"def\"><num>③</num> (笛を)吹くこと</div><div class=\"ex\"><i>flamina tibiae</i> (<author>H<small>OR</small></author>)<span class=\"ext\">笛の調べ.</span></div><hr><div class=\"hw\">flāmen<SUP>2</SUP></div><div class=\"pos\">-minis, <i>m</i></div><div class=\"ori\">[<i>cf. </i> flagro]</div><div class=\"def\">神官, 祭司《特に flamen Dialis》.</div>\r\n","<div class=\"hw\">flāmina</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">《碑》=<a href=\"entry://flāminica\">flaminica</a>.</div>\r\n","<div class=\"hw\">flāminia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[flamen<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 神官の住居.</div><div class=\"def\"><num>②</num> 神官の妻に仕える巫女.</div>\r\n","<div class=\"hw\">flāminica</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[flamen<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 神官の妻.</div><div class=\"def\"><num>②</num> 巫女.</div>\r\n","<div class=\"hw\">flāminium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://flāmōnium\">flamonium</a>.</div>\r\n","<div class=\"hw\">Flāminius<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">フラーミニウス《ローマ人の氏族名;特に <i>C. ～ Nepos</i>, 前223年と217年の執政官;Trasumenus 湖畔で Hannibal に大敗した(前217)》.</div><hr><div class=\"hw\">Flāminius<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Flaminius の</div><div class=\"ex\"><i>Via Flaminia</i><span class=\"ext\">フラミニア街道《ローマ市から Ariminum に至る道路;前220年の監察官(censor)C. Flaminius が建設した》.</span></div>\r\n","<div class=\"hw\">Flāminiānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Flaminius の.</div>\r\n","<div class=\"hw\">flāminālis</div><div class=\"pos\">-is, <i>m</i></div><div class=\"ori\">[flamen<SUP>2</SUP>]</div><div class=\"def\">《碑》神官職経験者.</div>\r\n","<div class=\"hw\">flāminātus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[flamen<SUP>2</SUP>]</div><div class=\"def\">《碑》神官職.</div>\r\n","<div class=\"hw\">Flāminīnus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">フラーミニーヌス《Quintia 氏族に属する家名;特に <i>T. Quintius ～</i>, Macedonia の王 Philippus V を Cynoscephalae で撃破した(前197)》.</div>\r\n","<div class=\"hw\">flāmōnium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[flamen<SUP>2</SUP>]</div><div class=\"def\">神官職.</div>\r\n","<div class=\"hw\">flātus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[flo]</div><div class=\"def\"><num>①</num> (風が)吹くこと;風.</div><div class=\"def\"><num>②</num> 呼吸, 息をすること.</div><div class=\"def\"><num>③</num> うぬぼれ, 傲慢.</div>\r\n","<div class=\"hw\">flāvens</div><div class=\"pos\">-entis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[↓<a href=\"entry://flāveō\">flāveō</a>]</div><div class=\"def\">黄色の, 黄金色の.</div>\r\n","<div class=\"hw\">flāvescō</div><div class=\"pos\">-ere, <i>intr inch</i></div><div class=\"ori\">[↑<a href=\"entry://flāveō\">flāveō</a>]</div><div class=\"def\">黄色[黄金色]になる.</div>\r\n","<div class=\"hw\">flāveō</div><div class=\"pos\">-ēre, <i>intr</i></div><div class=\"ori\">[flavus]</div><div class=\"def\">黄色である.</div>\r\n","<div class=\"hw\">flāvicomans</div><div class=\"pos\">-antis, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">=<a href=\"entry://flāvicomus\">flavicomus</a>.</div>\r\n","<div class=\"hw\">flāvicomus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[flavus/coma<SUP>1</SUP>]</div><div class=\"def\">金髪の.</div>\r\n","<div class=\"hw\">flāvidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[flavus]</div><div class=\"def\">黄色がかった.</div>\r\n","<div class=\"hw\">Flāvius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">フラーウィウス《ローマ人の氏族名;Vespasianus, Titus, Domitianus などの皇帝がこの氏族に属する》.</div>\r\n","<div class=\"hw\">Flāviānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Flavius の.</div>\r\n","<div class=\"hw\">flāvus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> 黄色の, 黄金色の.</div><div class=\"def\"><num>②</num> 金髪の.</div>\r\n","<div class=\"hw\">Flāvīna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">フラーウィーナ《Etruria の町》.</div>\r\n","<div class=\"hw\">Flāvīnius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Flavina の.</div>\r\n","<div class=\"hw\">flēbilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[fleo]</div><div class=\"def\"><num>①</num> 悲しむべき.</div><div class=\"def\"><num>②</num> 悲しんでいる;悲しげな, 悲しい</div><div class=\"ex\"><i>gemitus ～</i> (<author>C<small>IC</small></author>)<span class=\"ext\">悲しげなうめき声.</span></div>\r\n","<div class=\"hw\">flēbiliter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://flēbilis\">flēbilis</a>]</div><div class=\"def\">悲しげに.</div>\r\n","<div class=\"hw\">flēmina</div><div class=\"pos\">-um, <i>n pl</i></div><div class=\"def\">足首の周囲の腫れ[むくみ].</div>\r\n","<div class=\"hw\">flētus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://fleō\">fleo</a>.</div><hr><div class=\"hw\">flētus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 泣くこと, 悲嘆.</div><div class=\"def\"><num>②</num> 涙.</div>\r\n","<div class=\"hw\">Flēvum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">フレーウゥム《Frisii 族の要塞》.</div>\r\n","<div class=\"hw\">flēvī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://fleō\">fleo</a>.</div>\r\n","<div class=\"hw\">Flēvō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">(<i>sc. </i> lacus)フレーウォー《Rhenus 川河口の湖;現 Zuiderzee》.</div>\r\n","<div class=\"hw\">flīgō</div><div class=\"pos\">-ere, <i>tr</i></div><div class=\"def\">打ちつける, 打ち倒す.</div>\r\n","<div class=\"hw\">flō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>, <i>tr</i></div><div class=\"def\"><num0>Ⅰ</num0> (<i>intr</i>)</div><div class=\"def\"><num>①</num> (風が)吹く.</div><div class=\"def\"><num>②</num> 息を吹く[吐く].</div><div class=\"def\"><num>③</num> (笛が)鳴る.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>tr</i>)</div><div class=\"def\"><num>①</num> (息などを)吐き出す.</div><div class=\"def\"><num>②</num> (笛を)吹く.</div><div class=\"def\"><num>③</num> 鋳造する.</div>\r\n","<div class=\"hw\">flōra</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[flos]</div><div class=\"def\">〘生物〙(一地域または一時代の)植物相.</div>\r\n","<div class=\"hw\">Flōra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘神話〙フローラ《イタリアの花と春と豊穣の女神》.</div>\r\n","<div class=\"hw\">flōrens</div><div class=\"pos\">-entis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[floreo]</div><div class=\"def\"><num>①</num> 花が咲いている, 花盛りの.</div><div class=\"def\"><num>②</num> 繁栄している, 栄えている, 盛りの 〈re〉.</div><div class=\"def\"><num>③</num> 輝かしい, 際立った.</div>\r\n","<div class=\"hw\">Flōrentia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">フローレンティア《Etruria の町;現 Firenze》.</div>\r\n","<div class=\"hw\">Flōrentīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Florentia の.</div><div class=\"hw2\"><b>Flōrentīnī</b></div><div class=\"pos2\">-orum, <i>m pl</i></div><div class=\"def2\">Florentia の住民.</div>\r\n","<div class=\"hw\">flōrescō</div><div class=\"pos\">-ere, <i>intr inch</i></div><div class=\"ori\">[↑<a href=\"entry://flōreō\">flōreō</a>]</div><div class=\"def\"><num>①</num> 花が咲き始める, 開花する.</div><div class=\"def\"><num>②</num> 栄え始める, 盛りになる.</div>\r\n","<div class=\"hw\">flōreus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[flos]</div><div class=\"def\"><num>①</num> 花の, 花で作った.</div><div class=\"def\"><num>②</num> 花の多い, 花でいっぱいの.</div>\r\n","<div class=\"hw\">flōreō</div><div class=\"pos\">-ēre flōruī, <i>intr</i></div><div class=\"ori\">[flos]</div><div class=\"def\"><num>①</num> 花が咲く, 花盛りである.</div><div class=\"def\"><num>②</num> 華やかである 〈re〉.</div><div class=\"def\"><num>③</num> 泡立つ.</div><div class=\"def\"><num>④</num> 栄える, 盛りである.</div><div class=\"def\"><num>⑤</num> 際立っている, 卓越している 〈re〉</div><div class=\"ex\"><i>florere honoribus et rerum gestarum gloriā</i> (<author>C<small>IC</small></author>)<span class=\"ext\">名誉と栄えある功績で際立つ.</span></div>\r\n","<div class=\"hw\">flōridulus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[↓<a href=\"entry://flōridus\">flōridus</a>]</div><div class=\"def\">花のような.</div>\r\n","<div class=\"hw\">flōridus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[flos]</div><div class=\"def\"><num>①</num> 花が咲いている, 花盛りの, 花の多い.</div><div class=\"def\"><num>②</num> 花の, 花で作った.</div><div class=\"def\"><num>③</num> 華やかな, 美しい.</div><div class=\"def\"><num>④</num> 美文調の, 美辞麗句の多い.</div><div class=\"def\"><num>⑤</num> 盛りの.</div>\r\n","<div class=\"hw\">flōridē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[floridus]</div><div class=\"def\">華やかに.</div>\r\n","<div class=\"hw\">flōrifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[flos/fero]</div><div class=\"def\">花を咲かせる.</div>\r\n","<div class=\"hw\">flōriger</div><div class=\"pos\">-gera -gerum, <i>adj</i></div><div class=\"ori\">[flos/gero]</div><div class=\"def\">=<a href=\"entry://flōrifer\">florifer</a>.</div>\r\n","<div class=\"hw\">flōrilegus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[flos/lego<SUP>2</SUP>]</div><div class=\"def\">花を摘む[集める].</div>\r\n","<div class=\"hw\">flōriparus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[flos/pario<SUP>2</SUP>]</div><div class=\"def\">花を咲かせる.</div>\r\n","<div class=\"hw\">flōrulentus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[flos]</div><div class=\"def\"><num>①</num> 花でいっぱいの.</div><div class=\"def\"><num>②</num> 若い盛りの.</div>\r\n","<div class=\"hw\">flōrus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[flos]</div><div class=\"def\">輝いている;金髪の.</div>\r\n","<div class=\"hw\">Flōrus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">フロールス《2世紀のローマの歴史家》.</div>\r\n","<div class=\"hw\">Flōrālia</div><div class=\"pos\">-ium, <i>n pl</i></div><div class=\"def\">フローラ祭《4月28日に行なわれた Flora 女神の祭典》.</div>\r\n","<div class=\"hw\">Flōrālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Flora 女神の.</div>\r\n","<div class=\"hw\">Flōrālēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"def\">(<i>sc. </i> ludi)=<a href=\"entry://Flōrālia\">Floralia</a>.</div>\r\n","<div class=\"hw\">flōrēnus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">グルデン金貨《最初 Florentia で発行された》.</div>\r\n","<div class=\"hw\">flōrītiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[floreo]</div><div class=\"def\">花を咲かせること, 開花.</div>\r\n","<div class=\"hw\">flōrōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[flos]</div><div class=\"def\">花でいっぱいの.</div>\r\n","<div class=\"hw\">flōs</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"def\"><num>①</num> 花.</div><div class=\"def\"><num>②</num> 開花.</div><div class=\"def\"><num>③</num> (ぶどう酒の)浮きかす, おり.</div><div class=\"def\"><num>④</num> 蜜.</div><div class=\"def\"><num>⑤</num> 盛り, 全盛</div><div class=\"ex\"><i>in flore virium se credens esse</i> (<author>L<small>IV</small></author>)<span class=\"ext\">自らが体力の絶頂期にあると信じて.</span></div><div class=\"def\"><num>⑥</num> 青春.</div><div class=\"def\"><num>⑦</num> 精華, 最良の部分.</div><div class=\"def\"><num>⑧</num> 装飾.</div><div class=\"def\"><num>⑨</num> うぶ毛.</div><div class=\"def\"><num>⑩</num> (ぶどう酒の)芳香.</div><div class=\"def\"><num>⑪</num> <SUP>◇</SUP>(<i>pl</i>)〘化〙華</div><div class=\"ex\"><i>flores zinci</i><span class=\"ext\">亜鉛華.</span></div>\r\n","<div class=\"hw\">flūmen</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"ori\">[fluo]</div><div class=\"def\"><num>①</num> 流水;流れ.</div><div class=\"def\"><num>②</num> 川.</div><div class=\"def\"><num>③</num> (血液・空気などの)流れ.</div><div class=\"def\"><num>④</num> (弁舌の)流暢, 能弁</div><div class=\"ex\"><i>～ orationis aureum</i> (<author>C<small>IC</small></author>)<span class=\"ext\">よどみない雄弁の黄金の流れ.</span></div>\r\n","<div class=\"hw\">Flūmentānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://flūmen\">flūmen</a>]</div><div class=\"def\"><i>porta Flumentana</i> (<author>C<small>IC</small></author>) フルーメンターナ門《ローマ市の門の一つ;Tiberis 川に近く, Campus Martius の入口にあった》.</div>\r\n","<div class=\"hw\">flūmineus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[flumen]</div><div class=\"def\">川の.</div>\r\n","<div class=\"hw\">flūminālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">=<a href=\"entry://flūmineus\">flumineus</a>.</div>\r\n","<div class=\"hw\">flūtō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"def\">=<a href=\"entry://fluitō\">fluito</a>.</div>\r\n","<div class=\"hw\">foculus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[↓<a href=\"entry://focus\">focus</a>]</div><div class=\"def\">炉, 火鉢.</div>\r\n","<div class=\"hw\">focus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 炉.</div><div class=\"def\"><num>②</num> 祭壇.</div><div class=\"def\"><num>③</num> 火葬用の薪の山.</div><div class=\"def\"><num>④</num> 家庭(の団欒<SUB>だんらん</SUB>).</div>\r\n","<div class=\"hw\">focācius</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[focus]</div><div class=\"def\">炉の.</div>\r\n","<div class=\"hw\">focāria</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[focus]</div><div class=\"def\">料理女.</div>\r\n","<div class=\"hw\">focārius</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[focus]</div><div class=\"def\">料理人.</div>\r\n","<div class=\"hw\">fodere</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://fodiō\">fodio</a>.</div>\r\n","<div class=\"hw\">fodicō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[fodio]</div><div class=\"def\">突く, つつく, ちくりと刺す</div><div class=\"ex\"><i>fodicantes res</i> (<author>C<small>IC</small></author>)<span class=\"ext\">心痛事.</span></div>\r\n","<div class=\"hw\">fodiō</div><div class=\"pos\">-dere fōdī fossum, <i>tr</i></div><div class=\"def\"><num>①</num> 掘る.</div><div class=\"def\"><num>②</num> 刺す, 突く 〈alqm [alqd]〉.</div><div class=\"def\"><num>③</num> 刺激する.</div>\r\n","<div class=\"hw\">fodīna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://fodiō\">fodiō</a>]</div><div class=\"def\">(通例, 複合語の一部として表記される)鉱坑, 採掘場</div><div class=\"ex\"><i>aurifodina</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">金鉱.</span></div>\r\n","<div class=\"hw\">foecund-</div><div class=\"def\">⇒fecund-.</div>\r\n","<div class=\"hw\">foederātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[foedero]</div><div class=\"def\">連合, 同盟.</div>\r\n","<div class=\"hw\">foederātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[foedus<SUP>2</SUP>]</div><div class=\"def\">連合した, 同盟した.</div>\r\n","<div class=\"hw\">foederō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↑<a href=\"entry://foederātus\">foederātus</a>]</div><div class=\"def\">(...に)調印する, 批准する.</div>\r\n","<div class=\"hw\">foedifragus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[foedus<SUP>2</SUP>/frango]</div><div class=\"def\">盟約に背く, 同盟を破棄する.</div>\r\n","<div class=\"hw\">foeditās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[foedus<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 醜さ.</div><div class=\"def\"><num>②</num> 不快, 忌まわしさ.</div><div class=\"def\"><num>③</num> 恥辱, 不名誉.</div>\r\n","<div class=\"hw\">foedus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> 嫌悪すべき, 忌まわしい;醜い 〈+<i>sup</i>〉.</div><div class=\"def\"><num>②</num> 恥ずべき, 不名誉な.</div><hr><div class=\"hw\">foedus<SUP>2</SUP></div><div class=\"pos\">-deris, <i>n</i></div><div class=\"def\"><num>①</num> 同盟, 盟約.</div><div class=\"def\"><num>②</num> 契約.</div><div class=\"def\"><num>③</num> 法, おきて.</div><div class=\"def\"><num>④</num> きずな.</div>\r\n","<div class=\"hw\">foedē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[foedus<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 無惨に, 残酷に.</div><div class=\"def\"><num>②</num> 恥ずべき仕方で, 不面目に.</div>\r\n","<div class=\"hw\">foedō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://foedus\">foedus<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> 醜くする, きたなくする.</div><div class=\"def\"><num>②</num> ひどく傷つける, そこなう</div><div class=\"ex\"><i>agri foedati</i> (<author>L<small>IV</small></author>)<span class=\"ext\">荒廃した農地.</span></div><div class=\"def\"><num>③</num> けがす, 恥辱を与える.</div>\r\n","<div class=\"hw\">foen-</div><div class=\"def\">⇒faen-.</div>\r\n","<div class=\"hw\">foeteō</div><div class=\"pos\">-ēre, <i>intr</i></div><div class=\"def\">悪臭を放つ.</div>\r\n","<div class=\"hw\">foetidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://foeteō\">foeteō</a>]</div><div class=\"def\"><num>①</num> 悪臭のある.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 嫌悪すべき.</div>\r\n","<div class=\"hw\">foetor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[foeteo]</div><div class=\"def\">悪臭.</div>\r\n","<div class=\"hw\">folium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> (草木の)葉.</div><div class=\"def\"><num>②</num> 甘松の葉.</div><div class=\"def\"><num>③</num> 花びら.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>〘解〙虫部葉.</div>\r\n","<div class=\"hw\">foliāceus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[folium]</div><div class=\"def\">葉のような.</div>\r\n","<div class=\"hw\">foliātilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[foliatus]</div><div class=\"def\">葉の.</div>\r\n","<div class=\"hw\">foliātum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[foliatus]</div><div class=\"def\">(<i>sc. </i> unguentum)甘松の葉で作った香油.</div>\r\n","<div class=\"hw\">foliātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[folium]</div><div class=\"def\">葉のある, 葉の多い.</div>\r\n","<div class=\"hw\">foliātūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://foliātus\">foliātus</a>]</div><div class=\"def\">(1本の草木の)生い繁った葉, 葉叢<SUB>はむら</SUB>.</div>\r\n","<div class=\"hw\">foliōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://folium\">folium</a>]</div><div class=\"def\">葉の多い.</div>\r\n","<div class=\"hw\">folleō</div><div class=\"pos\">-ēre, <SUP>◇</SUP><i>intr</i></div><div class=\"ori\">[follis]</div><div class=\"def\">(ふいごのように)ふくらむ.</div>\r\n","<div class=\"hw\">folliculus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[↓<a href=\"entry://follis\">follis</a>]</div><div class=\"def\"><num>①</num> (小さな)革袋.</div><div class=\"def\"><num>②</num> (遊戯用の)ボール.</div><div class=\"def\"><num>③</num> 殻, さや.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP> 嚢<SUB>のう</SUB>.</div>\r\n","<div class=\"hw\">folliculōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://folliculus\">folliculus</a>]</div><div class=\"def\">さやの多い.</div>\r\n","<div class=\"hw\">follicō</div><div class=\"pos\">-āre -ātum, <i>intr</i></div><div class=\"ori\">[follis]</div><div class=\"def\"><num>①</num> (ふいごのように)ふくらんだりしぼんだりする;苦しそうに喘<SUB>あえ</SUB>ぐ.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> ゆるんで[だぶだぶして]いる.</div>\r\n","<div class=\"hw\">follis</div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\"><num>①</num> 革袋.</div><div class=\"def\"><num>②</num> (<i>pl</i>)ふいご.</div><div class=\"def\"><num>③</num> 財布.</div><div class=\"def\"><num>④</num> (遊戯用の)ボール.</div>\r\n","<div class=\"hw\">follītus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://follis\">follis</a>]</div><div class=\"def\">袋に入れられた.</div>\r\n","<div class=\"hw\">fons</div><div class=\"pos\">fontis, <i>m</i></div><div class=\"ori\">[<i>cf. </i> fundo<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 泉, わき水;井戸.</div><div class=\"def\"><num>②</num> 水源, 源泉.</div><div class=\"def\"><num>③</num> 起源, 根源.</div><div class=\"def\"><num>④</num> (F-)〘神話〙フォンス《ローマの泉の神;Janus の息子》.</div>\r\n","<div class=\"hw\">fonticola</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>adj m</i>, <i>f</i></div><div class=\"ori\">[fons/colo<SUP>2</SUP>]</div><div class=\"def\">泉のほとりに住む.</div>\r\n","<div class=\"hw\">fonticulus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[fons]</div><div class=\"def\"><num>①</num> (小さな)泉.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘解〙泉門.</div>\r\n","<div class=\"hw\">fontigena</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>adj m</i>, <i>f</i></div><div class=\"ori\">[fons/gigno]</div><div class=\"def\">泉のほとりで生まれた《Musae の添え名》.</div>\r\n","<div class=\"hw\">Fontinālia</div><div class=\"pos\">-um, <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://Fontinālis\">Fontinālis</a>]</div><div class=\"def\">フォンティナーリア《Fons 神の祭典;10月13日に行なわれた》.</div>\r\n","<div class=\"hw\">Fontinālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\"><i>porta Fontinalis</i> (<author>L<small>IV</small></author>) フォンティナーリス門《ローマ市の門の一つ;Campus Martius の入口にあった》.</div>\r\n","<div class=\"hw\">fontāna</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[fontanus]</div><div class=\"def\">泉.</div>\r\n","<div class=\"hw\">Fontāna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">《碑》フォンターナ《泉の女神》.</div>\r\n","<div class=\"hw\">fontāneus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">=<a href=\"entry://fontānus\">fontanus</a>.</div>\r\n","<div class=\"hw\">fontānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fons]</div><div class=\"def\">泉の.</div>\r\n","<div class=\"hw\">Fontēius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">フォンテイユス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">Fontēiānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Fonteius の.</div>\r\n","<div class=\"hw jl\"><SUP>*</SUP>for</div><div class=\"pos\">fārī fātus sum, <i>intr</i>, <i>tr dep</i></div><div class=\"def\">(用例は <i>pr</i> fātur, fantur;<i>fut</i> fābor, fābitur;<i>impr</i> fāre;<i>prp</i> fans <i>etc. </i>;<i>ger</i> fandī <i>etc. </i>)</div><div class=\"ori\">[<i>cf. </i> fama, fabula]</div><div class=\"def\"><num>①</num> 話す, 言う 〈<i>abs</i>;alqd;alci;ad alqm;+間接疑問〉</div><div class=\"ex\"><i>fando</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">うわさによって[よれば].</span></div><div class=\"def\"><num>②</num> 予言する.</div>\r\n","<div class=\"hw\">forasticus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://forās\">forās</a>]</div><div class=\"def\"><num>①</num> 戸外の, 外部の.</div><div class=\"def\"><num>②</num> 公けの.</div>\r\n","<div class=\"hw\">forceps</div><div class=\"pos\">-cipis, <i>m</i>(<i>f</i>)</div><div class=\"ori\">[formus/capio<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> はさむ道具, やっとこ, ピンセット, ...ばさみ.</div><div class=\"def\"><num>②</num> (カニなどの)はさみ.</div>\r\n","<div class=\"hw\">forda</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://fordus\">fordus</a>]</div><div class=\"def\">(<i>sc. </i> bos)妊娠中の雌牛.</div>\r\n","<div class=\"hw\">fordus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fero]</div><div class=\"def\">(雌牛が)妊娠している.</div>\r\n","<div class=\"hw\">fore</div><div class=\"def\"><i>inf fut</i>=futurus esse(⇒ <a href=\"entry://sum\">sum</a>).</div>\r\n","<div class=\"hw\">forem</div><div class=\"def\"><i>subj impf</i> =<a href=\"entry://essem\">essem</a>(⇒ <a href=\"entry://sum\">sum</a>).</div>\r\n","<div class=\"hw\">forensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[forum]</div><div class=\"def\"><num>①</num> 公共広場(forum)の, 市場の.</div><div class=\"def\"><num>②</num> 法廷の, 弁論の.</div><div class=\"def\"><num>③</num> 公けの, 公共の.</div>\r\n","<div class=\"hw\">Forentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">フォレントゥム《Apulia の町;現 Forenza》.</div>\r\n","<div class=\"hw\">forestis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[foras, foris<SUP>2</SUP>]</div><div class=\"def\">山林;御料林.</div>\r\n","<div class=\"hw\">forestārius</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↓<a href=\"entry://forestis\">forestis</a>]</div><div class=\"def\">林務官.</div>\r\n","<div class=\"hw\">forfex</div><div class=\"pos\">-ficis, <i>f</i></div><div class=\"ori\">[<i>cf. </i> forceps]</div><div class=\"def\"><num>①</num> はさむ道具.</div><div class=\"def\"><num>②</num> はさみ.</div>\r\n","<div class=\"hw\">foria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">下痢.</div>\r\n","<div class=\"hw\">forica</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://foria\">foria</a>]</div><div class=\"def\">公衆便所.</div>\r\n","<div class=\"hw\">foricula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[foris<SUP>1</SUP>]</div><div class=\"def\">(窓の)よろい戸, 雨戸.</div>\r\n","<div class=\"hw\">foriculārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↑<a href=\"entry://foricula\">foricula</a>]</div><div class=\"def\">《碑》(<i>sc. </i> vectigal)関税, 通過税.</div>\r\n","<div class=\"hw\">forinsecus</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[foris<SUP>2</SUP>/-secus;<i>cf. </i> extrinsecus]</div><div class=\"def\"><num>①</num> 外側に.</div><div class=\"def\"><num>②</num> 外へ.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 公けに.</div>\r\n","<div class=\"hw\">foriolus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[foria]</div><div class=\"def\">下痢をしている.</div>\r\n","<div class=\"hw\">foris<SUP>1</SUP></div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\"><num>①</num> とびら, 戸.</div><div class=\"def\"><num>②</num> 門, 入口.</div>\r\n","<div class=\"hw\">forma</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 姿, 形, 外観.</div><div class=\"def\"><num>②</num> 美しさ.</div><div class=\"def\"><num>③</num> 像, 肖像.</div><div class=\"def\"><num>④</num> 型, 配置.</div><div class=\"def\"><num>⑤</num> 性質, 状態</div><div class=\"ex\"><i>civitates in aliquam tolerabilem formam redigendae</i> (<author>L<small>IV</small></author>)<span class=\"ext\">ある程度まともな状態に引き戻されるべき国々.</span></div><div class=\"def\"><num>⑥</num> 種類.</div><div class=\"def\"><num>⑦</num> 図形;略図.</div><div class=\"def\"><num>⑧</num> 概略.</div><div class=\"def\"><num>⑨</num> 趣旨.</div><div class=\"def\"><num>⑩</num> 規定, 規範.</div><div class=\"def\"><num>⑪</num> 〘文〙語尾変化.</div><div class=\"def\"><num>⑫</num> <SUP>◇</SUP>〘キ教〙予示, 予表.</div>\r\n","<div class=\"hw\">formaldehydum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘薬〙ホルムアルデヒド.</div>\r\n","<div class=\"hw\">formalinum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘薬〙ホルマリン.</div>\r\n","<div class=\"hw\">formella</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f dim</i></div><div class=\"ori\">[formula]</div><div class=\"def\">(パン焼き・チーズ作り用の)小さな型.</div>\r\n","<div class=\"hw\">Formiae</div><div class=\"pos\">-ārum, <i>f</i></div><div class=\"def\">フォルミアエ《Latium の海沿いの町;現 Mola di Gaeta》.</div>\r\n","<div class=\"hw\">formidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[formus]</div><div class=\"def\">暖かい.</div>\r\n","<div class=\"hw\">Formiānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Formiae の.</div><div class=\"hw2\"><b>Formiānī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Formiae の住民.</div><div class=\"hw2\"><b>Formiānum</b></div><div class=\"pos2\">-ī, <i>n</i></div><div class=\"def2\">Formiae の別荘.</div>\r\n","<div class=\"hw\">formula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[forma]</div><div class=\"def\"><num>①</num> 美, 美しさ.</div><div class=\"def\"><num>②</num> 定式, 方式</div><div class=\"ex\"><i>testamentorum formulae</i> (<author>C<small>IC</small></author>)<span class=\"ext\">遺言の方式.</span></div><div class=\"def\"><num>③</num> 法則, 原則.</div><div class=\"def\"><num>④</num> 契約, 条約, 協定.</div><div class=\"def\"><num>⑤</num> 裁判手続, 訴訟.</div>\r\n","<div class=\"hw\">formus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">熱い.</div>\r\n","<div class=\"hw\">formābilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[formo]</div><div class=\"def\">形成されうる.</div>\r\n","<div class=\"hw\">formālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[forma]</div><div class=\"def\"><num>①</num> 鋳型を作るのに用いられる.</div><div class=\"def\"><num>②</num> 手本[規準]となる</div><div class=\"ex\"><i>～ epistula</i> (<author>S<small>UET</small></author>)<span class=\"ext\">回章, 通達</span></div><div class=\"ex\"><i>formale pretium</i> (<author>U<small>LP</small></author>)<span class=\"ext\">相場.</span></div>\r\n","<div class=\"hw\">formāliter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://formālis\">formālis</a>]</div><div class=\"def\">形相のもとに.</div>\r\n","<div class=\"hw\">formāmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[formo]</div><div class=\"def\">形態.</div>\r\n","<div class=\"hw\">formātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[formo]</div><div class=\"def\"><num>①</num> 形成</div><div class=\"ex\"><i>～ morum</i> (<author>S<small>EN</small></author>)<span class=\"ext\">道徳の教育.</span></div><div class=\"def\"><num>②</num> 〘建〙設計, デザイン.</div>\r\n","<div class=\"hw\">formātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[formo]</div><div class=\"def\">形成者.</div>\r\n","<div class=\"hw\">formātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://formō\">formo</a>.</div>\r\n","<div class=\"hw\">formātūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[formo]</div><div class=\"def\"><num>①</num> 形成.</div><div class=\"def\"><num>②</num> 形態.</div>\r\n","<div class=\"hw\">formīca</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘昆〙アリ(蟻).</div>\r\n","<div class=\"hw\">formīcābilis, -cālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://formīca\">formīca</a>]</div><div class=\"def\">アリがはうような感じの</div><div class=\"ex\"><i>～ pulsus</i> (<author>C<small>AEL</small> A<small>UR</small></author>)<span class=\"ext\">〘病〙蟻走脈《弱くて不整》.</span></div>\r\n","<div class=\"hw\">formīcātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[formico]</div><div class=\"def\">〘医〙(アリがはうように)むずむずすること, 蟻走感.</div>\r\n","<div class=\"hw\">formīcīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[formica]</div><div class=\"def\">アリの(ような)</div><div class=\"ex\"><i>gradus ～</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">(アリのように)はうこと.</span></div>\r\n","<div class=\"hw\">formīcō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"ori\">[formica]</div><div class=\"def\"><num>①</num> アリがはうように感ずる, 蟻走感を覚える.</div><div class=\"def\"><num>②</num> (脈が)弱くて不整である.</div>\r\n","<div class=\"hw\">formīcōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[formica]</div><div class=\"def\">アリの群がっている.</div>\r\n","<div class=\"hw\">formīdolōsitās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://formīdolōsus\">formīdolōsus</a>]</div><div class=\"def\">残酷, 苛酷.</div>\r\n","<div class=\"hw\">formīdolōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[formido<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 恐ろしい, 恐るべき.</div><div class=\"def\"><num>②</num> 恐れる 〈alcis〉</div><div class=\"ex\"><i>～ hostium</i> (<author>T<small>AC</small></author>)<span class=\"ext\">敵を恐れて.</span></div>\r\n","<div class=\"hw\">formīdolōsē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[formidolosus]</div><div class=\"def\"><num>①</num> 恐ろしく.</div><div class=\"def\"><num>②</num> 恐れて.</div>\r\n","<div class=\"hw\">formīdābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[formido<SUP>1</SUP>]</div><div class=\"def\">恐るべき, 恐ろしい.</div>\r\n","<div class=\"hw\">formīdābiliter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://formīdābilis\">formīdābilis</a>]</div><div class=\"def\">恐ろしく.</div>\r\n","<div class=\"hw\">formīdāmen</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"ori\">[formido<SUP>1</SUP>]</div><div class=\"def\">おばけ, 幽霊.</div>\r\n","<div class=\"hw\">formīdātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://formīdō\">formido<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">formīdō<SUP>1</SUP></div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i>(<i>intr</i>)</div><div class=\"ori\">[↓<a href=\"entry://formīdō\">formīdō<SUP>2</SUP></a>]</div><div class=\"def\">恐れる, こわがる 〈alqd [alqm];ne;+<i>inf</i>;<i>abs</i>;+<i>dat</i>〉.</div><hr><div class=\"hw\">formīdō<SUP>2</SUP></div><div class=\"pos\">-dinis, <i>f</i></div><div class=\"def\"><num>①</num> 恐れ, 恐怖 〈alcis〉.</div><div class=\"def\"><num>②</num> 恐ろしいもの, おばけ;かかし.</div>\r\n","<div class=\"hw\">formō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[forma]</div><div class=\"def\"><num>①</num> 形づくる, 形成する 〈alqd〉.</div><div class=\"def\"><num>②</num> 整える, 調整する</div><div class=\"ex\"><i>formatis omnibus domi et ad belli et ad pacis usus</i> (<author>L<small>IV</small></author>)<span class=\"ext\">国内のすべてを戦争のみならず平和の要求にも適合するように整備して.</span></div><div class=\"def\"><num>③</num> 教育する, 仕込む 〈alqm [alqd]〉.</div><div class=\"def\"><num>④</num> 描く, 描写する.</div>\r\n","<div class=\"hw\">formōsitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://formōsus\">formōsus</a>]</div><div class=\"def\">美しさ.</div>\r\n","<div class=\"hw\">formōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[forma]</div><div class=\"def\">形のよい, 美しい;美貌の.</div>\r\n","<div class=\"hw\">formōsē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[formosus]</div><div class=\"def\">美しく.</div>\r\n","<div class=\"hw\">fornax</div><div class=\"pos\">-ācis, <i>f</i></div><div class=\"def\"><num>①</num> かまど, 炉</div><div class=\"ex\"><i>～ Aetnae</i> (<author>L<small>UCR</small></author>)<span class=\"ext\">Aetna 山の噴火口.</span></div><div class=\"def\"><num>②</num> (F-)〘神話〙フォルナクス《ローマのかまどの女神》.</div>\r\n","<div class=\"hw\">fornicor</div><div class=\"pos\">-ārī -ātus sum, <SUP>◇</SUP><i>intr dep</i></div><div class=\"ori\">[↓<a href=\"entry://fornix\">fornix</a>]</div><div class=\"def\">〘聖〙姦淫の罪を犯す.</div>\r\n","<div class=\"hw\">fornicāria</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://fornicārius\">fornicārius</a>]</div><div class=\"def\">〘聖〙姦淫の罪を犯す者《女性》.</div>\r\n","<div class=\"hw\">fornicārius</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[fornix]</div><div class=\"def\">〘聖〙姦淫の罪を犯す者.</div>\r\n","<div class=\"hw\">fornicātiō<SUP>1</SUP></div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[fornicatus]</div><div class=\"def\"><num>①</num> 丸天井を付けること.</div><div class=\"def\"><num>②</num> 丸天井.</div><hr><div class=\"hw\">fornicātiō<SUP>2</SUP></div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[fornicor]</div><div class=\"def\">密通.</div>\r\n","<div class=\"hw\">fornicātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[fornicor]</div><div class=\"def\">密通者.</div>\r\n","<div class=\"hw\">fornicātrix</div><div class=\"pos\">-īcis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↑<a href=\"entry://fornicātor\">fornicātor</a>]</div><div class=\"def\">=<a href=\"entry://fornicāria\">fornicaria</a>.</div>\r\n","<div class=\"hw\">fornicātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fornix]</div><div class=\"def\">丸天井の.</div>\r\n","<div class=\"hw\">fornicō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>intr</i></div><div class=\"def\">=<a href=\"entry://fornicor\">fornicor</a>.</div>\r\n","<div class=\"hw\">fornix</div><div class=\"pos\">-icis, <i>m</i></div><div class=\"ori\">[<i>cf. </i> fornax, furnus]</div><div class=\"def\"><num>①</num> 丸天井.</div><div class=\"def\"><num>②</num> 拱廊<SUB>きょうろう</SUB>, アーケード.</div><div class=\"def\"><num>③</num> 記念門.</div><div class=\"def\"><num>④</num> 出撃門.</div><div class=\"def\"><num>⑤</num> 売春宿.</div><div class=\"def\"><num>⑥</num> <SUP>◇</SUP>〘解〙脳弓;円蓋</div><div class=\"ex\"><i>～ pharyngis</i><span class=\"ext\">咽頭円蓋.</span></div>\r\n","<div class=\"hw\">fornus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">=<a href=\"entry://furnus\">furnus</a>.</div>\r\n","<div class=\"hw\">fornācula</div><div class=\"pos\"><i>f dim</i></div><div class=\"ori\">[↓<a href=\"entry://fornax\">fornax</a>]</div><div class=\"def\">(小さな)かまど, 炉.</div>\r\n","<div class=\"hw\">Fornācālia</div><div class=\"pos\">-ium, <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://fornācālis\">fornācālis</a>]</div><div class=\"def\">Fornax 女神の祭.</div>\r\n","<div class=\"hw\">fornācālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[fornax]</div><div class=\"def\">かまどの.</div>\r\n","<div class=\"hw\">forpex</div><div class=\"pos\">-picis, <i>f</i></div><div class=\"ori\">[forceps]</div><div class=\"def\">火ばさみ, 火ばし.</div>\r\n","<div class=\"hw\">fors</div><div class=\"pos\">fortis, <i>f</i></div><div class=\"ori\">[fero]</div><div class=\"def\">(用例は <i>sg nom</i> & <i>abl</i> のみ)</div><div class=\"def\"><num>①</num> 偶然, 運.</div><div class=\"def\"><num>②</num> (<i>adv</i> として)</div><div class=\"def\"><num1>⒜</num1> </div><div class=\"ex\">(nom)<i>fors</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">たまたま, おそらく.</span></div><div class=\"def\"><num1>⒝</num1> </div><div class=\"ex\">(abl)<i>forte</i> (<author>C<small>IC</small></author>)<span class=\"ext\">偶然に, ひょっとして.</span></div><div class=\"def\"><num>③</num> (F-)〘神話〙フォルス《偶然[運命]の女神》</div><div class=\"ex\"><i>～ Fortuna</i> (<author>T<small>ER</small></author>)<span class=\"ext\">幸運の女神.</span></div>\r\n","<div class=\"hw\">forsan</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://fors\">fors</a>/an]</div><div class=\"def\">ことによると, ひょっとして.</div>\r\n","<div class=\"hw\">forsit</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[fors/sit(sum の 3 <i>sg subj pr</i>)]</div><div class=\"def\">=<a href=\"entry://forsitan\">forsitan</a>.</div>\r\n","<div class=\"hw\">forsitan</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://forsit\">forsit</a>/an]</div><div class=\"def\">=<a href=\"entry://forsan\">forsan</a>.</div>\r\n","<div class=\"hw\">fortasse</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[<forte an sit]</div><div class=\"def\"><num>①</num> ことによると, ひょっとして.</div><div class=\"def\"><num>②</num> 約, およそ.</div>\r\n","<div class=\"hw\">fortassis</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[<forte an si vis]</div><div class=\"def\">=<a href=\"entry://fortasse\">fortasse</a>.</div>\r\n","<div class=\"hw\">forte</div><div class=\"pos\"><i>adv</i>(<i>abl</i>)</div><div class=\"def\">⇒<a href=\"entry://fors\">fors</a>.</div>\r\n","<div class=\"hw\">forticulus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[fortis]</div><div class=\"def\">やや勇敢な.</div>\r\n","<div class=\"hw\">fortificātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://fortificō\">fortificō</a>]</div><div class=\"def\">丈夫にすること, 強くすること.</div>\r\n","<div class=\"hw\">fortificō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://fortis\">fortis</a>/facio]</div><div class=\"def\">丈夫にする, 強くする.</div>\r\n","<div class=\"hw\">fortis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\"><num>①</num> (肉体的に)強い, たくましい.</div><div class=\"def\"><num>②</num> (精神的に)勇敢な, 不屈の;大胆な</div><div class=\"ex\"><i>fortes fortuna adjuvat</i> (<author>C<small>IC</small></author>)<span class=\"ext\">運命(の女神)は勇者を助ける.</span></div><div class=\"def\"><num>③</num> (物が)強力な, 頑丈な.</div><div class=\"def\"><num>④</num> (風・流れなどが)激しい.</div><div class=\"def\"><num>⑤</num> (弁論などが)迫力のある, 説得力のある.</div>\r\n","<div class=\"hw\">fortiter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://fortis\">fortis</a>]</div><div class=\"def\"><num>①</num> 強く.</div><div class=\"def\"><num>②</num> 勇敢に, 大胆に.</div>\r\n","<div class=\"hw\">fortitūdō</div><div class=\"pos\">-dinis, <i>f</i></div><div class=\"ori\">[fortis]</div><div class=\"def\"><num>①</num> 強いこと.</div><div class=\"def\"><num>②</num> 勇敢.</div>\r\n","<div class=\"hw\">fortuītus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fors]</div><div class=\"def\">偶然の, 思いがけない.</div>\r\n","<div class=\"hw\">fortuītō</div><div class=\"pos\"><i>adv</i>(<i>abl</i>)</div><div class=\"ori\">[↓<a href=\"entry://fortuītus\">fortuītus</a>]</div><div class=\"def\">偶然に, たまたま.</div>\r\n","<div class=\"hw\">fortūna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>cf. </i> fors]</div><div class=\"def\"><num>①</num> 運, 運命.</div><div class=\"def\"><num>②</num> 幸運.</div><div class=\"def\"><num>③</num> 不幸, 不運.</div><div class=\"def\"><num>④</num> (F-)〘神話〙フォルトゥーナ《ローマの運命の女神;ギリシア神話の Tyche に当たる》.</div><div class=\"def\"><num>⑤</num> 境遇</div><div class=\"ex\"><i>est infima ～ servorum</i> (<author>C<small>IC</small></author>)<span class=\"ext\">奴隷たちのおかれている境遇は最悪だ.</span></div><div class=\"def\"><num>⑥</num> 偶然.</div><div class=\"def\"><num>⑦</num> 機会, 好機.</div><div class=\"def\"><num>⑧</num> 結果, 成り行き.</div><div class=\"def\"><num>⑨</num> (主に <i>pl</i>)財産.</div>\r\n","<div class=\"hw\">fortūnātim</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">=<a href=\"entry://fortūnātē\">fortunate</a>.</div>\r\n","<div class=\"hw\">fortūnātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[↓<a href=\"entry://fortūnō\">fortūnō</a>]</div><div class=\"def\"><num>①</num> 幸福な, 幸運な.</div><div class=\"def\"><num>②</num> 財産のある, 裕福な.</div>\r\n","<div class=\"hw\">fortūnātē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[fortunatus]</div><div class=\"def\">幸福に, 幸運に.</div>\r\n","<div class=\"hw\">fortūnō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[fortuna]</div><div class=\"def\"><num>①</num> 幸福にする, 祝福する.</div><div class=\"def\"><num>②</num> 繁栄させる.</div>\r\n","<div class=\"hw\">forulī</div><div class=\"pos\">-ōrum, <i>m pl dim</i></div><div class=\"ori\">[forus]</div><div class=\"def\">本箱.</div>\r\n","<div class=\"hw\">Forulī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">フォルリー《Sabini 族の村》.</div>\r\n","<div class=\"hw\">forum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> 公共広場</div><div class=\"ex\"><i>～ Romanum</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">フォルム・ローマーヌム《ローマ市の Palatinus 丘と Capitolinus 丘の間にあった大きな広場;商取引の場;また裁判・政治などの公事の集会に使われた》.</span></div><div class=\"def\"><num>②</num> 市場</div><div class=\"ex\"><i>～ bovarium</i> (<author>V<small>ARR</small></author>)<span class=\"ext\">牛市場《Tiberis 川と Circus Maximus の間にあった》</span></div><div class=\"ex\"><i>～ olitorium</i> (<author>V<small>ARR</small></author>)<span class=\"ext\">青果市場《Tiberis 川と Capitolinus 丘の間にあった》</span></div><div class=\"ex\"><i>～ piscarium</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">魚市場《forum Romanum の北東部にあったらしい》.</span></div><div class=\"def\"><num>③</num> 商売, 取引.</div><div class=\"def\"><num>④</num> 国事, 政治</div><div class=\"ex\"><i>～ attingere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">政治にたずさわる.</span></div><div class=\"def\"><num>⑤</num> 法廷, 裁判;(属州での)巡回裁判</div><div class=\"ex\"><i>～ agere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">巡回裁判を開く.</span></div><div class=\"def\"><num>⑥</num> 巡回裁判開廷都市.</div><div class=\"def\"><num>⑦</num> (F-)フォルム《多くの町の名》</div><div class=\"ex\"><i>～ Appii</i> (<author>C<small>IC</small></author>)<span class=\"ext\">フォルム・アッピイー《Latium の Via Appia 沿いの町;現 Foro Appio》</span></div><div class=\"ex\"><i>～ Aurelium</i> (<author>C<small>IC</small></author>)<span class=\"ext\">フォルム・アウレーリウム《Etruria の Via Aurelia 沿いの町;現 Montalto》</span></div><div class=\"ex\"><i>～ Cornelium</i> (<author>C<small>IC</small></author>)<span class=\"ext\">フォルム・コルネーリウム《Gallia Cispadana の町;現 Imola》</span></div><div class=\"ex\"><i>～ Gallorum</i> (<author>C<small>IC</small></author>)<span class=\"ext\">フォルム・ガッロールム《Gallia Cispadana の町;現 Castel Franco》</span></div><div class=\"ex\"><i>～ Julii</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">フォルム・ユーリイー《Gallia Narbonensis の町;現 Fréjus》</span></div><div class=\"ex\"><i>～ Voconii</i> (<author>C<small>IC</small></author>)<span class=\"ext\">フォルム・ウォコーニイー《Gallia Narbonensis の町》.</span></div>\r\n","<div class=\"hw\">forus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> (船の)甲板, 舷門<SUB>げんもん</SUB>.</div><div class=\"def\"><num>②</num> 通路.</div><div class=\"def\"><num>③</num> (ハチの巣の)蜜房.</div><div class=\"def\"><num>④</num> (<i>pl</i>)(Circus Maximus の観覧席の)列.</div>\r\n","<div class=\"hw\">forābilis</div><div class=\"pos\">-is -e, adj</div><div class=\"ori\">[foro]</div><div class=\"def\">刺し通せる, 貫通できる.</div>\r\n","<div class=\"hw\">forāmen</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"ori\">[foro]</div><div class=\"def\">穴, 口.</div>\r\n","<div class=\"hw\">forāminōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://forāmen\">forāmen</a>]</div><div class=\"def\">穴の多い.</div>\r\n","<div class=\"hw\">forāneus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://forās\">forās</a>]</div><div class=\"def\"><num>①</num> 外部の.</div><div class=\"def\"><num>②</num> (聖職者が)管区に住まない.</div>\r\n","<div class=\"hw\">forās</div><div class=\"pos\"><i>adv</i></div><div class=\"def\"><num>①</num> 戸外に, 外に.</div><div class=\"def\"><num>②</num> 世間に, 公けに.</div>\r\n","<div class=\"hw\">forātus</div><div class=\"pos\">-ūs, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[foro]</div><div class=\"def\">穴をあけること, 刺し通すこと.</div>\r\n","<div class=\"hw\">forīs<SUP>2</SUP></div><div class=\"pos\"><i>adv</i></div><div class=\"def\"><num>①</num> 外で, 外に.</div><div class=\"def\"><num>②</num> 外国で.</div><div class=\"def\"><num>③</num> 外から.</div>\r\n","<div class=\"hw\">forīsfacere</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://forīsfaciō\">forisfacio</a>.</div>\r\n","<div class=\"hw\">forīsfaciō</div><div class=\"pos\">-ere, <SUP>◇</SUP><i>intr</i>, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[foris<SUP>2</SUP>/facio]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>intr</i>)不正[悪事]を働く.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>tr</i>)</div><div class=\"def\"><num>①</num> (罰として没収されて財産などを)失う.</div><div class=\"def\"><num>②</num> (<i>refl</i>)極刑に処される.</div>\r\n","<div class=\"hw\">forō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"def\">穴をあける, うがつ.</div>\r\n","<div class=\"hw\">fossa</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[fodio]</div><div class=\"def\"><num>①</num> 排水溝, 溝, どぶ.</div><div class=\"def\"><num>②</num> (城塞の)壕, 掘割.</div><div class=\"def\"><num>③</num> 水路, 運河.</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>〘解〙窩<SUB>か</SUB>.</div>\r\n","<div class=\"hw\">fossibilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[fossus]</div><div class=\"def\">掘られた.</div>\r\n","<div class=\"hw\">fossilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">=<a href=\"entry://fossīcius\">fossicius</a>.</div>\r\n","<div class=\"hw\">fossiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[fodio]</div><div class=\"def\"><num>①</num> 掘ること.</div><div class=\"def\"><num>②</num> 穴.</div>\r\n","<div class=\"hw\">fossor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[fodio]</div><div class=\"def\"><num>①</num> 掘る人.</div><div class=\"def\"><num>②</num> (軽蔑的に)田舎者.</div>\r\n","<div class=\"hw\">fossula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[fossa]</div><div class=\"def\"><num>①</num> 小さな掘割.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘解〙小窩.</div>\r\n","<div class=\"hw\">fossus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://fodiō\">fodio</a>.</div>\r\n","<div class=\"hw\">fossātum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i>(<i>pp</i>)</div><div class=\"ori\">[fosso]</div><div class=\"def\">掘割, 溝.</div>\r\n","<div class=\"hw\">fossātus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i>(<i>pp</i>)</div><div class=\"ori\">[fosso]</div><div class=\"def\">境界.</div>\r\n","<div class=\"hw\">fossīcius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fossus]</div><div class=\"def\">掘り出された.</div>\r\n","<div class=\"hw\">fossō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr freq</i></div><div class=\"ori\">[fodio]</div><div class=\"def\">掘る.</div>\r\n","<div class=\"hw\">fossōrium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[fodio]</div><div class=\"def\">鋤<SUB>すき</SUB>.</div>\r\n","<div class=\"hw\">fossūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[fodio]</div><div class=\"def\"><num>①</num> 掘ること.</div><div class=\"def\"><num>②</num> 穴, くぼみ.</div>\r\n","<div class=\"hw\">Fosī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">フォシー《Germania の一部族》.</div>\r\n","<div class=\"hw\">fovea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 穴.</div><div class=\"def\"><num>②</num> 落とし穴.</div>\r\n","<div class=\"hw\">foveō</div><div class=\"pos\">-ēre fōvī fōtum, <i>tr</i></div><div class=\"def\"><num>①</num> 暖かくする, 温める;(患部を)温湿布する.</div><div class=\"def\"><num>②</num> かわいがる, 愛撫する, 抱きしめる.</div><div class=\"def\"><num>③</num> 成長を見守る, 愛育する.</div><div class=\"def\"><num>④</num> 心に抱く, (考えなどを)堅持する</div><div class=\"ex\"><i>animo mea vota fovebam</i> (<author>O<small>V</small></author>)<span class=\"ext\">私は願いを胸に秘めていた.</span></div><div class=\"def\"><num>⑤</num> 味方する, 支援する.</div><div class=\"def\"><num>⑥</num> 励ます, 促進する.</div><div class=\"def\"><num>⑦</num> 支持を求める, 機嫌を取る.</div>\r\n","<div class=\"hw\">fovēla</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://foveō\">foveō</a>]</div><div class=\"def\">慰め.</div>\r\n","<div class=\"hw\">fracescō</div><div class=\"pos\">-ere fracuī, <i>intr</i></div><div class=\"ori\">[↑<a href=\"entry://fracēs\">fracēs</a>]</div><div class=\"def\"><num>①</num> 柔らかくなる.</div><div class=\"def\"><num>②</num> 腐る, 腐敗する.</div>\r\n","<div class=\"hw\">fracidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fraces]</div><div class=\"def\">(オリーブの実が)柔らかい, 熟した.</div>\r\n","<div class=\"hw\">fractiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[frango]</div><div class=\"def\">砕くこと, 割ること.</div>\r\n","<div class=\"hw\">fractus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[frango]</div><div class=\"def\"><num>①</num> (地面が)でこぼこの.</div><div class=\"def\"><num>②</num> (音が)とぎれとぎれの, 耳ざわりな.</div><div class=\"def\"><num>③</num> 弱々しい, 力のない</div><div class=\"ex\"><i>fractiorem esse animo</i> (<author>C<small>IC</small></author>)<span class=\"ext\">一段と落胆している.</span></div><div class=\"def\"><num>④</num> めめしい.</div>\r\n","<div class=\"hw\">fractūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[frango]</div><div class=\"def\"><num>①</num> 砕けること;砕けた[折れた]部位.</div><div class=\"def\"><num>②</num> 〘医〙骨折.</div>\r\n","<div class=\"hw\">fracuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://fracescō\">fracesco</a>.</div>\r\n","<div class=\"hw\">fracēs</div><div class=\"pos\">-um, <i>f pl</i></div><div class=\"def\">オリーブのしぼりかす;オリーブ油のおり.</div>\r\n","<div class=\"hw\">fragilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[frango]</div><div class=\"def\"><num>①</num> こわれやすい, もろい.</div><div class=\"def\"><num>②</num> はかない, 移ろいやすい.</div><div class=\"def\"><num>③</num> 弱い, 弱々しい.</div><div class=\"def\"><num>④</num> パチパチ鳴っている.</div>\r\n","<div class=\"hw\">fragilitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://fragilis\">fragilis</a>]</div><div class=\"def\">もろさ, はかなさ.</div>\r\n","<div class=\"hw\">fragmen</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"def\">=<a href=\"entry://fragmentum\">fragmentum</a>.</div>\r\n","<div class=\"hw\">fragmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[frango]</div><div class=\"def\">(通例 <i>pl</i>)断片, 破片, かけら.</div>\r\n","<div class=\"hw\">fragor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[frango]</div><div class=\"def\"><num>①</num> こわす[こわれる]こと.</div><div class=\"def\"><num>②</num> こわれるような物音;どよめき, とどろき.</div>\r\n","<div class=\"hw\">fragōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://fragor\">fragor</a>]</div><div class=\"def\"><num>①</num> こわれやすい, もろい.</div><div class=\"def\"><num>②</num> でこぼこの.</div><div class=\"def\"><num>③</num> とどろく.</div>\r\n","<div class=\"hw\">framea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">(Germania 人が用いた)投げ槍.</div>\r\n","<div class=\"hw\">frangō</div><div class=\"pos\">-ere frēgī fractum, <i>tr</i></div><div class=\"def\"><num>①</num> 粉砕する, こわす</div><div class=\"ex\"><i>compluribus navibus fractis</i> (<author>C<small>AES</small></author>)<span class=\"ext\">多くの船が難破して</span></div><div class=\"ex\"><i>laqueo gulam frangere</i> (<author>S<small>ALL</small></author>)<span class=\"ext\">首の骨を折る(=締め殺す).</span></div><div class=\"def\"><num>②</num> ひく, つき砕く, すりつぶす.</div><div class=\"def\"><num>③</num> (約束・誓い・法を)破る, 違反する.</div><div class=\"def\"><num>④</num> 落胆させる, 意気沮喪させる.</div><div class=\"def\"><num>⑤</num> 弱める, 和らげる</div><div class=\"ex\"><i>morantem diem mero frangere</i> (<author>H<small>OR</small></author>)<span class=\"ext\">ぐずぐず過ぎる日をぶどう酒で紛らす.</span></div><div class=\"def\"><num>⑥</num> 抑える, 抑制する.</div><div class=\"def\"><num>⑦</num> 感動させる, 心を動かす.</div>\r\n","<div class=\"hw\">fraudulenter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[fraudulentus]</div><div class=\"def\">詐欺によって, 不正手段で.</div>\r\n","<div class=\"hw\">fraudulentia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://fraudulentus\">fraudulentus</a>]</div><div class=\"def\">詐欺, かたり.</div>\r\n","<div class=\"hw\">fraudulentus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fraus]</div><div class=\"def\">人をだます, 詐欺的な.</div>\r\n","<div class=\"hw\">fraudulōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">=<a href=\"entry://fraudulentus\">fraudulentus</a>.</div>\r\n","<div class=\"hw\">fraudābilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[fraudo]</div><div class=\"def\">詐欺の, 欺瞞の.</div>\r\n","<div class=\"hw\">fraudātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[fraudo]</div><div class=\"def\">詐欺, 欺瞞.</div>\r\n","<div class=\"hw\">fraudātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://fraudō\">fraudō</a>]</div><div class=\"def\">詐欺師.</div>\r\n","<div class=\"hw\">fraudō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[fraus]</div><div class=\"def\"><num>①</num> だまし取る 〈alqm re〉.</div><div class=\"def\"><num>②</num> 盗む, 横領[着服]する 〈alqd〉.</div>\r\n","<div class=\"hw\">fraus</div><div class=\"pos\">fraudis, <i>f</i>(<i>pl gen</i> fraudum [fraudium])</div><div class=\"def\"><num>①</num> 欺瞞, 詐欺</div><div class=\"ex\"><i>legi fraudem facere</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">法を破る.</span></div><div class=\"def\"><num>②</num> 迷い, 誤り</div><div class=\"ex\"><i>in fraudem incidere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">過ちに陥る.</span></div><div class=\"def\"><num>③</num> 損害, 不利益</div><div class=\"ex\"><i>sine fraude</i> (<author>H<small>OR</small></author>)<span class=\"ext\">害を受けずに, 無事に.</span></div><div class=\"def\"><num>④</num> 不正行為, 犯罪.</div>\r\n","<div class=\"hw\">fraxineus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fraxinus<SUP>2</SUP>]</div><div class=\"def\">トネリコの.</div>\r\n","<div class=\"hw\">fraxinus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://fraxineus\">fraxineus</a>.</div><hr><div class=\"hw\">fraxinus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>f</i></div><div class=\"def\"><num>①</num> 〘植〙トネリコ.</div><div class=\"def\"><num>②</num> トネリコ製の槍.</div>\r\n","<div class=\"hw\">Fregellae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"def\">フレゲッラエ《Latium にあった Volsci 族の町;現 Ceprano》.</div>\r\n","<div class=\"hw\">Fregellānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Fregellae の.</div><div class=\"hw2\"><b>Fregellānī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Fregellae の住民.</div>\r\n","<div class=\"hw\">Fregēnae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"def\">フレゲーナエ《Etruria 南部の海に近い町》.</div>\r\n","<div class=\"hw\">fremebundus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fremo]</div><div class=\"def\">《詩》ほえる, うなる, とどろく.</div>\r\n","<div class=\"hw\">fremidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://fremebundus\">fremebundus</a>.</div>\r\n","<div class=\"hw\">fremitus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://fremō\">fremo</a>.</div><hr><div class=\"hw\">fremitus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> どよめき, うなり, とどろき.</div><div class=\"def\"><num>②</num> ぶつぶつ不平を言うこと.</div><div class=\"def\"><num>③</num> 拍手喝采(の音).</div><div class=\"def\"><num>④</num> <SUP>◇</SUP>〘医〙振盪音.</div>\r\n","<div class=\"hw\">fremor</div><div class=\"pos\">-ōrīs</div><div class=\"ori\">[↑<a href=\"entry://fremō\">fremō</a>]</div><div class=\"def\">うなり, ざわめき.</div>\r\n","<div class=\"hw\">fremuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://fremō\">fremo</a>.</div>\r\n","<div class=\"hw\">fremō</div><div class=\"pos\">-ere fremuī fremitum, <i>intr</i>, <i>tr</i></div><div class=\"def\"><num>①</num> とどろく, どよめく, うなる.</div><div class=\"def\"><num>②</num> ぶつぶつ不平を言う.</div><div class=\"def\"><num>③</num> 歓声をあげ(て賛意を表明す)る.</div><div class=\"def\"><num>④</num> わめく, やかましく要求する.</div>\r\n","<div class=\"hw\">frendeō</div><div class=\"pos\">-ēre, <i>intr</i>, <i>tr</i></div><div class=\"def\">=<a href=\"entry://frendō\">frendo</a>.</div>\r\n","<div class=\"hw\">frendor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↑<a href=\"entry://frendō\">frendō</a>]</div><div class=\"def\">歯ぎしり.</div>\r\n","<div class=\"hw\">frendō</div><div class=\"pos\">-ere frēsum [fressum], <i>intr</i>, <i>tr</i></div><div class=\"def\"><num0>Ⅰ</num0> (<i>intr</i>)歯ぎしりする.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>tr</i>)ひく, すりつぶす.</div>\r\n","<div class=\"hw\">Frentānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Frentani 族の.</div>\r\n","<div class=\"hw\">Frentānī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">フレンターニー《アドリア海沿岸地方にいた Samnites 族の一派》.</div>\r\n","<div class=\"hw\">Frentō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>m</i></div><div class=\"def\">フレントー《Apulia 北部の川;Fertor (1) の別名》.</div>\r\n","<div class=\"hw\">frequens</div><div class=\"pos\">-entis, <i>adj</i></div><div class=\"def\"><num>①</num> たびたびの, 頻繁な</div><div class=\"ex\"><i>～ Platonis auditor</i> (<author>C<small>IC</small></author>)<span class=\"ext\">Plato の勤勉な聴講生.</span></div><div class=\"def\"><num>②</num> いっぱいの, ぎっしり詰まった 〈+<i>abl</i>〉</div><div class=\"ex\"><i>major frequentiorque legatio</i> (<author>L<small>IV</small></author>)<span class=\"ext\">より大きな, より多人数の使節団</span></div><div class=\"ex\"><i>～ custodiis locus</i> (<author>L<small>IV</small></author>)<span class=\"ext\">警備の厳重な場所.</span></div><div class=\"def\"><num>③</num> (人が)しばしば訪れる.</div>\r\n","<div class=\"hw\">frequenter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[frequens]</div><div class=\"def\"><num>①</num> しばしば, 頻繁に.</div><div class=\"def\"><num>②</num> 多数で, 大挙して.</div>\r\n","<div class=\"hw\">frequentia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[frequens]</div><div class=\"def\"><num>①</num> 密集, 集合;群衆.</div><div class=\"def\"><num>②</num> 多数, 大量.</div><div class=\"def\"><num>③</num> 頻繁.</div>\r\n","<div class=\"hw\">frequentātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[frequento]</div><div class=\"def\">密集, 頻繁.</div>\r\n","<div class=\"hw\">frequentātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[frequento]</div><div class=\"def\">常連, しばしば訪れる人.</div>\r\n","<div class=\"hw\">frequentātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[frequento]</div><div class=\"def\"><num>①</num> 頻用される, ありふれた.</div><div class=\"def\"><num>②</num> (...に)満ちた, 豊富な 〈+<i>abl</i>〉.</div>\r\n","<div class=\"hw\">frequentātīvus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[frequento]</div><div class=\"def\">〘文〙反復(相)の.</div>\r\n","<div class=\"hw\">frequentō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[frequens]</div><div class=\"def\"><num>①</num> 数多く集める.</div><div class=\"def\"><num>②</num> いっぱいにする, 満たす</div><div class=\"ex\"><i>frequentare urbes</i> (<author>C<small>IC</small></author>)<span class=\"ext\">集まって町に住む.</span></div><div class=\"def\"><num>③</num> 大勢で行なう</div><div class=\"ex\"><i>frequentare sacra</i> (<author>O<small>V</small></author>)<span class=\"ext\">祭を祝う.</span></div><div class=\"def\"><num>④</num> しばしば行なう, 頻用する</div><div class=\"ex\"><i>frequentare memoriam alcis</i> (<author>S<small>EN</small></author>)<span class=\"ext\">ある人の思い出に執着する.</span></div><div class=\"def\"><num>⑤</num> しばしば訪れる.</div>\r\n","<div class=\"hw\">fressus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">=<a href=\"entry://frēsus\">fresus</a>.</div>\r\n","<div class=\"hw\">Fretensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://fretum\">fretum</a>]</div><div class=\"def\"><i>mare Fretense</i> (<author>C<small>IC</small></author>) 現 Messina 海峡《イタリア本土と Sicilia 島の間》.</div>\r\n","<div class=\"hw\">fretum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> 海峡;(特に)現 Messina 海峡 (=<i>～ Siciliae [Siciliense, Siculum]</i> (<author>C<small>AES</small> [C<small>IC</small>, L<small>IV</small>]</author>))</div><div class=\"ex\"><i>～ Oceani [Gaditanum]</i> (<author>C<small>IC</small> [P<small>LIN</small>]</author>)<span class=\"ext\">現 Gibraltar 海峡.</span></div><div class=\"def\"><num>②</num> 海.</div><div class=\"def\"><num>③</num> (嵐のような)過渡期.</div>\r\n","<div class=\"hw\">fretus<SUP>1</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">=<a href=\"entry://fretum\">fretum</a>.</div>\r\n","<div class=\"hw\">fricium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↓<a href=\"entry://fricō\">fricō</a>]</div><div class=\"def\">歯みがき粉.</div>\r\n","<div class=\"hw\">frictiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"def\">=<a href=\"entry://fricātiō\">fricatio</a>.</div>\r\n","<div class=\"hw\">frictus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://fricō\">frico</a>, <a href=\"entry://frīgō\">frigo</a>.</div><hr><div class=\"hw\">frictus<SUP>2</SUP></div><div class=\"pos\">-ūs, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[frico]</div><div class=\"def\">こすること.</div>\r\n","<div class=\"hw\">fricuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://fricō\">frico</a>.</div>\r\n","<div class=\"hw\">fricātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[frico]</div><div class=\"def\">マッサージ.</div>\r\n","<div class=\"hw\">fricātus</div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"ori\">[frico]</div><div class=\"def\">こすること, 磨くこと.</div>\r\n","<div class=\"hw\">fricātūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[frico]</div><div class=\"def\">(表面を)こすって磨くこと.</div>\r\n","<div class=\"hw\">fricō</div><div class=\"pos\">-āre fricuī fric(ā)tum, <i>tr</i></div><div class=\"def\">こする;マッサージする.</div>\r\n","<div class=\"hw\">friguttiō</div><div class=\"pos\">-īre, <i>intr</i>, <i>tr</i></div><div class=\"def\"><num>①</num> さえずる.</div><div class=\"def\"><num>②</num> どもる, 口ごもる.</div>\r\n","<div class=\"hw\">fringilla</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘鳥〙ズアオアトリ.</div>\r\n","<div class=\"hw\">Friniātēs</div><div class=\"pos\">-um, <i>m pl</i></div><div class=\"def\">フリニアーテース《Appenninus 山脈の北側にいた Liguria 人》.</div>\r\n","<div class=\"hw\">frit</div><div class=\"pos\"><i>indecl n</i></div><div class=\"def\">小さな穀粒.</div>\r\n","<div class=\"hw\">fritillus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">さい筒《さいを入れて振り出す円筒》.</div>\r\n","<div class=\"hw\">frixī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://frīgescō\">frigesco</a>, <a href=\"entry://frīgō\">frigo</a>.</div>\r\n","<div class=\"hw\">frixōrium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[frigo]</div><div class=\"def\">料理鍋, フライパン.</div>\r\n","<div class=\"hw\">frixūra</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">=<a href=\"entry://frixōrium\">frixorium</a>.</div>\r\n","<div class=\"hw\">friābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[frio]</div><div class=\"def\">砕けやすい, もろい.</div>\r\n","<div class=\"hw\">friō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"def\">細かく砕く, 粉にする.</div>\r\n","<div class=\"hw\">frondescō</div><div class=\"pos\">-ere fronduī, <i>intr inch</i></div><div class=\"ori\">[↑<a href=\"entry://frondeō\">frondeō</a>]</div><div class=\"def\">葉が茂る, 葉をつける.</div>\r\n","<div class=\"hw\">frondeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[frons<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 葉の茂った.</div><div class=\"def\"><num>②</num> 葉から作られた.</div>\r\n","<div class=\"hw\">frondeō</div><div class=\"pos\">-ēre, <i>intr</i></div><div class=\"ori\">[frons<SUP>1</SUP>]</div><div class=\"def\">葉が茂っている, 葉をつけている.</div>\r\n","<div class=\"hw\">frondicomus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[frons<SUP>1</SUP>/coma<SUP>1</SUP>]</div><div class=\"def\">葉におおわれた.</div>\r\n","<div class=\"hw\">frondifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[frons<SUP>1</SUP>/fero]</div><div class=\"def\">葉の茂った.</div>\r\n","<div class=\"hw\">fronduī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://frondescō\">frondesco</a>.</div>\r\n","<div class=\"hw\">frondārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[frons<SUP>1</SUP>]</div><div class=\"def\">葉の.</div>\r\n","<div class=\"hw\">frondātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[frons<SUP>1</SUP>]</div><div class=\"def\">植木の葉を間引く職人, 剪定師.</div>\r\n","<div class=\"hw\">frondōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[frons<SUP>1</SUP>]</div><div class=\"def\">葉の多い.</div>\r\n","<div class=\"hw\">frons<SUP>1</SUP></div><div class=\"pos\">frondis, <i>f</i></div><div class=\"def\"><num>①</num> 葉.</div><div class=\"def\"><num>②</num> 葉で作った冠.</div><hr><div class=\"hw\">frons<SUP>2</SUP></div><div class=\"pos\">frontis, <i>f</i></div><div class=\"def\"><num>①</num> 額</div><div class=\"ex\"><i>frontem contrahere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">まゆをひそめる.</span></div><div class=\"def\"><num>②</num> 表情;慎しみ;厚顔</div><div class=\"ex\"><i>fronte occultare sententiam</i> (<author>C<small>IC</small></author>)<span class=\"ext\">本心を顔に出さない.</span></div><div class=\"def\"><num>③</num> 前面, 前部.</div><div class=\"def\"><num>④</num> 〘軍〙(部隊・艦隊の)前衛, 先陣.</div><div class=\"def\"><num>⑤</num> 書巻の上下の先端.</div><div class=\"def\"><num>⑥</num> (建物の)正面(幅).</div>\r\n","<div class=\"hw\">frontispicium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[frons<SUP>2</SUP>/specio]</div><div class=\"def\">〘建〙(建物の)正面.</div>\r\n","<div class=\"hw\">frontomaxillāris</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙前頭上顎骨の.</div>\r\n","<div class=\"hw\">frontālia</div><div class=\"pos\">-ium, <i>n pl</i></div><div class=\"ori\">[↑<a href=\"entry://frons\">frons<SUP>2</SUP></a>]</div><div class=\"def\">(馬の)額飾り.</div>\r\n","<div class=\"hw\">frontālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[frons<SUP>2</SUP>]</div><div class=\"def\">〘解〙前頭の.</div>\r\n","<div class=\"hw\">Frontīnus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">フロンティーヌス《ローマ人の家名》.</div>\r\n","<div class=\"hw\">frontō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"ori\">[frons<SUP>2</SUP>]</div><div class=\"def\">額の広い人.</div>\r\n","<div class=\"hw\">Frontō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">フロントー《ローマ人の家名;特に <i>M. Cornelius ～</i>, M. Aurelius や L. Verus の師となった修辞家(100?‐?166)》.</div>\r\n","<div class=\"hw\">frontōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[frons<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> (Janus について)多くの額をもった.</div><div class=\"def\"><num>②</num> ずうずうしい, あつかましい.</div>\r\n","<div class=\"hw\">frontōsē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://frontōsus\">frontōsus</a>]</div><div class=\"def\">ずうずうしく, あつかましく.</div>\r\n","<div class=\"hw\">fructifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[fructus<SUP>2</SUP>/fero]</div><div class=\"def\">実をならせる.</div>\r\n","<div class=\"hw\">fructificātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://fructificō\">fructificō</a>]</div><div class=\"def\">実を結ぶこと.</div>\r\n","<div class=\"hw\">fructificō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"ori\">[fructus<SUP>2</SUP>/facio]</div><div class=\"def\">実を結ぶ.</div>\r\n","<div class=\"hw\">fructus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://fruor\">fruor</a>.</div><hr><div class=\"hw\">fructus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 享受.</div><div class=\"def\"><num>②</num> 収穫物;果実, 実.</div><div class=\"def\"><num>③</num> 利益, 収入.</div><div class=\"def\"><num>④</num> 結果, 成果, 報い</div><div class=\"ex\"><i>～ studiorum</i> (<author>Q<small>UINT</small></author>)<span class=\"ext\">研究の成果.</span></div><div class=\"def\"><num>⑤</num> 楽しみ, 満足.</div><div class=\"def\"><num>⑥</num> <SUP>◇</SUP>〘薬〙</div><div class=\"ex\"><i>～ cardamomi</i><span class=\"ext\">ショウズク</span></div><div class=\"ex\"><i>～ piperis nigri</i><span class=\"ext\">コショウ.</span></div>\r\n","<div class=\"hw\">fructuārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fructus<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 実の, 実をならせる.</div><div class=\"def\"><num>②</num> 〘法〙用益権の.</div><hr><div class=\"hw\">fructuārius<SUP>2</SUP></div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"def\">〘法〙用益権者.</div>\r\n","<div class=\"hw\">fructuōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fructus<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 実をならせる, 多産の.</div><div class=\"def\"><num>②</num> 有利な, 有益な.</div>\r\n","<div class=\"hw\">fructuōsē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://fructuōsus\">fructuōsus</a>]</div><div class=\"def\">有利[有益]に.</div>\r\n","<div class=\"hw\">fruitiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[fruor]</div><div class=\"def\">享受.</div>\r\n","<div class=\"hw\">fruitūrus</div><div class=\"pos\">-a -um, <i>fut p</i></div><div class=\"def\">⇒<a href=\"entry://fruor\">fruor</a>.</div>\r\n","<div class=\"hw\">fruor</div><div class=\"pos\">-ī fructus sum(<i>fut p</i> fruitūrus), <i>intr</i>(<i>tr</i>)<i>dep</i></div><div class=\"def\">〈+<i>abl</i> [<i>acc</i>]〉</div><div class=\"def\"><num>①</num> 利用する, 享受する.</div><div class=\"def\"><num>②</num> 〘法〙(あるものの)用益権を有する.</div><div class=\"def\"><num>③</num> 楽しむ.</div>\r\n","<div class=\"hw\">Frusinās</div><div class=\"pos\">-ātis, <i>adj</i></div><div class=\"def\">Frusino の.</div><div class=\"hw2\"><b>Frusinātēs</b></div><div class=\"pos2\">-ium, <i>m pl</i></div><div class=\"def2\">Frusino の住民.</div>\r\n","<div class=\"hw\">Frusinō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">フルシノー《Latium にあった Hernici 族の町;現 Frosinone》.</div>\r\n","<div class=\"hw\">frustillum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n dim</i></div><div class=\"ori\">[frustum]</div><div class=\"def\">小片.</div>\r\n","<div class=\"hw\">frustillātim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[frustum]</div><div class=\"def\">細かく刻んで, ばらばらに.</div>\r\n","<div class=\"hw\">frustror</div><div class=\"pos\">-ārī -ātus sum, <i>tr dep</i></div><div class=\"ori\">[frustra]</div><div class=\"def\"><num>①</num> 欺く, だます.</div><div class=\"def\"><num>②</num> 失敗させる, だいなしにする</div><div class=\"ex\"><i>militarem impetum frustari</i> (<author>L<small>IV</small></author>)<span class=\"ext\">激しい戦闘意欲に水をさす.</span></div>\r\n","<div class=\"hw\">frustrā</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[<i>cf. </i> fraus]</div><div class=\"def\"><num>①</num> 間違って, 誤って.</div><div class=\"def\"><num>②</num> 無益に, むなしく, いたずらに.</div><div class=\"def\"><num>③</num> 理由なく, 根拠なしに.</div>\r\n","<div class=\"hw\">frustrāmen</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"ori\">[frustror]</div><div class=\"def\">欺瞞, 錯誤.</div>\r\n","<div class=\"hw\">frustrātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[frustror]</div><div class=\"def\"><num>①</num> 欺くこと, ごまかし.</div><div class=\"def\"><num>②</num> 失敗, 挫折.</div><div class=\"def\"><num>③</num> 延引, 遅滞.</div>\r\n","<div class=\"hw\">frustrātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[frustror]</div><div class=\"def\">遅らせる者, 妨げる者.</div>\r\n","<div class=\"hw\">frustrō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"def\">=<a href=\"entry://frustror\">frustror</a>.</div>\r\n","<div class=\"hw\">frustulentus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[frustum]</div><div class=\"def\">(一口大の)食べ物でいっぱいの.</div>\r\n","<div class=\"hw\">frustulum</div><div class=\"pos\">-ī, <i>n dim</i></div><div class=\"ori\">[↓<a href=\"entry://frustum\">frustum</a>]</div><div class=\"def\">小片, かけら.</div>\r\n","<div class=\"hw\">frustum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[fruor]</div><div class=\"def\"><num>①</num> (食べ物の)一かじり, 一口.</div><div class=\"def\"><num>②</num> 断片, 一片.</div>\r\n","<div class=\"hw\">frustātim</div><div class=\"pos\"><i>adv</i></div><div class=\"def\">=<a href=\"entry://frustillātim\">frustillatim</a>.</div>\r\n","<div class=\"hw\">frutectum, -tētum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[fruticetum]</div><div class=\"def\">低木の茂み;低木.</div>\r\n","<div class=\"hw\">frutectōsus, -tētōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://frutectum\">frutectum, -tētum</a>]</div><div class=\"def\">低木の多い.</div>\r\n","<div class=\"hw\">frutex</div><div class=\"pos\">-ticis, <i>m</i></div><div class=\"def\"><num>①</num> 低木.</div><div class=\"def\"><num>②</num> 茎, 幹.</div><div class=\"def\"><num>③</num> (非難のことばとして)のろま, ばか者.</div>\r\n","<div class=\"hw\">fruticor</div><div class=\"pos\">-ārī, <i>intr dep</i></div><div class=\"def\">=<a href=\"entry://fruticō\">frutico</a>.</div>\r\n","<div class=\"hw\">fruticētum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↑<a href=\"entry://frutex\">frutex</a>]</div><div class=\"def\">低木の茂み.</div>\r\n","<div class=\"hw\">fruticō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"ori\">[frutex]</div><div class=\"def\">若枝を出す, 茂る.</div>\r\n","<div class=\"hw\">fruticōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[frutex]</div><div class=\"def\"><num>①</num> 低木の生い茂る.</div><div class=\"def\"><num>②</num> 茂みのような.</div>\r\n","<div class=\"hw\">frux</div><div class=\"pos\">-ūgis, <i>f</i></div><div class=\"ori\">[<i>cf</i>. fruor]</div><div class=\"def\"><num>①</num> 果実;穀物.</div><div class=\"def\"><num>②</num> 成果.</div><div class=\"def\"><num>③</num> 美徳, 高潔.</div>\r\n","<div class=\"hw\">fruī</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://fruor\">fruor</a>.</div>\r\n","<div class=\"hw\">frāga</div><div class=\"pos\">-ōrum, <i>n pl</i></div><div class=\"def\">野イチゴ.</div>\r\n","<div class=\"hw\">frāgrans</div><div class=\"pos\">-antis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[fragro]</div><div class=\"def\">芳しい, 香りのよい;匂いの強い.</div>\r\n","<div class=\"hw\">frāgrantia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://frāgrans\">frāgrans</a>]</div><div class=\"def\">芳香.</div>\r\n","<div class=\"hw\">frāgrō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"def\">芳香を放つ;強く匂う.</div>\r\n","<div class=\"hw\">frāgum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"def\">〘植〙野イチゴの木.</div>\r\n","<div class=\"hw\">frāter</div><div class=\"pos\">-tris, <i>m</i></div><div class=\"def\"><num>①</num> 兄弟;(<i>pl</i>)兄弟姉妹.</div><div class=\"def\"><num>②</num> 従兄弟.</div><div class=\"def\"><num>③</num> 義兄弟.</div><div class=\"def\"><num>④</num> 同志, 同国民.</div><div class=\"def\"><num>⑤</num> 同類のもの.</div><div class=\"def\"><num>⑥</num> <SUP>◇</SUP>〘カト〙修道士.</div>\r\n","<div class=\"hw\">frāterculus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[↑<a href=\"entry://frāter\">frāter</a>]</div><div class=\"def\">(小さな)兄弟.</div>\r\n","<div class=\"hw\">frāternitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://frāternus\">frāternus</a>]</div><div class=\"def\"><num>①</num> 兄弟であること.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘カト〙信心会.</div>\r\n","<div class=\"hw\">frāternus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[frater]</div><div class=\"def\"><num>①</num> 兄弟の.</div><div class=\"def\"><num>②</num> 親族の.</div><div class=\"def\"><num>③</num> 兄弟のような, 親しい.</div>\r\n","<div class=\"hw\">frāternē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[fraternus]</div><div class=\"def\">兄弟のように.</div>\r\n","<div class=\"hw\">frātria<SUP>1</SUP></div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[frater]</div><div class=\"def\">兄弟の妻.</div><hr><div class=\"hw\">frātria<SUP>2</SUP></div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\">(ギリシアのポリスにおける)部族の下位区分《ローマの curia に当たる》.</div>\r\n","<div class=\"hw\">frātricīda</div><div class=\"pos\">-ae, <i>m</i></div><div class=\"ori\">[frater/caedo]</div><div class=\"def\">兄弟殺し《犯人》.</div>\r\n","<div class=\"hw\">frātricīdium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[↑<a href=\"entry://frātricīda\">frātricīda</a>]</div><div class=\"def\">兄弟の殺害.</div>\r\n","<div class=\"hw\">frātrissa</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"def\">=<a href=\"entry://frātria\">fratria<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">frātruēlis</div><div class=\"pos\">-is, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[frater]</div><div class=\"def\">父の兄弟の息子, (父方の)従兄弟.</div>\r\n","<div class=\"hw\">frēgī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://frangō\">frango</a>.</div>\r\n","<div class=\"hw\">frēnulum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n dim</i></div><div class=\"ori\">[↓<a href=\"entry://frēnum\">frēnum</a>]</div><div class=\"def\"><num>①</num> 〘解〙(陰核・包皮・舌などの)小帯.</div><div class=\"def\"><num>②</num> 〘昆〙抱棘<SUB>ほうきょく</SUB>.</div>\r\n","<div class=\"hw\">frēnum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">(<i>pl</i> は通例 frēnī -ōrum, <i>m</i>;frēna(<i>n pl</i>)は 《詩》)</div><div class=\"def\"><num>①</num> 頭部馬具《はみ・手綱など》.</div><div class=\"def\"><num>②</num> 制御, 抑制.</div>\r\n","<div class=\"hw\">frēnātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[freno]</div><div class=\"def\">抑制.</div>\r\n","<div class=\"hw\">frēnātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[freno]</div><div class=\"def\"><num>①</num> 御者.</div><div class=\"def\"><num>②</num> 制御する人.</div>\r\n","<div class=\"hw\">frēnō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[frenum]</div><div class=\"def\"><num>①</num> 馬勒を付ける, 手綱を引く.</div><div class=\"def\"><num>②</num> 制御する, 抑制する.</div>\r\n","<div class=\"hw\">frēsus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://frendō\">frendo</a>.</div>\r\n","<div class=\"hw\">frētus<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">確信[信頼]している 〈+<i>abl</i> [<i>dat</i>];+<i>acc c.inf</i>〉</div><div class=\"ex\"><i>loci praesidio freti</i> (<author>C<small>AES</small></author>)<span class=\"ext\">地の利をあてにした彼らは.</span></div><hr><div class=\"hw\">frētus<SUP>3</SUP></div><div class=\"pos\">-ūs, <SUP>◇</SUP><i>m</i></div><div class=\"def\">信頼.</div>\r\n","<div class=\"hw\">frīgefactō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://frīgeō\">frīgeō</a>/facio]</div><div class=\"def\">冷やす.</div>\r\n","<div class=\"hw\">frīgerō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"ori\">[frigus]</div><div class=\"def\">冷たくする, 冷やす.</div>\r\n","<div class=\"hw\">frīgescō</div><div class=\"pos\">-ere frixī, <i>intr inch</i></div><div class=\"ori\">[frigeo]</div><div class=\"def\"><num>①</num> 寒く[冷たく]なる, 冷える.</div><div class=\"def\"><num>②</num> 活気がなくなる, 気が抜ける.</div>\r\n","<div class=\"hw\">frīgeō</div><div class=\"pos\">-ēre, <i>intr</i></div><div class=\"ori\">[frigus]</div><div class=\"def\"><num>①</num> 寒い, 冷たい.</div><div class=\"def\"><num>②</num> 活気がない, 気が抜けている.</div><div class=\"def\"><num>③</num> 無視される, 冷たくあしらわれる, 振るわない</div><div class=\"ex\"><i>cum omnia consilia frigerent</i> (<author>C<small>IC</small></author>)<span class=\"ext\">すべての計画が足踏み状態になると.</span></div>\r\n","<div class=\"hw\">frīgida</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[frigidus]</div><div class=\"def\">(<i>sc. </i> aqua)冷水.</div>\r\n","<div class=\"hw\">frīgiditās</div><div class=\"pos\">-ātis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[frigidus]</div><div class=\"def\">寒さ.</div>\r\n","<div class=\"hw\">frīgidulus</div><div class=\"pos\">-a -um, <i>adj dim</i></div><div class=\"ori\">[frigidus]</div><div class=\"def\"><num>①</num> やや冷たい.</div><div class=\"def\"><num>②</num> やや弱い.</div>\r\n","<div class=\"hw\">frīgidum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://frīgidus\">frīgidus</a>]</div><div class=\"def\">寒さ.</div>\r\n","<div class=\"hw\">frīgidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[frigeo]</div><div class=\"def\"><num>①</num> 冷たい, 寒い.</div><div class=\"def\"><num>②</num> 冷やす, 冷たくする.</div><div class=\"def\"><num>③</num> 力のない, 活気のない, 気の抜けた.</div><div class=\"def\"><num>④</num> (議論・話が)単調な, 退屈な.</div>\r\n","<div class=\"hw\">frīgidārium</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://frīgidārius\">frīgidārius</a>]</div><div class=\"def\"><num>①</num> 冷浴室.</div><div class=\"def\"><num>②</num> (食料の)冷却貯蔵庫.</div>\r\n","<div class=\"hw\">frīgidārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[frigidus]</div><div class=\"def\">冷却の</div><div class=\"ex\"><i>cella frigidaria</i> (<author>P<small>LIN</small> M<small>IN</small></author>)<span class=\"ext\">冷浴室.</span></div>\r\n","<div class=\"hw\">frīgidē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[frigidus]</div><div class=\"def\"><num>①</num> 冷淡に, 熱意なく.</div><div class=\"def\"><num>②</num> (ことばが)単調に, 平板に.</div>\r\n","<div class=\"hw\">frīgidō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[frigidus]</div><div class=\"def\">冷やす, 冷たく[寒く]する.</div>\r\n","<div class=\"hw\">frīgor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[frigeo]</div><div class=\"def\">寒さ.</div>\r\n","<div class=\"hw\">frīgorificus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://frīgus\">frīgus</a>/facio]</div><div class=\"def\">冷たくする.</div>\r\n","<div class=\"hw\">frīgus</div><div class=\"pos\">-goris, <i>n</i></div><div class=\"def\"><num>①</num> 寒さ, 冷たさ</div><div class=\"ex\"><i>ante focum, si ～ erit</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">冬になれば炉の前で</span></div><div class=\"ex\"><i>～ non habitabile</i> (<author>O<small>V</small></author>)<span class=\"ext\">人の住めない寒冷地. </span></div><div class=\"def\"><num>②</num> 身震い, 戦慄.</div><div class=\"def\"><num>③</num> 無気力, 不活発, 怠惰.</div><div class=\"def\"><num>④</num> 冷遇, 冷淡.</div>\r\n","<div class=\"hw\">frīgēdō</div><div class=\"pos\">-dinis, <i>f</i></div><div class=\"ori\">[frigeo]</div><div class=\"def\">寒さ.</div>\r\n","<div class=\"hw\">frīgō</div><div class=\"pos\">-ere frixī frictum [frixum], <i>tr</i></div><div class=\"def\">いる, あぶる.</div>\r\n","<div class=\"hw\">Frīsius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Frisii 族の.</div>\r\n","<div class=\"hw\">Frīsiī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">フリーシイー《Germania 北部(現オランダ Friesland 州)にいた一部族》.</div>\r\n","<div class=\"hw\">frīvolus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[frio]</div><div class=\"def\">価値のない, くだらない, 取るに足らぬ.</div>\r\n","<div class=\"hw\">frīvolē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://frīvolus\">frīvolus</a>]</div><div class=\"def\">軽々しく, 無造作に.</div>\r\n","<div class=\"hw\">frūgescō</div><div class=\"pos\">-ere, <SUP>◇</SUP><i>intr</i></div><div class=\"ori\">[frux]</div><div class=\"def\">実がなる.</div>\r\n","<div class=\"hw\">frūgifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[frux/fero]</div><div class=\"def\"><num>①</num> 実をならせる, 多産の.</div><div class=\"def\"><num>②</num> 有利な, 有益な.</div>\r\n","<div class=\"hw\">frūgiferens</div><div class=\"pos\">-entis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[frux/fero]</div><div class=\"def\">実をならせる, 多産の.</div>\r\n","<div class=\"hw\">frūgilegus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[frux/lego<SUP>2</SUP>]</div><div class=\"def\">《詩》(蟻が)穀物[果実]を集める.</div>\r\n","<div class=\"hw\">frūgiparens</div><div class=\"pos\">-entis, <SUP>◇</SUP><i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[frux/pario<SUP>2</SUP>]</div><div class=\"def\">実をならせる.</div>\r\n","<div class=\"hw\">frūgiparus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[frux/pario<SUP>2</SUP>]</div><div class=\"def\">《詩》多産の.</div>\r\n","<div class=\"hw\">frūgālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[frux]</div><div class=\"def\">倹約な, 質素な;実直な.</div>\r\n","<div class=\"hw\">frūgāliter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[frugalis]</div><div class=\"def\">倹約して, 質素に.</div>\r\n","<div class=\"hw\">frūgālitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://frūgālis\">frūgālis</a>]</div><div class=\"def\">倹約;実直.</div>\r\n","<div class=\"hw\">frūgī</div><div class=\"pos\"><i>indecl adj</i></div><div class=\"def\">(本来 frux の <i>sg dat</i>)</div><div class=\"def\"><num>①</num> りっぱな, 有徳の.</div><div class=\"def\"><num>②</num> 慎しみ深い;質素な.</div>\r\n","<div class=\"hw\">frūmentor</div><div class=\"pos\">-ārī -ātus sum, <i>intr dep</i></div><div class=\"ori\">[↓<a href=\"entry://frūmentum\">frūmentum</a>]</div><div class=\"def\">穀物を調達する, 食糧を徴発する.</div>\r\n","<div class=\"hw\">frūmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[frux]</div><div class=\"def\">穀物.</div>\r\n","<div class=\"hw\">frūmentāceus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">=<a href=\"entry://frūmentārius\">frumentarius<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">frūmentālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">=<a href=\"entry://frūmentārius\">frumentarius<SUP>1</SUP></a>.</div>\r\n","<div class=\"hw\">frūmentārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[frumentum]</div><div class=\"def\">穀物の</div><div class=\"ex\"><i>navis frumentaria</i> (<author>C<small>AES</small></author>)<span class=\"ext\">穀物輸送船</span></div><div class=\"ex\"><i>lex frumentaria</i> (<author>C<small>IC</small></author>)<span class=\"ext\">穀物の分配に関する法律.</span></div><hr><div class=\"hw\">frūmentārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 穀物商人.</div><div class=\"def\"><num>②</num> 〘軍〙食糧徴発兵(=<a href=\"entry://frūmentātor\">frumentator</a>).</div>\r\n","<div class=\"hw\">frūmentātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[frumentor]</div><div class=\"def\"><num>①</num> 食糧徴発.</div><div class=\"def\"><num>②</num> 穀物の分配.</div>\r\n","<div class=\"hw\">frūmentātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://frūmentor\">frūmentor</a>]</div><div class=\"def\"><num>①</num> 穀物商人.</div><div class=\"def\"><num>②</num> 〘軍〙食糧徴発兵.</div>\r\n","<div class=\"hw\">frūniscor</div><div class=\"pos\">-scī -nītus sum, <i>tr</i>, <i>intr dep</i></div><div class=\"ori\">[fruor]</div><div class=\"def\">楽しむ.</div>\r\n","<div class=\"hw\">frūniscī</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://frūniscor\">fruniscor</a>.</div>\r\n","<div class=\"hw\">frūnītus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://frūniscor\">fruniscor</a>.</div>\r\n","<div class=\"hw\">fu</div><div class=\"pos\"><i>int</i></div><div class=\"def\">(嫌悪感を表わす)チェッ, フフン.</div>\r\n","<div class=\"hw\">fuam, fuas, fuat, ▶etc.◀</div><div class=\"pos\"><i>subj pr</i></div><div class=\"def\">《古形》=sim, sis, sit, etc.(⇒ <a href=\"entry://sum\">sum</a>).</div>\r\n","<div class=\"hw\">fueram</div><div class=\"pos\"><i>plpf</i></div><div class=\"def\">⇒<a href=\"entry://sum\">sum</a>.</div>\r\n","<div class=\"hw\">fuerō</div><div class=\"pos\"><i>fut pf</i></div><div class=\"def\">⇒<a href=\"entry://sum\">sum</a>.</div>\r\n","<div class=\"hw\">fuga</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 逃走;敗走.</div><div class=\"def\"><num>②</num> 追放.</div><div class=\"def\"><num>③</num> 回避, 忌避 〈alcis rei〉.</div><div class=\"def\"><num>④</num> 飛び去ること, 速さ</div><div class=\"ex\"><i>～ temporum</i> (<author>H<small>OR</small></author>)<span class=\"ext\">去り行く時代の流れ.</span></div>\r\n","<div class=\"hw\">fugax</div><div class=\"pos\">-ācis, <i>adj</i></div><div class=\"ori\">[fuga]</div><div class=\"def\"><num>①</num> 逃げようとする.</div><div class=\"def\"><num>②</num> 速い.</div><div class=\"def\"><num>③</num> はかない, うつろいやすい.</div><div class=\"def\"><num>④</num> 避けている 〈+<i>gen</i>〉.</div>\r\n","<div class=\"hw\">fugere</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://fugiō\">fugio</a>.</div>\r\n","<div class=\"hw\">fugiens<SUP>1</SUP></div><div class=\"pos\">-entis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[fugio]</div><div class=\"def\"><num>①</num> 逃げる, 消え去る</div><div class=\"ex\"><i>vinum ～</i> (<author>C<small>IC</small></author>)<span class=\"ext\">気の抜けたぶどう酒.</span></div><div class=\"def\"><num>②</num> 避けている 〈+<i>gen</i>〉.</div><hr><div class=\"hw\">fugiens<SUP>2</SUP></div><div class=\"pos\">-entis, <SUP>◇</SUP><i>m</i></div><div class=\"def\">〘法〙被告人.</div>\r\n","<div class=\"hw\">fugitor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[fugio]</div><div class=\"def\">逃亡者.</div>\r\n","<div class=\"hw\">fugitīvus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://fugiō\">fugiō</a>]</div><div class=\"def\">逃げた.</div><hr><div class=\"hw\">fugitīvus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">逃亡者《特に逃亡奴隷》.</div>\r\n","<div class=\"hw\">fugitō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>, <i>tr freq</i></div><div class=\"ori\">[fugio]</div><div class=\"def\"><num>①</num> 逃げる.</div><div class=\"def\"><num>②</num> 避ける, 遠ざける 〈alqd [alqm];+<i>inf</i>〉.</div>\r\n","<div class=\"hw\">fugiō</div><div class=\"pos\">-gere fūgī(<i>fut p</i> fugitūrus), <i>intr</i>, <i>tr</i></div><div class=\"def\"><num0>Ⅰ</num0> (<i>intr</i>)</div><div class=\"def\"><num>①</num> 逃げる, 逃走する, 走り去る 〈a [ex] re;ad [in] alqd〉.</div><div class=\"def\"><num>②</num> 追放される, 亡命する.</div><div class=\"def\"><num>③</num> 消える, 過ぎ去る.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>tr</i>)</div><div class=\"def\"><num>①</num> (...から)逃げる, のがれる 〈alqm [alqd]〉.</div><div class=\"def\"><num>②</num> 避ける, 遠ざける</div><div class=\"ex\"><i>fuge quaerere</i> (<author>H<small>OR</small></author>)<span class=\"ext\">問うことをやめよ.</span></div><div class=\"def\"><num>③</num> (人の注意などを)免れる, 気づかれない</div><div class=\"ex\"><i>neque haec Dionysium fugiebant</i> (<author>N<small>EP</small></author>)<span class=\"ext\">これらのことに Dionysius も気づいていた</span></div><div class=\"ex\"><i>fūgit</i>(pf)<i>te ratio</i> (<author>P<small>LAUT</small></author>)<span class=\"ext\">分別がおまえを見捨てた(=おまえは間違えた).</span></div>\r\n","<div class=\"hw\">fugāciter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[fugax]</div><div class=\"def\">逃避的に.</div>\r\n","<div class=\"hw\">fugātor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[fugo]</div><div class=\"def\">逃走させる者.</div>\r\n","<div class=\"hw\">fugātrix</div><div class=\"pos\">-ōris <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↑<a href=\"entry://fugātor\">fugātor</a>]</div><div class=\"def\">逃走させる者《女性》.</div>\r\n","<div class=\"hw\">fugō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[fuga]</div><div class=\"def\">逃走させる, 追い払う 〈alqm [alqd]〉.</div>\r\n","<div class=\"hw\">fuisse</div><div class=\"pos\"><i>inf pf</i></div><div class=\"def\">⇒<a href=\"entry://sum\">sum</a>.</div>\r\n","<div class=\"hw\">fulciō</div><div class=\"pos\">-īre fulsī fultum, <i>tr</i></div><div class=\"def\"><num>①</num> 支える, 支柱を付ける.</div><div class=\"def\"><num>②</num> 強くする, 強固にする.</div><div class=\"def\"><num>③</num> 支援する, 元気づける.</div>\r\n","<div class=\"hw\">fulcrum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↑<a href=\"entry://fulciō\">fulciō</a>]</div><div class=\"def\"><num>①</num> (寝台・食事用臥台の)支柱, 脚.</div><div class=\"def\"><num>②</num> 寝台, 食事用臥台.</div>\r\n","<div class=\"hw\">fulcīmen</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"ori\">[fulcio]</div><div class=\"def\">支え, 支柱.</div>\r\n","<div class=\"hw\">fulcīmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">=<a href=\"entry://fulcīmen\">fulcimen</a>.</div>\r\n","<div class=\"hw\">Fulcīnius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">フルキーニウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">fulgescō</div><div class=\"pos\">-ere, <SUP>◇</SUP><i>intr inch</i></div><div class=\"ori\">[↑<a href=\"entry://fulgeō\">fulgeō</a>]</div><div class=\"def\">光を放つ, 輝く.</div>\r\n","<div class=\"hw\">fulgetrum</div><div class=\"pos\">-ī, <i>n</i>, <B>-tra</B> -ae, <i>f</i></div><div class=\"ori\">[fulgeo]</div><div class=\"def\">稲光, 稲妻.</div>\r\n","<div class=\"hw\">fulgeō</div><div class=\"pos\">-ēre fulsī, <i>intr</i></div><div class=\"def\"><num>①</num> きらめく, 輝く.</div><div class=\"def\"><num>②</num> 目立つ, 際立つ.</div>\r\n","<div class=\"hw\">fulgidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fulgeo]</div><div class=\"def\">きらめく, 輝く.</div>\r\n","<div class=\"hw\">fulgor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[fulgeo]</div><div class=\"def\"><num>①</num> きらめき, 輝き.</div><div class=\"def\"><num>②</num> 稲光, 稲妻.</div><div class=\"def\"><num>③</num> 光る物体;流星.</div><div class=\"def\"><num>④</num> 卓越, 栄誉, 名声.</div>\r\n","<div class=\"hw\">fulgur</div><div class=\"pos\">-uris, <i>n</i></div><div class=\"ori\">[fulgeo]</div><div class=\"def\"><num>①</num> 稲光.</div><div class=\"def\"><num>②</num> きらめき, 輝き.</div>\r\n","<div class=\"hw\">fulguriō</div><div class=\"pos\">-īre -īvī -ītum, <i>intr</i>, <i>tr</i></div><div class=\"ori\">[fulgur]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>intr</i>)(Juppiter が)稲妻を投ずる.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>tr</i>)(用例は <i>pp</i> fulgurītus のみ)雷に打たれた.</div>\r\n","<div class=\"hw\">fulgurālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://fulgur\">fulgur</a>]</div><div class=\"def\">稲光の.</div>\r\n","<div class=\"hw\">fulgurātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[fulguro]</div><div class=\"def\">電光, 稲光.</div>\r\n","<div class=\"hw\">fulgurātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[fulguro]</div><div class=\"def\"><num>①</num> 稲妻による占者.</div><div class=\"def\"><num>②</num> (Juppiter の添え名として)稲妻を投ずる者.</div>\r\n","<div class=\"hw\">fulgurātūra</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[fulguro]</div><div class=\"def\">稲妻による占い.</div>\r\n","<div class=\"hw\">fulgurō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"ori\">[fulgur]</div><div class=\"def\"><num>①</num> (<i>impers</i>)稲妻が光る.</div><div class=\"def\"><num>②</num> 光を放つ, 輝く.</div>\r\n","<div class=\"hw\">fulgō</div><div class=\"pos\">-ere, <i>intr</i></div><div class=\"def\">=<a href=\"entry://fulgeō\">fulgeo</a>.</div>\r\n","<div class=\"hw\">fulica</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘鳥〙オオバン.</div>\r\n","<div class=\"hw\">fulix</div><div class=\"pos\">-icis, <i>f</i></div><div class=\"def\">=<a href=\"entry://fulica\">fulica</a>.</div>\r\n","<div class=\"hw\">fullō</div><div class=\"pos\">-ōnis, <i>m</i></div><div class=\"def\">洗い張り屋.</div>\r\n","<div class=\"hw\">fullōnia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[fullonius]</div><div class=\"def\">(<i>sc. </i> ars)洗い張り業.</div>\r\n","<div class=\"hw\">fullōnica</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://fullōnicus\">fullōnicus</a>]</div><div class=\"def\"><num>①</num> (<i>sc. </i> officina)洗い張り屋の店[作業場].</div><div class=\"def\"><num>②</num> (<i>sc. </i> ars)洗い張り業.</div>\r\n","<div class=\"hw\">fullōnicus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://fullōnius\">fullonius</a>.</div>\r\n","<div class=\"hw\">fullōnius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fullo]</div><div class=\"def\">洗い張り屋の.</div>\r\n","<div class=\"hw\">fulmen</div><div class=\"pos\">-minis, <i>n</i></div><div class=\"ori\">[<<SUP>*</SUP>fulgmen<fulgeo]</div><div class=\"def\"><num>①</num> (落雷する)稲妻, 落雷.</div><div class=\"def\"><num>②</num> 突然の災難, 壊滅的打撃;抗しがたい力.</div>\r\n","<div class=\"hw\">fulmenta</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[fulcio]</div><div class=\"def\">支柱, つっかい.</div>\r\n","<div class=\"hw\">fulmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[fulcio]</div><div class=\"def\"><num>①</num> 支柱, つっかい.</div><div class=\"def\"><num>②</num> 家具の脚.</div>\r\n","<div class=\"hw\">fulmineus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fulmen]</div><div class=\"def\"><num>①</num> 稲妻の, 落雷の.</div><div class=\"def\"><num>②</num> 光り輝く.</div><div class=\"def\"><num>③</num> 破壊的な;電光石火の.</div>\r\n","<div class=\"hw\">fulminātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[fulmino]</div><div class=\"def\">落雷.</div>\r\n","<div class=\"hw\">fulminō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>, <i>tr</i></div><div class=\"ori\">[fulmen]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>intr</i>)(<i>impers</i>)稲妻が光る.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>tr</i>)稲妻で打つ.</div>\r\n","<div class=\"hw\">fulsī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://fulciō\">fulcio</a>, <a href=\"entry://fulgeō\">fulgeo</a>.</div>\r\n","<div class=\"hw\">fultor</div><div class=\"pos\">-ōris, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[fulcio]</div><div class=\"def\">支持者.</div>\r\n","<div class=\"hw\">fultus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://fulciō\">fulcio</a>.</div>\r\n","<div class=\"hw\">fultūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[fulcio]</div><div class=\"def\"><num>①</num> 支え, 支柱.</div><div class=\"def\"><num>②</num> 強めること.</div>\r\n","<div class=\"hw\">Fulvius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">フルウィウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">fulvus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>cf. </i> flavus]</div><div class=\"def\">黄褐色の.</div>\r\n","<div class=\"hw\">functiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[fungor]</div><div class=\"def\"><num>①</num> 実行, 遂行.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>(関税・租税の)納付.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP> 消滅, 死.</div>\r\n","<div class=\"hw\">functus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://fungor\">fungor</a>.</div>\r\n","<div class=\"hw\">funda</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[fundo<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 投石器.</div><div class=\"def\"><num>②</num> (投石器から発射される)石.</div><div class=\"def\"><num>③</num> 投網<SUB>とあみ</SUB>.</div>\r\n","<div class=\"hw\">fundibalus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[funda]</div><div class=\"def\">投石器.</div>\r\n","<div class=\"hw\">fundibulum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[fundo<SUP>2</SUP>]</div><div class=\"def\">投石器.</div>\r\n","<div class=\"hw\">fundibulārius</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[funda]</div><div class=\"def\">投石兵(=<a href=\"entry://funditor\">funditor</a>).</div>\r\n","<div class=\"hw\">fundiformis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"def\">〘解〙三角巾形の.</div>\r\n","<div class=\"hw\">funditor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[funda]</div><div class=\"def\">投石兵.</div>\r\n","<div class=\"hw\">funditus</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[fundus]</div><div class=\"def\"><num>①</num> 土台から, 根こそぎ.</div><div class=\"def\"><num>②</num> 完全に, 徹底的に.</div><div class=\"def\"><num>③</num> 底に, 下に.</div>\r\n","<div class=\"hw\">funditō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr freq</i></div><div class=\"ori\">[fundo<SUP>2</SUP>]</div><div class=\"def\">投石する;投げつける.</div>\r\n","<div class=\"hw\">fundula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">袋小路, 行き止まり.</div>\r\n","<div class=\"hw\">fundus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 底</div><div class=\"ex\"><i>largitio non habet fundum</i> (<author>C<small>IC</small></author>)<span class=\"ext\">施しに限度はない.</span></div><div class=\"def\"><num>②</num> 基礎.</div><div class=\"def\"><num>③</num> (計画・行動などの)決定の根拠を与える者, 認可する者</div><div class=\"ex\"><i>fundum fieri legis</i> (<author>C<small>IC</small></author>)<span class=\"ext\">法律の是認者となる(=法律を裁可する).</span></div><div class=\"def\"><num>④</num> 地所, 農地.</div><div class=\"def\"><num>⑤</num> <SUP>◇</SUP>〘解〙(胃・眼・子宮などの)基底部, 底.</div>\r\n","<div class=\"hw\">fundāmen</div><div class=\"pos\">-minis, <i>m</i></div><div class=\"ori\">[fundo<SUP>1</SUP>]</div><div class=\"def\">基礎, 土台.</div>\r\n","<div class=\"hw\">fundāmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[fundo<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> (建物などの)基礎, 土台.</div><div class=\"def\"><num>②</num> 根拠, 根底.</div>\r\n","<div class=\"hw\">fundāmentālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://fundāmen\">fundāmen</a>]</div><div class=\"def\">基礎の, 根本的な.</div>\r\n","<div class=\"hw\">fundāmentāliter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://fundāmentālis\">fundāmentālis</a>]</div><div class=\"def\">根本から, 完全に.</div>\r\n","<div class=\"hw\">Fundānius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">フンダーニウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">Fundānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Fundi の.</div><div class=\"hw2\"><b>Fundānī</b></div><div class=\"pos2\">-ōrum, <i>m pl</i></div><div class=\"def2\">Fundi の住民.</div>\r\n","<div class=\"hw\">fundātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[fundo<SUP>1</SUP>]</div><div class=\"def\">(建物の)基礎.</div>\r\n","<div class=\"hw\">fundātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[fundo<SUP>1</SUP>]</div><div class=\"def\">創建[創設]者.</div>\r\n","<div class=\"hw\">fundātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[fundo<SUP>1</SUP>]</div><div class=\"def\">しっかりした, 確固たる.</div>\r\n","<div class=\"hw\">Fundī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"def\">フンディー《Latium の町;現 Fondi》.</div>\r\n","<div class=\"hw\">fundō<SUP>1</SUP></div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[fundus]</div><div class=\"def\"><num>①</num> 土台[基礎]を据える.</div><div class=\"def\"><num>②</num> 確立する, 強固にする</div><div class=\"ex\"><i>fundare nostrum imperium</i> (<author>C<small>IC</small></author>)<span class=\"ext\">われわれの支配権を確立する.</span></div><div class=\"def\"><num>③</num> 創建[創設]する.</div><hr><div class=\"hw\">fundō<SUP>2</SUP></div><div class=\"pos\">-ere fūdī fūsum, <i>tr</i></div><div class=\"def\"><num>①</num> 注ぐ, こぼす.</div><div class=\"def\"><num>②</num> ぬらす 〈+<i>abl</i>〉.</div><div class=\"def\"><num>③</num> 溶かす, 鋳造する.</div><div class=\"def\"><num>④</num> 投げつける, まき散らす;投げ倒す.</div><div class=\"def\"><num>⑤</num> (<i>refl</i>, <i>pass</i>)飛び出る</div><div class=\"ex\"><i>agmina se fundunt portis</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">軍勢が城門からどっと駆け出る.</span></div><div class=\"def\"><num>⑥</num> (豊富に)産み出す, もたらす.</div><div class=\"def\"><num>⑦</num> (敵を)撃破する, 敗走させる.</div><div class=\"def\"><num>⑧</num> 広げる, 伸ばす</div><div class=\"ex\"><i>tum se latius fundet orator</i> (<author>C<small>IC</small></author>)<span class=\"ext\">そうなれば雄弁家は自らの力量をいっそう発揮するだろう.</span></div><div class=\"def\"><num>⑨</num> (ことばなどを)発する, 口に出す.</div>\r\n","<div class=\"hw\">fungibilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[fungor]</div><div class=\"def\">〘法〙代替可能な.</div>\r\n","<div class=\"hw\">fungor</div><div class=\"pos\">-gī functus sum, <i>tr</i>, <i>intr dep</i></div><div class=\"def\"><num>①</num> 実行する, 遂行する, 果たす, 達成する 〈+<i>abl</i> [<i>acc</i>]〉</div><div class=\"ex\"><i>vitā fungi</i> (<author>G<small>ELL</small></author>)<span class=\"ext\">死ぬ</span></div><div class=\"ex\"><i>fungitur officio boni senatoris</i> (<author>C<small>IC</small></author>)<span class=\"ext\">彼は良き元老院議員の務めを果たしている.</span></div><div class=\"def\"><num>②</num> こうむる, 経験する 〈<i>abs</i>〉.</div>\r\n","<div class=\"hw\">fungus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> キノコ.</div><div class=\"def\"><num>②</num> 灯心にできるカビ状のもの.</div><div class=\"def\"><num>③</num> (非難のことばとして)ばか, まぬけ.</div>\r\n","<div class=\"hw\">fungī</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://fungor\">fungor</a>.</div>\r\n","<div class=\"hw\">fungīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fungus]</div><div class=\"def\">キノコの.</div>\r\n","<div class=\"hw\">fungōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://fungus\">fungus</a>]</div><div class=\"def\">穴の多い, 海綿状の.</div>\r\n","<div class=\"hw\">furca</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 熊手, 股鍬<SUB>またぐわ</SUB>.</div><div class=\"def\"><num>②</num> (Y 字形の)支柱, 叉木<SUB>またぎ</SUB>.</div><div class=\"def\"><num>③</num> 叉木状の刑具, さらし台.</div>\r\n","<div class=\"hw\">furcifer</div><div class=\"pos\">-ferī, <i>m</i></div><div class=\"ori\">[↑<a href=\"entry://furca\">furca</a>/fero]</div><div class=\"def\">(絞首刑に処すべき)悪党, 極悪人《通例, 奴隷に対するののしりのことばとして》.</div>\r\n","<div class=\"hw\">furcilla</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[furca]</div><div class=\"def\">(小さな)熊手, 股鍬.</div>\r\n","<div class=\"hw\">furcillātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[↓<a href=\"entry://furcillō\">furcillō</a>]</div><div class=\"def\">叉<SUB>また</SUB>状の.</div>\r\n","<div class=\"hw\">furcillō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"ori\">[furcilla]</div><div class=\"def\">叉木状の刑具で罰する;非難する.</div>\r\n","<div class=\"hw\">furcula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[furca]</div><div class=\"def\"><num>①</num> (Y 字形の)支柱, 叉木.</div><div class=\"def\"><num>②</num> <i>Furculae Caudinae</i> (<author>L<small>IV</small></author>) ローマ軍が Samnium 人に攻囲された(前321)ことで有名な Caudium 付近の狭い谷道.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘昆〙叉状器.</div>\r\n","<div class=\"hw\">furenter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[furo]</div><div class=\"def\">狂ったように.</div>\r\n","<div class=\"hw\">furfur</div><div class=\"pos\">-uris, <i>m</i></div><div class=\"def\"><num>①</num> ぬか, ふすま.</div><div class=\"def\"><num>②</num> ふけ.</div>\r\n","<div class=\"hw\">furfureus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[furfur]</div><div class=\"def\">ぬかの.</div>\r\n","<div class=\"hw\">furfurāceus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://furfur\">furfur</a>]</div><div class=\"def\">ぬかのような.</div>\r\n","<div class=\"hw\">furfurōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[furfur]</div><div class=\"def\">ぬかのような, 茶色がかった.</div>\r\n","<div class=\"hw\">furia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[furo]</div><div class=\"def\"><num>①</num> 憤激, 激怒;狂乱;激情.</div><div class=\"def\"><num>②</num> (<i>pl</i> Furiae)〘神話〙フリアエ《ローマの復讐の女神たち;ギリシア神話の Erinyes に当たる》.</div>\r\n","<div class=\"hw\">furibundus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[furo]</div><div class=\"def\"><num>①</num> 怒り狂う, 荒れ狂う.</div><div class=\"def\"><num>②</num> 霊感を受けた.</div>\r\n","<div class=\"hw\">furiālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://furia\">furia</a>]</div><div class=\"def\"><num>①</num> 復讐の女神たちの.</div><div class=\"def\"><num>②</num> 荒れ狂う, 狂乱の.</div><div class=\"def\"><num>③</num> 狂乱させる.</div>\r\n","<div class=\"hw\">furiāliter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://furiālis\">furiālis</a>]</div><div class=\"def\">狂ったように.</div>\r\n","<div class=\"hw\">furiātilis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[furia]</div><div class=\"def\">怒り狂う.</div>\r\n","<div class=\"hw\">furiō<SUP>1</SUP></div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[furia]</div><div class=\"def\">狂乱させる, 激怒させる.</div><hr><div class=\"hw\">furiō<SUP>2</SUP></div><div class=\"pos\">-īre, <SUP>◇</SUP><i>intr</i></div><div class=\"ori\">[furia]</div><div class=\"def\">激怒している.</div>\r\n","<div class=\"hw\">furiōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[furia]</div><div class=\"def\"><num>①</num> 狂乱した.</div><div class=\"def\"><num>②</num> 狂暴な, 気違いじみた.</div>\r\n","<div class=\"hw\">furiōsē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://furiōsus\">furiōsus</a>]</div><div class=\"def\">狂ったように.</div>\r\n","<div class=\"hw\">Furnius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">フルニウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">furnus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[<i>cf. </i> fornax]</div><div class=\"def\">かまど.</div>\r\n","<div class=\"hw\">furnāceus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[furnus]</div><div class=\"def\">かまどで焼いた.</div>\r\n","<div class=\"hw\">furnāria</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[furnus]</div><div class=\"def\">パン屋.</div>\r\n","<div class=\"hw\">furor<SUP>1</SUP></div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[↑<a href=\"entry://furō\">furō</a>]</div><div class=\"def\"><num>①</num> 狂乱;熱狂.</div><div class=\"def\"><num>②</num> 霊感を受けること.</div><div class=\"def\"><num>③</num> 激情;激怒.</div><div class=\"def\"><num>④</num> 狂暴なふるまい.</div><div class=\"def\"><num>⑤</num> (嵐などの)猛威.</div>\r\n","<div class=\"hw\">furtificus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[furtum/facio]</div><div class=\"def\">盗みをする, 盗癖のある.</div>\r\n","<div class=\"hw\">furtim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[furtum]</div><div class=\"def\">秘密に, ひそかに, こっそりと.</div>\r\n","<div class=\"hw\">furtum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[fur]</div><div class=\"def\"><num>①</num> 盗み, 窃盗;誘拐<SUB>ゆうかい</SUB>.</div><div class=\"def\"><num>②</num> 盗品.</div><div class=\"def\"><num>③</num> 公明正大ではない手段[方法], 欺瞞<SUB>ぎまん</SUB>.</div><div class=\"def\"><num>④</num> 隠すこと, 隠蔽<SUB>いんぺい</SUB></div><div class=\"ex\"><i>furto noctis</i> (<author>T<small>AC</small></author>)<span class=\"ext\">闇にまぎれて.</span></div><div class=\"def\"><num>⑤</num> ひそかな恋, 密通.</div>\r\n","<div class=\"hw\">furtīvus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[furtum]</div><div class=\"def\"><num>①</num> 盗まれた.</div><div class=\"def\"><num>②</num> 秘密の, ひそかな.</div>\r\n","<div class=\"hw\">furtīvē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://furtīvus\">furtīvus</a>]</div><div class=\"def\">ひそかに, こっそりと.</div>\r\n","<div class=\"hw\">furtō</div><div class=\"pos\"><i>adv</i>(<i>abl</i>)</div><div class=\"ori\">[↓<a href=\"entry://furtum\">furtum</a>]</div><div class=\"def\">ひそかに, こっそりと.</div>\r\n","<div class=\"hw\">furvus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>cf. </i> fuscus]</div><div class=\"def\">うす暗い, 黒ずんだ</div><div class=\"ex\"><i>dies ～</i> (<author>S<small>EN</small> M<small>AJ</small></author>)<span class=\"ext\">不吉な日(=<a href=\"entry://āter\">dies ater</a>).</span></div>\r\n","<div class=\"hw\">Furīna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘神話〙フリーナ《古い時代にイタリアで崇拝されていた女神》.</div>\r\n","<div class=\"hw\">furō</div><div class=\"pos\">-ere, <i>intr</i></div><div class=\"def\"><num>①</num> 狂乱する.</div><div class=\"def\"><num>②</num> 激怒する.</div><div class=\"def\"><num>③</num> 熱狂する.</div><div class=\"def\"><num>④</num> 荒れ狂う.</div>\r\n","<div class=\"hw\">fuscina</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">三叉の槍[ほこ].</div>\r\n","<div class=\"hw\">fuscinula</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f dim</i></div><div class=\"ori\">[↑<a href=\"entry://fuscina\">fuscina</a>]</div><div class=\"def\">小さな三叉フォーク, 肉刺し.</div>\r\n","<div class=\"hw\">fuscus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>cf. </i> furvus]</div><div class=\"def\"><num>①</num> うす暗い, 黒ずんだ.</div><div class=\"def\"><num>②</num> はっきりしない, かすれた.</div>\r\n","<div class=\"hw\">fuscō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://fuscus\">fuscus</a>]</div><div class=\"def\">黒くする, 暗くする.</div>\r\n","<div class=\"hw\">fustis</div><div class=\"pos\">-is, <i>m</i>(<i>sg abl</i> fuste [fusti])</div><div class=\"def\">棒, 棍棒.</div>\r\n","<div class=\"hw\">fustuārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↑<a href=\"entry://fustis\">fustis</a>]</div><div class=\"def\">棍棒で打ち殺すこと《軍隊での処罰》.</div>\r\n","<div class=\"hw\">fustīgō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://fustis\">fustis</a>]</div><div class=\"def\">棍棒で打ち殺す.</div>\r\n","<div class=\"hw\">futuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://futuō\">futuo</a>.</div>\r\n","<div class=\"hw\">futuō</div><div class=\"pos\">-ere -uī -ūtum, <i>tr</i></div><div class=\"def\">(女と)同衾する 〈<i>abs</i>;alqm〉.</div>\r\n","<div class=\"hw\">futūrum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://futūrus\">futūrus</a>]</div><div class=\"def\">未来, 将来.</div>\r\n","<div class=\"hw\">futūrus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>fut p</i>)</div><div class=\"ori\">[sum]</div><div class=\"def\"><num>①</num> 未来の, 将来の.</div><div class=\"def\"><num>②</num> 今にも起こりそうな, 差し迫った.</div>\r\n","<div class=\"hw\">futūtiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[futuo]</div><div class=\"def\">交接.</div>\r\n","<div class=\"hw\">futūtus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://futuō\">futuo</a>.</div>\r\n","<div class=\"hw\">fuī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://sum\">sum</a>.</div>\r\n","<div class=\"hw\">fābella</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[fabula]</div><div class=\"def\"><num>①</num> (小さな)物語.</div><div class=\"def\"><num>②</num> 寓話.</div><div class=\"def\"><num>③</num> (小さな)芝居.</div>\r\n","<div class=\"hw\">fābula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>cf. </i> fari, fama]</div><div class=\"def\"><num>①</num> 談話, 会話</div><div class=\"ex\"><i>lupus in fabula</i> (<author>T<small>ER</small></author>)<span class=\"ext\">うわさをすれば影.</span></div><div class=\"def\"><num>②</num> 話, 報告</div><div class=\"ex\"><i>quae haec est ～?</i> (<author>T<small>ER</small></author>)<span class=\"ext\">こりゃ何の話だ.</span></div><div class=\"def\"><num>③</num> 物語.</div><div class=\"def\"><num>④</num> うわさ, 風説.</div><div class=\"def\"><num>⑤</num> 作り話</div><div class=\"ex\"><i>fabulae!</i> (<author>T<small>ER</small></author>)<span class=\"ext\">ばかな!</span></div><div class=\"def\"><num>⑥</num> 寓話.</div><div class=\"def\"><num>⑦</num> 伝説, 神話.</div><div class=\"def\"><num>⑧</num> 劇, 芝居.</div>\r\n","<div class=\"hw\">fābulor</div><div class=\"pos\">-ārī -ātus sum, <i>intr</i>, <i>tr dep</i></div><div class=\"ori\">[fabula]</div><div class=\"def\"><num>①</num> おしゃべりする, 雑談する 〈alqd;cum alqo;inter se;de re〉.</div><div class=\"def\"><num>②</num> (話を)でっちあげる 〈alqd〉.</div>\r\n","<div class=\"hw\">fābulāris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://fābula\">fābula</a>]</div><div class=\"def\">伝説[神話]的な, 架空の.</div>\r\n","<div class=\"hw\">fābulātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[fabulor]</div><div class=\"def\">談話, 会話.</div>\r\n","<div class=\"hw\">fābulātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[fabulor]</div><div class=\"def\"><num>①</num> 語り手.</div><div class=\"def\"><num>②</num> 物語作者;寓話作者.</div>\r\n","<div class=\"hw\">fābulō</div><div class=\"pos\">-āre -āvī, <i>intr</i>, <i>tr</i></div><div class=\"def\">=<a href=\"entry://fābulor\">fabulor</a>.</div>\r\n","<div class=\"hw\">fābulōsitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://fābulōsus\">fābulōsus</a>]</div><div class=\"def\"><num>①</num> 信じられない[ありそうにない]こと.</div><div class=\"def\"><num>②</num> 伝説(の創作).</div>\r\n","<div class=\"hw\">fābulōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fabula]</div><div class=\"def\"><num>①</num> 伝説で有名な, 伝説的な.</div><div class=\"def\"><num>②</num> 信じられないような.</div><div class=\"def\"><num>③</num> 架空の, 作り話の.</div>\r\n","<div class=\"hw\">fābulōsē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[fabulosus]</div><div class=\"def\">伝説的に, 架空の話として</div><div class=\"ex\"><i>insulae ～ narratae</i> (<author>P<small>LIN</small></author>)<span class=\"ext\">伝説で語られる島々.</span></div>\r\n","<div class=\"hw\">fācundia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[facundus]</div><div class=\"def\">雄弁, 能弁.</div>\r\n","<div class=\"hw\">fācunditās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://fācundus\">fācundus</a>]</div><div class=\"def\">雄弁, 能弁.</div>\r\n","<div class=\"hw\">fācundus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fari]</div><div class=\"def\">雄弁な, 能弁な, 流暢な.</div>\r\n","<div class=\"hw\">fācundē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[facundus]</div><div class=\"def\">雄弁に, 能弁に.</div>\r\n","<div class=\"hw\">fāgineus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fagus]</div><div class=\"def\">ブナノキの;ブナ材の.</div>\r\n","<div class=\"hw\">fāginus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fagus]</div><div class=\"def\">ブナ材の.</div>\r\n","<div class=\"hw\">fāgum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://fāgus\">fāgus</a>]</div><div class=\"def\">ブナの実.</div>\r\n","<div class=\"hw\">fāgus</div><div class=\"pos\">-ī, <i>f</i></div><div class=\"ori\">[<i>Gk</i>]</div><div class=\"def\"><num>①</num> 〘植〙ブナノキ.</div><div class=\"def\"><num>②</num> ブナ材.</div>\r\n","<div class=\"hw\">fāma</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>cf</i>. fari]</div><div class=\"def\"><num>①</num> 報告.</div><div class=\"def\"><num>②</num> うわさ.</div><div class=\"def\"><num>③</num> 言い伝え, 伝承.</div><div class=\"def\"><num>④</num> 世論.</div><div class=\"def\"><num>⑤</num> 評判 〈+<i>gen</i>〉</div><div class=\"ex\"><i>～ sapientiae</i> (<author>C<small>IC</small></author>)<span class=\"ext\">賢者であるという評判.</span></div><div class=\"def\"><num>⑥</num> 好評, 名声;悪名.</div>\r\n","<div class=\"hw\">fāmigerābilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[fama/gero]</div><div class=\"def\">有名な, 名高い.</div>\r\n","<div class=\"hw\">fāmigerātiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[famigeratus]</div><div class=\"def\">うわさ, 評判.</div>\r\n","<div class=\"hw\">fāmigerātor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[↓<a href=\"entry://fāmigerātus\">fāmigerātus</a>]</div><div class=\"def\">うわさを広める者.</div>\r\n","<div class=\"hw\">fāmigerātus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fama/gero]</div><div class=\"def\">有名な.</div>\r\n","<div class=\"hw\">fāmātus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://fāma\">fāma</a>]</div><div class=\"def\">悪名高い, 評判の悪い.</div>\r\n","<div class=\"hw\">fāmōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fama]</div><div class=\"def\"><num>①</num> 有名な, 名高い.</div><div class=\"def\"><num>②</num> 悪名高い.</div><div class=\"def\"><num>③</num> 中傷的な.</div>\r\n","<div class=\"hw\">fāmōsē</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://fāmōsus\">fāmōsus</a>]</div><div class=\"def\">名高く, 輝かしく.</div>\r\n","<div class=\"hw\">Fānester</div><div class=\"pos\">-tris -tre, <i>adj</i></div><div class=\"def\">Fanum の.</div>\r\n","<div class=\"hw\">fānor</div><div class=\"pos\">-ārī -ātus sum, <i>intr dep</i></div><div class=\"ori\">[fanum]</div><div class=\"def\">暴れ回る, 狂乱する.</div>\r\n","<div class=\"hw\">fānum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">聖域, 神殿.</div>\r\n","<div class=\"hw\">Fānum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\">ファーヌム《Umbria の海辺の町;Fortuna の神殿があったことから ～ Fortunae とも呼ばれた;現 Fano》.</div>\r\n","<div class=\"hw\">fānāticus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fanum]</div><div class=\"def\"><num>①</num> 神殿の.</div><div class=\"def\"><num>②</num> 熱狂した, 狂乱した.</div>\r\n","<div class=\"hw\">fānāticē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://fānāticus\">fānāticus</a>]</div><div class=\"def\">狂乱して.</div>\r\n","<div class=\"hw\">fānō</div><div class=\"pos\">-āre, <i>tr</i></div><div class=\"ori\">[fanum]</div><div class=\"def\">献納[奉献]する.</div>\r\n","<div class=\"hw\">fārior</div><div class=\"pos\">-ārī, <i>intr dep</i></div><div class=\"ori\">[for]</div><div class=\"def\">話す, 言う.</div>\r\n","<div class=\"hw\">fārī</div><div class=\"pos\"><i>inf</i></div><div class=\"def\">⇒<a href=\"entry://for\">for</a>.</div>\r\n","<div class=\"hw\">fās</div><div class=\"pos\"><i>indecl n</i></div><div class=\"def\"><num>①</num> 神のおきて[命令].</div><div class=\"def\"><num>②</num> 正しいこと:<i>～ est</i> 正当である 〈alci;+<i>inf</i>;+<i>acc c.inf</i>〉</div><div class=\"ex\"><i>cives, si eos hoc nomine appellari ～ est</i> (<author>C<small>IC</small></author>)<span class=\"ext\">市民たち, もし彼らがこの名で呼ばれるのが正当であればだが.</span></div><div class=\"def\"><num>③</num> 運命, 宿命.</div>\r\n","<div class=\"hw\">fāticanus, -cinus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fatum/cano]</div><div class=\"def\">予言する.</div>\r\n","<div class=\"hw\">fātidicus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fatum/dico<SUP>2</SUP>]</div><div class=\"def\">予言する.</div><hr><div class=\"hw\">fātidicus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">予言者.</div>\r\n","<div class=\"hw\">fātifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[fatum/fero]</div><div class=\"def\">破滅[死]をもたらす.</div>\r\n","<div class=\"hw\">fātiloquium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://fātiloquus\">fātiloquus<SUP>1</SUP></a>]</div><div class=\"def\">予言.</div>\r\n","<div class=\"hw\">fātiloquus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fatum/loquor]</div><div class=\"def\">予言する.</div><hr><div class=\"hw\">fātiloquus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">予言者.</div>\r\n","<div class=\"hw\">Fātua</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘神話〙ファートゥア《Fauna の別名;<i>cf. </i> Fatuus》.</div>\r\n","<div class=\"hw\">fātum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[for]</div><div class=\"def\"><num>①</num> 神託, 予言.</div><div class=\"def\"><num>②</num> 神意, 天命.</div><div class=\"def\"><num>③</num> 天寿を全うすること, 自然死</div><div class=\"ex\"><i>fato obire</i> (<author>T<small>AC</small></author>)<span class=\"ext\">天寿を全うして死ぬ.</span></div><div class=\"def\"><num>④</num> 運命, 宿命.</div><div class=\"def\"><num>⑤</num> 破滅, 不運.</div><div class=\"def\"><num>⑥</num> (<i>pl</i> Fata)運命の女神たち(=<a href=\"entry://Parca\">Parcae</a>).</div><div class=\"def\"><num>⑦</num> 破滅をもたらすもの.</div>\r\n","<div class=\"hw\">fātuor<SUP>2</SUP></div><div class=\"pos\">-ārī, <SUP>◇</SUP><i>intr dep</i></div><div class=\"ori\">[Fatuus]</div><div class=\"def\">(予言の)霊感を受けている.</div>\r\n","<div class=\"hw\">fātur</div><div class=\"pos\">3 <i>sg ind pr</i></div><div class=\"def\">⇒<a href=\"entry://for\">for</a>.</div>\r\n","<div class=\"hw\">fātus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://for\">for</a>.</div><hr><div class=\"hw\">fātus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> <SUP>◇</SUP> ことば.</div><div class=\"def\"><num>②</num> 神託, 予言.</div><div class=\"def\"><num>③</num> 運命.</div>\r\n","<div class=\"hw\">Fātuus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">〘神話〙ファートゥウス《「話す者」 の意;Faunus の別名》.</div>\r\n","<div class=\"hw\">fātālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[fatum]</div><div class=\"def\"><num>①</num> 運命の;運命づけられた, 宿命的な</div><div class=\"ex\"><i>fatales deae</i> (<author>O<small>V</small></author>)<span class=\"ext\">=<a href=\"entry://Parca\">Parcae</a></span></div><div class=\"ex\"><i>annus ～ ad interitum hujus urbis</i> (<author>C<small>IC</small></author>)<span class=\"ext\">この町の破滅が運命づけられた年.</span></div><div class=\"def\"><num>②</num> 不運な, 破滅的な.</div>\r\n","<div class=\"hw\">fātālismus</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↑<a href=\"entry://fātālis\">fātālis</a>]</div><div class=\"def\">〘哲〙宿命論.</div>\r\n","<div class=\"hw\">fātāliter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[fatalis]</div><div class=\"def\">宿命的に, 不可避的に.</div>\r\n","<div class=\"hw\">fāvī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://faveō\">faveo</a>.</div>\r\n","<div class=\"hw\">fēcul-</div><div class=\"def\">⇒faecul-.</div>\r\n","<div class=\"hw\">fēcunditās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[fecundus]</div><div class=\"def\">豊饒<SUB>ほうじょう</SUB>, 多産, 豊かさ.</div>\r\n","<div class=\"hw\">fēcunditō</div><div class=\"pos\">-āre, <i>tr freq</i></div><div class=\"def\">《碑》=<a href=\"entry://fēcundō\">fecundo</a>.</div>\r\n","<div class=\"hw\">fēcundus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\"><num>①</num> 実り豊かな, 多産の, 肥沃な.</div><div class=\"def\"><num>②</num> 豊富な, あり余るほどの.</div><div class=\"def\"><num>③</num> (...に)富む 〈re;alcis rei〉</div><div class=\"ex\"><i>fecunda melle Calymne</i> (<author>O<small>V</small></author>)<span class=\"ext\">蜜に富む Calymne 島.</span></div><div class=\"def\"><num>④</num> 実り豊かにする, 肥沃にする</div><div class=\"ex\"><i>～ imber</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">豊饒の雨.</span></div>\r\n","<div class=\"hw\">fēcundē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[fecundus]</div><div class=\"def\">豊かに.</div>\r\n","<div class=\"hw\">fēcundō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://fēcundus\">fēcundus</a>]</div><div class=\"def\">肥沃にする, 多産にする.</div>\r\n","<div class=\"hw\">fēcī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://faciō\">facio</a>.</div>\r\n","<div class=\"hw\">fēlis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\">=<a href=\"entry://fēlēs\">feles</a>.</div>\r\n","<div class=\"hw\">fēlix<SUP>1</SUP></div><div class=\"pos\">-īcis, <i>adj</i></div><div class=\"def\"><num>①</num> 実り豊かな, 多産の, 肥沃な.</div><div class=\"def\"><num>②</num> 幸福な, 幸運な, 恵まれた 〈+<i>gen</i>;in re;+<i>inf</i>〉.</div><div class=\"def\"><num>③</num> さい先のよい, 都合のよい.</div><div class=\"def\"><num>④</num> 成功した 〈(in)re〉</div><div class=\"ex\"><i>tamquam et ipse ～ bello</i> (<author>T<small>AC</small></author>)<span class=\"ext\">あたかもみずからも戦いに勝利したかのように.</span></div>\r\n","<div class=\"hw\">Fēlix</div><div class=\"pos\">-icis, <i>m</i></div><div class=\"def\">フェーリクス《よく用いられるローマ人の添え名;特に <i>L. Cornelius Sulla ～</i> ⇒ <a href=\"entry://Sulla\">Sulla</a>》.</div>\r\n","<div class=\"hw\">fēlēs</div><div class=\"pos\">-is, <i>f</i></div><div class=\"def\"><num>①</num> 〘動〙ネコ.</div><div class=\"def\"><num>②</num> かどわかす者.</div>\r\n","<div class=\"hw\">fēlīciter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[felix<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 豊かに.</div><div class=\"def\"><num>②</num> さい先よく, 都合よく</div><div class=\"ex\"><i>obtestatus deos, ut ea res legioni ～ eveniret</i> (<author>C<small>AES</small></author>)<span class=\"ext\">そのことが軍団に幸いするように神々に祈って.</span></div><div class=\"def\"><num>③</num> 幸運に, 幸福に</div><div class=\"ex\"><i>～ vivere</i> (<author>C<small>IC</small></author>)<span class=\"ext\">幸福に生きる.</span></div><div class=\"def\"><num>④</num> 成功して.</div>\r\n","<div class=\"hw\">fēlīcitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[felix<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 肥沃, 多産.</div><div class=\"def\"><num>②</num> 幸運, 幸福.</div>\r\n","<div class=\"hw\">fēmella</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[femina]</div><div class=\"def\">若い女.</div>\r\n","<div class=\"hw\">fēmellārius</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>m</i></div><div class=\"ori\">[↑<a href=\"entry://fēmella\">fēmella</a>]</div><div class=\"def\">若い女の尻を追い回す者, 女たらし.</div>\r\n","<div class=\"hw\">fēmina</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\"><num>①</num> 女, 女性.</div><div class=\"def\"><num>②</num> (動物の)雌.</div>\r\n","<div class=\"hw\">fēminal</div><div class=\"pos\">-ālis, <i>n</i></div><div class=\"ori\">[↑<a href=\"entry://fēmina\">fēmina</a>]</div><div class=\"def\">女性外陰部.</div>\r\n","<div class=\"hw\">fēmineus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[femina]</div><div class=\"def\"><num>①</num> 女の, 女性の;女らしい.</div><div class=\"def\"><num>②</num> めめしい, 柔弱な.</div>\r\n","<div class=\"hw\">fēminīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[femina]</div><div class=\"def\"><num>①</num> 女の;女らしい.</div><div class=\"def\"><num>②</num> 〘文〙女性の.</div>\r\n","<div class=\"hw\">fēminīnē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↓<a href=\"entry://fēminīnus\">fēminīnus</a>]</div><div class=\"def\">〘文〙女性形で.</div>\r\n","<div class=\"hw\">fēminō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>intr</i></div><div class=\"ori\">[femina]</div><div class=\"def\">(女性が)自慰を行なう.</div>\r\n","<div class=\"hw\">fēnebris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">=<a href=\"entry://faenebris\">faenebris</a>.</div>\r\n","<div class=\"hw\">fēner-</div><div class=\"def\">⇒faener-.</div>\r\n","<div class=\"hw\">fēneus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://faeneus\">faeneus</a>.</div>\r\n","<div class=\"hw\">fēnicul-</div><div class=\"def\">⇒faenicul-.</div>\r\n","<div class=\"hw\">fēnu-</div><div class=\"def\">⇒faenu-.</div>\r\n","<div class=\"hw\">fēnārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://faenārius\">faenarius</a>.</div>\r\n","<div class=\"hw\">fēnīlia</div><div class=\"pos\">-ium, <i>n pl</i></div><div class=\"def\">=<a href=\"entry://faenīlia\">faenilia</a>.</div>\r\n","<div class=\"hw\">fēriae</div><div class=\"pos\">-ārum, <i>f pl</i></div><div class=\"ori\">[<i>cf. </i> festus]</div><div class=\"def\"><num>①</num> 祝日, 祭日.</div><div class=\"def\"><num>②</num> 休日, 休息.</div>\r\n","<div class=\"hw\">fērior</div><div class=\"pos\">-ārī -ātus sum, <i>intr dep</i></div><div class=\"ori\">[feriae]</div><div class=\"def\">仕事を休む, 休日にする.</div>\r\n","<div class=\"hw\">fēriāticus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://fēriae\">fēriae</a>]</div><div class=\"def\">祝日の.</div>\r\n","<div class=\"hw\">fēriātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[ferior]</div><div class=\"def\">休日の, ひまな.</div>\r\n","<div class=\"hw\">Fērālia</div><div class=\"pos\">-ium, <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://fērālis\">fērālis</a>]</div><div class=\"def\">死者の祭《2月21日に行なわれた》.</div>\r\n","<div class=\"hw\">fērālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\"><num>①</num> 死者の, 死体の.</div><div class=\"def\"><num>②</num> 死をもたらす, 致命的な, 破滅的な.</div><div class=\"def\"><num>③</num> 陰鬱な.</div>\r\n","<div class=\"hw\">Fērōnia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">〘神話〙フェーローニア《Italia の古い女神;解放奴隷の守護神》.</div>\r\n","<div class=\"hw\">fēta</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[fetus]</div><div class=\"def\">母獣.</div>\r\n","<div class=\"hw\">fēteō</div><div class=\"pos\">-ēre, <i>intr</i></div><div class=\"def\">=<a href=\"entry://foeteō\">foeteo</a>.</div>\r\n","<div class=\"hw\">fētidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://foetidus\">foetidus</a>.</div>\r\n","<div class=\"hw\">fētiālis<SUP>1</SUP></div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">外交担当神官の.</div><hr><div class=\"hw\">fētiālis<SUP>2</SUP></div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\">(ローマ人の代表として宣戦・講和などにあたった)外交担当神官団の一人.</div>\r\n","<div class=\"hw\">fētor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"def\">=<a href=\"entry://foetor\">foetor</a>.</div>\r\n","<div class=\"hw\">fētus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>cf. </i> fecundus, felix<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 出産したばかりの.</div><div class=\"def\"><num>②</num> 妊娠している.</div><div class=\"def\"><num>③</num> 実り豊かな, 多産の;豊富な 〈re〉.</div><hr><div class=\"hw\">fētus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> 分娩, 出産.</div><div class=\"def\"><num>②</num> 実を結ぶこと.</div><div class=\"def\"><num>③</num> 子.</div><div class=\"def\"><num>④</num> 実, 若枝;産物.</div>\r\n","<div class=\"hw\">fētālia</div><div class=\"pos\">-ium, <SUP>◇</SUP><i>n pl</i></div><div class=\"ori\">[fetus]</div><div class=\"def\">誕生日.</div>\r\n","<div class=\"hw\">fētālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[fetus]</div><div class=\"def\">〘生物〙胎児の.</div>\r\n","<div class=\"hw\">fētō</div><div class=\"pos\">-āre, <i>intr</i>, <i>tr</i></div><div class=\"ori\">[fetus]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>intr</i>)(鳥が)卵をかえす.</div><div class=\"def\"><num0>Ⅱ</num0> <SUP>◇</SUP>(<i>tr</i>)妊娠させる.</div>\r\n","<div class=\"hw\">fētōsus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[fetus]</div><div class=\"def\">多産の.</div>\r\n","<div class=\"hw\">fētūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↓<a href=\"entry://fētus\">fētus<SUP>1</SUP></a>]</div><div class=\"def\"><num>①</num> 子を産むこと, 繁殖.</div><div class=\"def\"><num>②</num> 子.</div>\r\n","<div class=\"hw\">fī<SUP>1</SUP></div><div class=\"pos\"><i>int</i></div><div class=\"def\">=<a href=\"entry://phȳ\">phy</a>《嫌悪・不快感を表わす》.</div><hr><div class=\"hw\">fī<SUP>2</SUP></div><div class=\"pos\">2 <i>sg impr pr</i></div><div class=\"def\">⇒<a href=\"entry://fīō\">fio</a>.</div>\r\n","<div class=\"hw\">fībula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[<i>cf. </i> figo]</div><div class=\"def\"><num>①</num> 〘建〙締め金.</div><div class=\"def\"><num>②</num> 留め針.</div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘解〙腓骨.</div>\r\n","<div class=\"hw\">fībulāris</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://fībula\">fībula</a>]</div><div class=\"def\">〘解〙腓骨の.</div>\r\n","<div class=\"hw\">fībulō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[fibula]</div><div class=\"def\"><num>①</num> 結び合わせる.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 留め金を付ける.</div>\r\n","<div class=\"hw\">fīcolea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[ficula]</div><div class=\"def\">イチジクの木で作った杖.</div>\r\n","<div class=\"hw\">Fīcolensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">=<a href=\"entry://Fīculensis\">Ficulensis</a>.</div>\r\n","<div class=\"hw\">fīcula</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[ficus]</div><div class=\"def\">〘植〙(小さな)イチジク.</div>\r\n","<div class=\"hw\">Fīculea</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">フィークレア《ローマ市北東の Sabini 族の町》.</div>\r\n","<div class=\"hw\">Fīculensis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"def\">Ficulea の.</div><div class=\"hw2\"><b>Fīculensēs</b></div><div class=\"pos2\">-ium, <i>m pl</i></div><div class=\"def2\">Ficulea の住民.</div>\r\n","<div class=\"hw\">Fīculeātēs</div><div class=\"pos\">-ium, <i>m pl</i></div><div class=\"def\">=<a href=\"entry://Fīculensis\">Ficulenses</a>.</div>\r\n","<div class=\"hw\">fīculnea</div><div class=\"pos\">-ae, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://fīculneus\">fīculneus</a>]</div><div class=\"def\">〘植〙イチジクの木.</div>\r\n","<div class=\"hw\">fīculneus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://fīculnus\">ficulnus</a>.</div>\r\n","<div class=\"hw\">fīculnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://fīcus\">fīcus</a>]</div><div class=\"def\">イチジク(の木)の.</div>\r\n","<div class=\"hw\">fīcus</div><div class=\"pos\">-ī [-ūs], <i>f</i></div><div class=\"def\"><num>①</num> 〘植〙イチジクの木.</div><div class=\"def\"><num>②</num> 〘植〙イチジク.</div><div class=\"def\"><num>③</num> 〘病〙痔(核).</div>\r\n","<div class=\"hw\">Fīcāna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">フィーカーナ《Ostia 近くの Latium の小さな町》.</div>\r\n","<div class=\"hw\">fīcārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ficus]</div><div class=\"def\">イチジクの.</div>\r\n","<div class=\"hw\">fīcēdula</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[ficus]</div><div class=\"def\">〘鳥〙ムシクイ.</div>\r\n","<div class=\"hw\">fīcētum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[ficus]</div><div class=\"def\">イチジク園.</div>\r\n","<div class=\"hw\">fīcōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[ficus]</div><div class=\"def\">痔疾にかかっている.</div>\r\n","<div class=\"hw\">fīdens</div><div class=\"pos\">-entis, <i>adj</i>(<i>prp</i>)</div><div class=\"ori\">[fido]</div><div class=\"def\">大胆な, 自信に満ちた.</div>\r\n","<div class=\"hw\">fīdenter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://fīdens\">fīdens</a>]</div><div class=\"def\">自信をもって, 大胆に.</div>\r\n","<div class=\"hw\">fīdentia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[fidens]</div><div class=\"def\">自信, 確信.</div>\r\n","<div class=\"hw\">Fīdentia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">フィーデンティア《Gallia Cisalpina の町》.</div>\r\n","<div class=\"hw\">fīdus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[<i>cf. </i> fido, fides<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 忠実な, 誠実な.</div><div class=\"def\"><num>②</num> 信頼できる, 確かな.</div>\r\n","<div class=\"hw\">fīdāmen</div><div class=\"pos\">-minis, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[fido]</div><div class=\"def\">信頼.</div>\r\n","<div class=\"hw\">fīdē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[fidus]</div><div class=\"def\">忠実に.</div>\r\n","<div class=\"hw\">Fīdēnae</div><div class=\"pos\">-ārum, <i>f pl</i>, <B>Fīdēna</B> -ae, <i>f</i></div><div class=\"def\">フィーデーナエ《ローマ市の北, Tiberis 河畔の町》.</div>\r\n","<div class=\"hw\">Fīdēnās</div><div class=\"pos\">-ātis, <i>adj</i></div><div class=\"def\">Fidenae の.</div><div class=\"hw2\"><b>Fīdēnātēs</b></div><div class=\"pos2\">-ium, <i>m pl</i></div><div class=\"def2\">Fidenae の住民.</div>\r\n","<div class=\"hw\">fīdō</div><div class=\"pos\">-ere fīsus sum, <i>intr</i></div><div class=\"ori\">[<i>cf. </i> fidus]</div><div class=\"def\"><num>①</num> 信頼する 〈+<i>dat</i> [<i>abl</i>]〉</div><div class=\"ex\"><i>puer sibi fidens</i> (<author>C<small>IC</small></author>)<span class=\"ext\">自信のある少年.</span></div><div class=\"def\"><num>②</num> 自信をもって...する 〈+<i>inf</i>〉.</div>\r\n","<div class=\"hw\">fīdūcia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://fīdō\">fīdō</a>]</div><div class=\"def\"><num>①</num> 信頼 〈alcis rei〉.</div><div class=\"def\"><num>②</num> 自信, 大胆さ.</div><div class=\"def\"><num>③</num> 確実性.</div><div class=\"def\"><num>④</num> 〘法〙信託, 抵当.</div>\r\n","<div class=\"hw\">fīdūciālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↑<a href=\"entry://fīdūcia\">fīdūcia</a>]</div><div class=\"def\">確信している;信頼している.</div>\r\n","<div class=\"hw\">fīdūciāliter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://fīdūciālis\">fīdūciālis</a>]</div><div class=\"def\">自信をもって.</div>\r\n","<div class=\"hw\">fīdūciārius<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fiducia]</div><div class=\"def\"><num>①</num> 〘法〙受託者の;信託の.</div><div class=\"def\"><num>②</num> 委託された.</div><hr><div class=\"hw\">fīdūciārius<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">《碑》〘法〙受託者, 被信託者.</div>\r\n","<div class=\"hw\">fīdūciō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[fiducia]</div><div class=\"def\">《碑》抵当に入れる.</div>\r\n","<div class=\"hw\">fīgō</div><div class=\"pos\">-ere fixī fixum [fictum], <i>tr</i></div><div class=\"def\"><num>①</num> 固定する, 結びつける 〈alqm [alqd];alqd in re;alqd in [ad] alqd;alqd re〉</div><div class=\"ex\"><i>figere alqm cruci [in crucem]</i> (<author>Q<small>UINT</small> [C<small>IC</small>]</author>)<span class=\"ext\">ある人をはりつけにする.</span></div><div class=\"def\"><num>②</num> 掛ける, つるす.</div><div class=\"def\"><num>③</num> 掲示する.</div><div class=\"def\"><num>④</num> 立てる, 据える</div><div class=\"ex\"><i>figere moenia</i> (<author>O<small>V</small></author>)<span class=\"ext\">城壁を築く.</span></div><div class=\"def\"><num>⑤</num> 刻みつける</div><div class=\"ex\"><i>figere alqd in animo</i> (<author>C<small>IC</small></author>)<span class=\"ext\">あることを心に銘記する.</span></div><div class=\"def\"><num>⑥</num> 差し込む, 突っ込む 〈alqd in re [alqd]〉.</div><div class=\"def\"><num>⑦</num> (押して)つける</div><div class=\"ex\"><i>figere oscula peregrinae terrae</i> (<author>O<small>V</small></author>)<span class=\"ext\">異国の大地に口づけする.</span></div><div class=\"def\"><num>⑧</num> じっと向ける 〈alqd in re [alqd];alqd re〉</div><div class=\"ex\"><i>figere oculos in terram</i> (<author>L<small>IV</small></author>)<span class=\"ext\">地面をじっと見つめる.</span></div><div class=\"def\"><num>⑨</num> 突き刺す, 刺し貫く 〈alqm [alqd] re〉.</div>\r\n","<div class=\"hw\">fīlia</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[filius]</div><div class=\"def\">娘.</div>\r\n","<div class=\"hw\">fīliaster</div><div class=\"pos\">-trī, <i>m</i></div><div class=\"ori\">[filius]</div><div class=\"def\">《碑》義理の息子.</div>\r\n","<div class=\"hw\">fīliastra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[filia]</div><div class=\"def\">《碑》義理の娘.</div>\r\n","<div class=\"hw\">fīliola</div><div class=\"pos\">-ae, <i>f dim</i></div><div class=\"ori\">[filia]</div><div class=\"def\">(小さな)娘.</div>\r\n","<div class=\"hw\">fīliolus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[↓<a href=\"entry://fīlius\">fīlius</a>]</div><div class=\"def\">(小さな)息子.</div>\r\n","<div class=\"hw\">fīlius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> 息子</div><div class=\"ex\"><i>～ familiae [familias]</i> (<author>C<small>IC</small></author>)<span class=\"ext\">父権の下にある息子</span></div><div class=\"ex\"><i>Fortunae ～</i> (<author>H<small>OR</small></author>)<span class=\"ext\">幸運児, 果報者</span></div><div class=\"ex\"><i>terrae ～</i> (<author>C<small>IC</small></author>)<span class=\"ext\">どこの馬の骨やらわからぬ男, 無名の者.</span></div><div class=\"def\"><num>②</num> (<i>pl</i>)子供たち.</div>\r\n","<div class=\"hw\">fīliālis<SUP>1</SUP></div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[filius]</div><div class=\"def\">子としての.</div><hr><div class=\"hw\">fīliālis<SUP>2</SUP></div><div class=\"pos\">-is, <SUP>◇</SUP><i>f</i></div><div class=\"def\">(<i>sc. </i> ecclesia)支聖堂.</div>\r\n","<div class=\"hw\">fīlum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"def\"><num>①</num> 糸</div><div class=\"ex\"><i>filo pendere</i> (<author>O<small>V</small></author>)<span class=\"ext\">危機一髪[風前の灯]である.</span></div><div class=\"def\"><num>②</num> 糸状のもの, ひも.</div><div class=\"def\"><num>③</num> (<i>pl</i>)(楽器の)弦.</div><div class=\"def\"><num>④</num> (Parcae が紡ぐ)運命の糸, 寿命.</div><div class=\"def\"><num>⑤</num> (話の)筋道, 構成.</div><div class=\"def\"><num>⑥</num> 形状;体格.</div>\r\n","<div class=\"hw\">fīlātim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[filum]</div><div class=\"def\">糸を1本ずつ.</div>\r\n","<div class=\"hw\">fīlō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[filum]</div><div class=\"def\">紡ぐ.</div>\r\n","<div class=\"hw\">fīniens</div><div class=\"pos\">-entis, <i>m</i>(<i>prp</i>)</div><div class=\"ori\">[↓<a href=\"entry://fīniō\">fīniō</a>]</div><div class=\"def\">(<i>sc. </i> orbis)地平線.</div>\r\n","<div class=\"hw\">fīnis</div><div class=\"pos\">-is, <i>m</i>(<i>f</i>)</div><div class=\"def\"><num>①</num> 境界(線).</div><div class=\"def\"><num>②</num> (<i>pl</i>)領域, 領土.</div><div class=\"def\"><num>③</num> 限度, 限界</div><div class=\"ex\"><i>fine</i> 〈+<i>gen</i>〉<span class=\"ext\">...まで</span></div><div class=\"ex\"><i>fine genūs</i> (<author>O<small>V</small></author>)<span class=\"ext\">膝まで.</span></div><div class=\"def\"><num>④</num> 目的, 目標.</div><div class=\"def\"><num>⑤</num> 極度, 頂点</div><div class=\"ex\"><i>～ bonorum</i> (<author>C<small>IC</small></author>)<span class=\"ext\">〘哲〙最高善.</span></div><div class=\"def\"><num>⑥</num> 終わり, 結末</div><div class=\"ex\"><i>finem facere</i> 〈+<i>gen</i> [<i>dat</i>]〉<span class=\"ext\">あることの結末をつける, 片付ける</span></div><div class=\"ex\"><i>loquendi finem facere</i> (<author>C<small>AES</small></author>)<span class=\"ext\">会談を打ち切る.</span></div><div class=\"def\"><num>⑦</num> 臨終, 死.</div>\r\n","<div class=\"hw\">fīnitimus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[finis]</div><div class=\"def\"><num>①</num> 隣接した, 近隣の 〈alci〉.</div><div class=\"def\"><num>②</num> 同族の, 同類の.</div>\r\n","<div class=\"hw\">fīnitimī</div><div class=\"pos\">-ōrum, <i>m pl</i></div><div class=\"ori\">[↓<a href=\"entry://fīnitimus\">fīnitimus</a>]</div><div class=\"def\">近隣の人々.</div>\r\n","<div class=\"hw\">fīnitumus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://fīnitimus\">finitimus</a>.</div>\r\n","<div class=\"hw\">fīniō</div><div class=\"pos\">-īre -īvī [-iī] -ītum, <i>tr</i>, <i>intr</i></div><div class=\"ori\">[↓<a href=\"entry://fīnis\">fīnis</a>]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>tr</i>)</div><div class=\"def\"><num>①</num> 境界を定める, 限定する</div><div class=\"ex\"><i>populi Romani imperium Rhenus finit</i> (<author>C<small>AES</small></author>)<span class=\"ext\">ローマ国民の支配は Rhenus 川が限界だ.</span></div><div class=\"def\"><num>②</num> 制限[抑制]する</div><div class=\"ex\"><i>an potest cupiditas finiri?</i> (<author>C<small>IC</small></author>)<span class=\"ext\">欲望に限度はあるのだろうか.</span></div><div class=\"def\"><num>③</num> 記述[描写]する, 定義する.</div><div class=\"def\"><num>④</num> 終える</div><div class=\"ex\"><i>vitam [animam] finire</i> (<author>O<small>V</small></author>)<span class=\"ext\">生涯を終える, 死ぬ.</span></div><div class=\"def\"><num>⑤</num> (<i>pass</i>)終わる;死ぬ.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>intr</i>)絶える;死ぬ.</div>\r\n","<div class=\"hw\">fīnālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[finis]</div><div class=\"def\"><num>①</num> 境界の.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 終局[究極]の, 最後の</div><div class=\"ex\"><i>causa ～</i><span class=\"ext\">〘哲〙(アリストテレス哲学の)目的因.</span></div>\r\n","<div class=\"hw\">fīnāliter</div><div class=\"pos\"><SUP>◇</SUP><i>adv</i></div><div class=\"ori\">[↑<a href=\"entry://fīnālis\">fīnālis</a>]</div><div class=\"def\">ついに, 最後に.</div>\r\n","<div class=\"hw\">fīnītiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[finio]</div><div class=\"def\"><num>①</num> 境界(線).</div><div class=\"def\"><num>②</num> 制限.</div><div class=\"def\"><num>③</num> 定義.</div><div class=\"def\"><num>④</num> 規則.</div><div class=\"def\"><num>⑤</num> 終わり;死.</div>\r\n","<div class=\"hw\">fīnītor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[finio]</div><div class=\"def\"><num>①</num> 境界を定める者, 測量士.</div><div class=\"def\"><num>②</num> 終わらせる者.</div><div class=\"def\"><num>③</num> </div><div class=\"ex\"><i>circulus ～</i> (<author>S<small>EN</small></author>)<span class=\"ext\">地平[水平]線.</span></div>\r\n","<div class=\"hw\">fīnītus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[finio]</div><div class=\"def\"><num>①</num> 限定された, 特定の.</div><div class=\"def\"><num>②</num> 〘修〙よくまとまった, 調和のとれた.</div>\r\n","<div class=\"hw\">fīnītē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[finitus]</div><div class=\"def\"><num>①</num> ある程度.</div><div class=\"def\"><num>②</num> とりわけ.</div>\r\n","<div class=\"hw\">fīnītīvus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[finio]</div><div class=\"def\">〘修〙</div><div class=\"def\"><num>①</num> 定義の[による].</div><div class=\"def\"><num>②</num> </div><div class=\"ex\"><i>modus ～</i> (<author>D<small>IOM</small></author>)<span class=\"ext\">直説法.</span></div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘文〙末尾の.</div>\r\n","<div class=\"hw\">fīsus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://fīdō\">fido</a>.</div>\r\n","<div class=\"hw\">fītilla</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"def\">(犠牲式の)供物用菓子.</div>\r\n","<div class=\"hw\">fīō</div><div class=\"pos\">fierī factus sum, <i>intr</i></div><div class=\"def\">(<a href=\"entry://faciō\">facio</a> の <i>pass</i> として用いられる)</div><div class=\"def\"><num>①</num> なる 〈ut [ne, quin] +<i>subj</i>〉;起こる;なされる</div><div class=\"ex\"><i>quid fiet</i> 〈+<i>dat [abl]〉?</i><span class=\"ext\">...はどうなるのだろうか</span></div><div class=\"ex\"><i>quid Tulliolā meā fiet?</i> (<author>C<small>IC</small></author>)<span class=\"ext\">私の Tulliola(Cicero の娘 Tullia の愛称)はどうなるのだろう</span></div><div class=\"ex\"><i>ut fieri solet</i> = <i>ut fit plerumque</i> (<author>C<small>IC</small></author>)<span class=\"ext\">たいていそうなるように</span></div><div class=\"ex\"><i>fit ut</i> (<author>C<small>IC</small></author>)<span class=\"ext\">...となる</span></div><div class=\"ex\"><i>fieri potest ut</i> (<author>C<small>IC</small></author>)<span class=\"ext\">...ということはありうる.</span></div><div class=\"def\"><num>②</num> 生まれる, 作られる;任命される.</div><div class=\"def\"><num>③</num> (...と)認められる, 評価される 〈+評価の <i>gen</i>〉.</div><div class=\"def\"><num>④</num> (<i>impers</i>)祭儀が行なわれる;供物がそなえられる 〈+<i>abl</i>〉.</div>\r\n","<div class=\"hw\">fōcilō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://fōculum\">fōculum</a>]</div><div class=\"def\"><num>①</num> 意識[健康]を回復させる, 元気づける.</div><div class=\"def\"><num>②</num> 大事にする, 気を配る.</div>\r\n","<div class=\"hw\">fōculum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[foveo]</div><div class=\"def\">炉, 火鉢.</div>\r\n","<div class=\"hw\">fōcāle</div><div class=\"pos\">-is, <i>n</i></div><div class=\"ori\">[fauces]</div><div class=\"def\">(病人や虚弱な人が用いた)スカーフ, 襟巻.</div>\r\n","<div class=\"hw\">fōdī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://fodiō\">fodio</a>.</div>\r\n","<div class=\"hw\">fōmentum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[foveo]</div><div class=\"def\"><num>①</num> (通例 <i>pl</i>)(温)湿布.</div><div class=\"def\"><num>②</num> 緩和するもの.</div>\r\n","<div class=\"hw\">fōmentātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[↓<a href=\"entry://fōmentō\">fōmentō</a>]</div><div class=\"def\">〘医〙(温)湿布.</div>\r\n","<div class=\"hw\">fōmentō</div><div class=\"pos\">-āre, <SUP>◇</SUP><i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://fōmentum\">fōmentum</a>]</div><div class=\"def\">(温)湿布する.</div>\r\n","<div class=\"hw\">fōmes</div><div class=\"pos\">-mitis, <i>m</i></div><div class=\"ori\">[foveo]</div><div class=\"def\">火口<SUB>ほくち</SUB>, たきつけ.</div>\r\n","<div class=\"hw\">fōtus<SUP>1</SUP></div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://foveō\">foveo</a>.</div><hr><div class=\"hw\">fōtus<SUP>2</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\"><num>①</num> <SUP>◇</SUP> 温めること.</div><div class=\"def\"><num>②</num> 〘医〙温罨法<SUB>あんぽう</SUB>.</div>\r\n","<div class=\"hw\">fōvī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://foveō\">foveo</a>.</div>\r\n","<div class=\"hw\">Fūcinus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">フーキヌス《イタリア中部の湖;現 Lago Fucino》.</div>\r\n","<div class=\"hw\">fūcus<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\"><num>①</num> (赤[紫]色の染料が作られる)地衣類の植物《リトマスゴケなど》.</div><div class=\"def\"><num>②</num> 赤色[紫色]の染料;化粧品.</div><div class=\"def\"><num>③</num> 赤色, 紫色.</div><div class=\"def\"><num>④</num> 蜂蝋<SUB>はちろう</SUB>, プロポリス.</div><div class=\"def\"><num>⑤</num> 見せかけ, ごまかし;飾りたてること.</div><hr><div class=\"hw\">fūcus<SUP>2</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">雄バチ.</div>\r\n","<div class=\"hw\">fūcātus</div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[fuco]</div><div class=\"def\"><num>①</num> 染められた, 人工の</div><div class=\"ex\"><i>naturalis, non ～ nitor</i> (<author>C<small>IC</small></author>)<span class=\"ext\">天然の, 人工のものではない輝き.</span></div><div class=\"def\"><num>②</num> 本物でない, にせの.</div>\r\n","<div class=\"hw\">fūcō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[fucus<SUP>1</SUP>]</div><div class=\"def\"><num>①</num> 着色する, 染める.</div><div class=\"def\"><num>②</num> 化粧する.</div><div class=\"def\"><num>③</num> 装飾する, 粉飾する.</div>\r\n","<div class=\"hw\">fūcōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://fūcus\">fūcus<SUP>1</SUP></a>]</div><div class=\"def\">偽りの, にせの.</div>\r\n","<div class=\"hw\">fūdī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://fundō\">fundo<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">Fūfidius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">フーフィディウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">Fūfius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">フーフィウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">fūgī</div><div class=\"pos\"><i>pf</i></div><div class=\"def\">⇒<a href=\"entry://fugiō\">fugio</a>.</div>\r\n","<div class=\"hw\">fūlīginātus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://fūlīgō\">fūlīgō</a>]</div><div class=\"def\">黒粉で塗られた.</div>\r\n","<div class=\"hw\">fūlīgō</div><div class=\"pos\">-ginis, <i>f</i></div><div class=\"ori\">[<i>cf. </i> fumus]</div><div class=\"def\"><num>①</num> すす.</div><div class=\"def\"><num>②</num> まゆ墨.</div>\r\n","<div class=\"hw\">fūmescō</div><div class=\"pos\">-ere, <SUP>◇</SUP><i>intr</i></div><div class=\"ori\">[fumus]</div><div class=\"def\">煙を吐く.</div>\r\n","<div class=\"hw\">fūmeus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fumus]</div><div class=\"def\">煙の多い, 煙っている.</div>\r\n","<div class=\"hw\">fūmidus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://fūmeus\">fumeus</a>.</div>\r\n","<div class=\"hw\">fūmifer</div><div class=\"pos\">-fera -ferum, <i>adj</i></div><div class=\"ori\">[fumus/fero]</div><div class=\"def\">《詩》煙を出している.</div>\r\n","<div class=\"hw\">fūmificus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fumus/facio]</div><div class=\"def\">煙を出している.</div>\r\n","<div class=\"hw\">fūmificō</div><div class=\"pos\">-āre, <i>intr</i></div><div class=\"ori\">[fumus/facio]</div><div class=\"def\">(香をたいて)煙を出す.</div>\r\n","<div class=\"hw\">fūmigābundus</div><div class=\"pos\">-a -um, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://fūmigō\">fūmigō</a>]</div><div class=\"def\">煙を出している.</div>\r\n","<div class=\"hw\">fūmigō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i>, <i>tr</i></div><div class=\"ori\">[fumus/ago]</div><div class=\"def\"><num0>Ⅰ</num0> (<i>intr</i>)煙を出す, 煙る.</div><div class=\"def\"><num0>Ⅱ</num0> (<i>tr</i>)煙らせる, 煙でいぶす.</div>\r\n","<div class=\"hw\">fūmus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">煙;蒸気</div><div class=\"ex\"><i>fumos vendere</i> (<author>M<small>ART</small></author>)<span class=\"ext\">空約束をする, ほらを吹く.</span></div>\r\n","<div class=\"hw\">fūmāriolum</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n dim</i></div><div class=\"ori\">[↓<a href=\"entry://fūmārium\">fūmārium</a>]</div><div class=\"def\">噴火口.</div>\r\n","<div class=\"hw\">fūmārium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[fumus]</div><div class=\"def\">(ぶどう酒を熟成させる)燻煙室.</div>\r\n","<div class=\"hw\">fūmātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[fumo]</div><div class=\"def\">煙でいぶすこと.</div>\r\n","<div class=\"hw\">fūmō</div><div class=\"pos\">-āre -āvī -ātum, <i>intr</i></div><div class=\"ori\">[fumus]</div><div class=\"def\">煙る, 煙を出す.</div>\r\n","<div class=\"hw\">fūmōsus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[↓<a href=\"entry://fūmus\">fūmus</a>]</div><div class=\"def\"><num>①</num> 煙っている, 煙の多い.</div><div class=\"def\"><num>②</num> 煙でいぶした, 燻製の.</div>\r\n","<div class=\"hw\">fūnambulus</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"ori\">[funis/ambulo]</div><div class=\"def\">綱渡り芸人.</div>\r\n","<div class=\"hw\">fūnebria</div><div class=\"pos\">-ium, <i>n pl</i></div><div class=\"ori\">[↓<a href=\"entry://fūnebris\">fūnebris</a>]</div><div class=\"def\">葬儀.</div>\r\n","<div class=\"hw\">fūnebris</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[funus]</div><div class=\"def\"><num>①</num> 葬式の, 葬送の.</div><div class=\"def\"><num>②</num> 死をもたらす, 破壊的な.</div>\r\n","<div class=\"hw\">fūnereus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">=<a href=\"entry://fūnebris\">funebris</a>.</div>\r\n","<div class=\"hw\">fūnerālis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[funus]</div><div class=\"def\">葬儀の.</div>\r\n","<div class=\"hw\">fūnerārius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[funus]</div><div class=\"def\">葬儀の.</div>\r\n","<div class=\"hw\">fūnerātiō</div><div class=\"pos\">-ōnis, <SUP>◇</SUP><i>f</i></div><div class=\"ori\">[funero]</div><div class=\"def\">葬儀, 埋葬.</div>\r\n","<div class=\"hw\">fūnerātīcium</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://fūnerātīcius\">fūnerātīcius</a>]</div><div class=\"def\">《碑》葬儀費用.</div>\r\n","<div class=\"hw\">fūnerātīcius</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[funus]</div><div class=\"def\">葬儀に関する.</div>\r\n","<div class=\"hw\">fūnerō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[funus]</div><div class=\"def\"><num>①</num> 埋葬する, 葬式をする.</div><div class=\"def\"><num>②</num> 殺す.</div>\r\n","<div class=\"hw\">fūnestus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[funus]</div><div class=\"def\"><num>①</num> 死をもたらす, 破滅させる.</div><div class=\"def\"><num>②</num> (死によって)けがれた;不吉な.</div><div class=\"def\"><num>③</num> 悲しむべき, 痛ましい.</div><div class=\"def\"><num>④</num> 悲しみに沈んだ.</div>\r\n","<div class=\"hw\">fūnestō</div><div class=\"pos\">-āre -āvī -ātum, <i>tr</i></div><div class=\"ori\">[↓<a href=\"entry://fūnestus\">fūnestus</a>]</div><div class=\"def\"><num>①</num> (殺人・流血で)けがす.</div><div class=\"def\"><num>②</num> 冒涜する, 名誉をけがす.</div><div class=\"def\"><num>③</num> 悲しみに沈ませる.</div>\r\n","<div class=\"hw\">fūniculus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[↓<a href=\"entry://fūnis\">fūnis</a>]</div><div class=\"def\"><num>①</num> 細いひも.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP>〘解〙索, 帯, 束</div><div class=\"ex\"><i>～ anterior</i><span class=\"ext\">前索</span></div><div class=\"ex\"><i>～ gracilis</i><span class=\"ext\">薄索</span></div><div class=\"ex\"><i>～ spermaticus</i><span class=\"ext\">精索</span></div><div class=\"ex\"><i>～ umbilicalis</i><span class=\"ext\">臍帯.</span></div><div class=\"def\"><num>③</num> <SUP>◇</SUP>〘植〙珠柄<SUB>しゅへい</SUB>.</div>\r\n","<div class=\"hw\">fūnis</div><div class=\"pos\">-is, <i>m</i></div><div class=\"def\">縄, 綱</div><div class=\"ex\"><i>funem sequi potius quam ducere</i> (<author>H<small>OR</small></author>)<span class=\"ext\">綱を引っぱる(=命令する)よりむしろ従う.</span></div>\r\n","<div class=\"hw\">fūnus</div><div class=\"pos\">-neris, <i>n</i></div><div class=\"def\"><num>①</num> 葬儀, 埋葬.</div><div class=\"def\"><num>②</num> 死体.</div><div class=\"def\"><num>③</num> 死.</div><div class=\"def\"><num>④</num> 没落, 破滅.</div>\r\n","<div class=\"hw\">fūnāle</div><div class=\"pos\">-is, <i>n</i></div><div class=\"ori\">[↓<a href=\"entry://fūnālis\">fūnālis</a>]</div><div class=\"def\"><num>①</num> 蝋たいまつ, ろうそく.</div><div class=\"def\"><num>②</num> 吊り燭台.</div>\r\n","<div class=\"hw\">fūnālis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[funis]</div><div class=\"def\">綱の, 綱につけられた</div><div class=\"ex\"><i>cereus ～</i> (<author>C<small>IC</small></author>)<span class=\"ext\">蝋たいまつ(=<a href=\"entry://fūnāle\">funale</a>)</span></div><div class=\"ex\"><i>equus ～</i> (<author>S<small>UET</small></author>)<span class=\"ext\">引き馬.</span></div>\r\n","<div class=\"hw\">fūnētum</div><div class=\"pos\">-ī, <i>n</i></div><div class=\"ori\">[funis]</div><div class=\"def\">(若枝を組み合わせた)縄格子.</div>\r\n","<div class=\"hw\">fūr</div><div class=\"pos\">fūris, <i>m</i>(<i>f</i>)</div><div class=\"def\"><num>①</num> 盗人, 泥棒.</div><div class=\"def\"><num>②</num> (奴隷に対するののしりのことばとして)ぬすっと, 悪党.</div>\r\n","<div class=\"hw\">fūrax</div><div class=\"pos\">-ācis, <i>adj</i></div><div class=\"ori\">[fur]</div><div class=\"def\">盗癖のある.</div>\r\n","<div class=\"hw\">Fūrius</div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">フーリウス《ローマ人の氏族名》.</div>\r\n","<div class=\"hw\">Fūriānus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"def\">Furius の.</div>\r\n","<div class=\"hw\">fūror<SUP>2</SUP></div><div class=\"pos\">-ārī -ātus sum, <i>tr dep</i></div><div class=\"ori\">[fur]</div><div class=\"def\"><num>①</num> 盗む, くすねる 〈alqd alci ;alqd ab alqo;alqd ex re〉.</div><div class=\"def\"><num>②</num> 不正に得る</div><div class=\"ex\"><i>furatus est civitatem</i> (<author>C<small>IC</small></author>)<span class=\"ext\">彼は市民権を詐取した.</span></div><div class=\"def\"><num>③</num> ひそかに引っ込める</div><div class=\"ex\"><i>fessos oculos furare labori</i> (<author>V<small>ERG</small></author>)<span class=\"ext\">疲れた目を労苦から遠ざけよ.</span></div>\r\n","<div class=\"hw\">fūrunculus</div><div class=\"pos\">-ī, <i>m dim</i></div><div class=\"ori\">[fur]</div><div class=\"def\"><num>①</num> こそ泥.</div><div class=\"def\"><num>②</num> 〘病〙癤<SUB>せつ</SUB>, フルンケル.</div>\r\n","<div class=\"hw jl\"><SUP>*</SUP>fūrāciter</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[furax]</div><div class=\"def\">(用例は <i>superl</i> fūrācissimē のみ)盗人のように.</div>\r\n","<div class=\"hw\">fūrācitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[furax]</div><div class=\"def\">盗癖.</div>\r\n","<div class=\"hw\">fūrātrīna</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[furor<SUP>2</SUP>]</div><div class=\"def\">盗み, 窃盗.</div>\r\n","<div class=\"hw\">fūrātus</div><div class=\"pos\">-a -um, <i>pp</i></div><div class=\"def\">⇒<a href=\"entry://fūror\">furor<SUP>2</SUP></a>.</div>\r\n","<div class=\"hw\">fūrīnus</div><div class=\"pos\">-a -um, <i>adj</i></div><div class=\"ori\">[fur]</div><div class=\"def\">盗人の.</div>\r\n","<div class=\"hw\">fūsiformis</div><div class=\"pos\">-is -e, <SUP>◇</SUP><i>adj</i></div><div class=\"ori\">[fusus<SUP>1</SUP>/forma]</div><div class=\"def\">〘解〙紡錘状の.</div>\r\n","<div class=\"hw\">fūsilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[fundo<SUP>2</SUP>]</div><div class=\"def\">溶けた;柔らかい.</div>\r\n","<div class=\"hw\">fūsiō</div><div class=\"pos\">-ōnis, <i>f</i></div><div class=\"ori\">[fundo<SUP>2</SUP>]</div><div class=\"def\">注ぐこと, 流出.</div>\r\n","<div class=\"hw\">fūsor</div><div class=\"pos\">-ōris, <i>m</i></div><div class=\"ori\">[fundo<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 注ぐ人.</div><div class=\"def\"><num>②</num> <SUP>◇</SUP> 鋳物師.</div>\r\n","<div class=\"hw\">fūsus<SUP>1</SUP></div><div class=\"pos\">-ī, <i>m</i></div><div class=\"def\">つむ, 紡錘.</div><hr><div class=\"hw\">fūsus<SUP>2</SUP></div><div class=\"pos\">-a -um, <i>adj</i>(<i>pp</i>)</div><div class=\"ori\">[fundo<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 広がった, 伸びた.</div><div class=\"def\"><num>②</num> だぶだぶの, たるんだ</div><div class=\"ex\"><i>fusum corpus</i> (<author>L<small>IV</small></author>)<span class=\"ext\">肥満した身体</span></div><div class=\"ex\"><i>toga fusa</i> (<author>S<small>UET</small></author>)<span class=\"ext\">ゆったりしたトガ.</span></div><div class=\"def\"><num>③</num> (文体が)冗長な, 散漫な.</div><hr><div class=\"hw\">fūsus<SUP>3</SUP></div><div class=\"pos\">-ūs, <i>m</i></div><div class=\"def\">注ぐこと.</div>\r\n","<div class=\"hw\">fūsē</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[fusus<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> 広範に, 広く.</div><div class=\"def\"><num>②</num> 詳細に, 十分に.</div><div class=\"def\"><num>③</num> 大ざっぱに.</div>\r\n","<div class=\"hw\">fūsōrium</div><div class=\"pos\">-ī, <SUP>◇</SUP><i>n</i></div><div class=\"ori\">[fundo<SUP>2</SUP>]</div><div class=\"def\">排水溝.</div>\r\n","<div class=\"hw\">fūsūra</div><div class=\"pos\">-ae, <i>f</i></div><div class=\"ori\">[fundo<SUP>2</SUP>]</div><div class=\"def\">鋳造.</div>\r\n","<div class=\"hw\">fūtile, futtile</div><div class=\"pos\"><i>adv</i>(<i>neut</i>)</div><div class=\"ori\">[↓<a href=\"entry://fūtilis\">fūtilis, futtilis</a>]</div><div class=\"def\">むなしく, むだに.</div>\r\n","<div class=\"hw\">fūtilis, futtilis</div><div class=\"pos\">-is -e, <i>adj</i></div><div class=\"ori\">[fundo<SUP>2</SUP>]</div><div class=\"def\"><num>①</num> こわれやすい, もろい.</div><div class=\"def\"><num>②</num> 役に立たない, 無益な.</div>\r\n","<div class=\"hw\">fūtilitās, futtilitās</div><div class=\"pos\">-ātis, <i>f</i></div><div class=\"ori\">[↑<a href=\"entry://fūtilis\">fūtilis, futtilis</a>]</div><div class=\"def\">むだ, 無益.</div>\r\n","<div class=\"hw\">fūtis</div><div class=\"pos\">-is, <i>f</i></div><div class=\"ori\">[fundo<SUP>2</SUP>]</div><div class=\"def\">水差し.</div>\r\n","<div class=\"hw\">fūtātim</div><div class=\"pos\"><i>adv</i></div><div class=\"ori\">[fundo<SUP>2</SUP>]</div><div class=\"def\">豊富に, たっぷり.</div>\r\n"]);
